function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutBackSoft(x) {
    const k = clamp01(x);
    const c1 = 1.15;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2);
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function bellEnvelope(p, start, end) {
    if (p <= start || p >= end) return 0;
    return Math.sin(Math.PI * ((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawMicroSproutLeaf(x, y, angle, length, fillCol, ink, lineW) {
    if (length <= 0.8) return;
    const hw = length * 0.42;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(length * 0.28, -hw, length * 0.78, -hw * 0.72, length, 0);
    ctx.bezierCurveTo(length * 0.78, hw * 0.72, length * 0.28, hw, 0, 0);
    ctx.closePath();
    ctx.fillStyle = fillCol;
    ctx.fill();
    ctx.lineWidth = lineW;
    ctx.strokeStyle = ink;
    ctx.stroke();
    ctx.restore();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (Deep Cosmic Emerald-Black, zero glow, zero edge border)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#040D0B");
  bgGrad.addColorStop(0.52, "#081B17");
  bgGrad.addColorStop(1, "#0D2923");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let lockAngle = 0;
  let irisOpen = 0;
  let scanPos = -1;
  let helixExpand = 0;
  let leafBud = 0;
  let sporeAlpha = 0;
  let levAmp = 0;
  let lockEmblemGlow = 0;

  if (currentScene === 0) {
    // Scene 0: Champagne Gold mechanical ring rotates to unlock -> 6 iris petals swing open smoothly -> vertical laser scans chamber
    lockAngle = smoothRange(sceneProgress, 0.04, 0.30) * (Math.PI / 6);
    irisOpen = easeOutBackSoft(clamp01((sceneProgress - 0.16) / 0.36));
    if (sceneProgress <= 0.16) irisOpen = 0;
    scanPos = (sceneProgress >= 0.42 && sceneProgress <= 0.92) ? (sceneProgress - 0.42) / 0.50 : -1;
    helixExpand = 0;
    leafBud = 0;
    sporeAlpha = 0;
    levAmp = 0;
    lockEmblemGlow = smoothRange(sceneProgress, 0.04, 0.30);
  } else if (currentScene === 1) {
    // Scene 1: Golden Core Seed levitates -> glowing jade-gold double helix expands & sprouts vibrant leaves + spores float inside chamber
    lockAngle = Math.PI / 6;
    irisOpen = 1.0;
    scanPos = -1;
    levAmp = bellEnvelope(sceneProgress, 0.02, 0.98) * minSide * 0.007;
    helixExpand = smoothRange(sceneProgress, 0.08, 0.46);
    leafBud = easeOutBackSoft(clamp01((sceneProgress - 0.28) / 0.36));
    if (sceneProgress <= 0.28) leafBud = 0;
    sporeAlpha = bellEnvelope(sceneProgress, 0.16, 0.94);
    lockEmblemGlow = 1.0;
  } else {
    // Scene 2: Helix condenses back into seed core -> aperture iris snap-locks shut -> lock collar rotates smoothly to t=0 rest
    lockAngle = (Math.PI / 6) * (1 - smoothRange(sceneProgress, 0.58, 0.92));
    irisOpen = 1.0 - smoothRange(sceneProgress, 0.34, 0.72);
    scanPos = -1;
    levAmp = 0;
    helixExpand = 1.0 - smoothRange(sceneProgress, 0.06, 0.40);
    leafBud = 1.0 - smoothRange(sceneProgress, 0.02, 0.32);
    sporeAlpha = 0;
    lockEmblemGlow = 1.0 - smoothRange(sceneProgress, 0.60, 0.94);
  }

  // 3. Layout Coordinates (Futuristic upright Bio-Vault capsule centered on canvas)
  const cx = width * 0.5;
  const cy = height * 0.50;
  const capW = minSide * 0.256;
  const capH = minSide * 0.396;
  const capRad = capW * 0.5;
  const strokeW = Math.max(2, minSide * 0.0052);
  const darkInk = "#030A08";

  // Pedestal dock feet anchored neatly at bottom of capsule
  const capTopY = cy - capH * 0.5;
  const capBotY = cy + capH * 0.5;
  roundedRectPath(cx - minSide * 0.145, capBotY - minSide * 0.008, minSide * 0.290, minSide * 0.018, minSide * 0.009);
  ctx.fillStyle = "#1E293B";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // 4. Capsule Armor Body & Titanium Structural Panel Lines
  roundedRectPath(cx - capW * 0.5, capTopY, capW, capH, capRad);
  const hullGrad = ctx.createLinearGradient(cx - capW * 0.5, capTopY, cx + capW * 0.5, capBotY);
  hullGrad.addColorStop(0, "#E2E8F0");
  hullGrad.addColorStop(0.52, "#94A3B8");
  hullGrad.addColorStop(1, "#475569");
  ctx.fillStyle = hullGrad;
  ctx.fill();

  // Subtle recessed dark tech bands strictly clipped inside outer capsule silhouette
  ctx.save();
  roundedRectPath(cx - capW * 0.5, capTopY, capW, capH, capRad);
  ctx.clip();

  // Top & Bottom Champagne Gold Accent Rings around Dome Caps
  ctx.fillStyle = "#0F172A";
  ctx.fillRect(cx - capW * 0.5, capTopY + minSide * 0.044, capW, minSide * 0.010);
  ctx.fillRect(cx - capW * 0.5, capBotY - minSide * 0.054, capW, minSide * 0.010);

  ctx.fillStyle = lerpColor([148, 163, 184], [253, 230, 138], 0.45 + 0.55 * lockEmblemGlow);
  ctx.fillRect(cx - capW * 0.5, capTopY + minSide * 0.046, capW, minSide * 0.005);
  ctx.fillRect(cx - capW * 0.5, capBotY - minSide * 0.052, capW, minSide * 0.005);

  // Lateral grip recess slots
  for (let side = -1; side <= 1; side += 2) {
    roundedRectPath(cx + side * (capW * 0.44) - minSide * 0.014, cy - minSide * 0.045, minSide * 0.028, minSide * 0.090, minSide * 0.007);
    ctx.fillStyle = "#334155";
    ctx.fill();
  }
  ctx.restore();

  // Outer Hull Border Stroke
  roundedRectPath(cx - capW * 0.5, capTopY, capW, capH, capRad);
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // 5. Central Bio-Chamber Interior (Drawn behind clipped 6-blade Aperture Iris)
  const apR = minSide * 0.096;
  ctx.beginPath();
  ctx.arc(cx, cy, apR, 0, Math.PI * 2);
  const chamberGrad = ctx.createLinearGradient(0, cy - apR, 0, cy + apR);
  chamberGrad.addColorStop(0, "#031511");
  chamberGrad.addColorStop(0.5, "#072620");
  chamberGrad.addColorStop(1, "#031511");
  ctx.fillStyle = chamberGrad;
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, apR - 1, 0, Math.PI * 2);
  ctx.clip();

  // 5a. Floating Bioluminescent Jade Spores inside Open Containment Glass
  if (sporeAlpha > 0.03) {
    for (let sp = 0; sp < 5; sp++) {
      const spProg = (cycleNorm * 6 + sp * 0.2) % 1;
      const sx = cx + Math.sin(sp * 2.1 + spProg * Math.PI * 2) * (apR * 0.56);
      const sy = lerp(cy + apR * 0.65, cy - apR * 0.65, spProg);
      const sa = Math.sin(Math.PI * spProg) * sporeAlpha * 0.85;
      if (sa > 0.04) {
        ctx.beginPath();
        ctx.arc(sx, sy, minSide * 0.0036, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(94, 234, 212, " + sa.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // 5b. Glowing Botanical Double Helix & Micro Leaves Rotating Around Core Axis (Scene 1)
  const levY = Math.sin(cycleNorm * Math.PI * 2 * 4) * levAmp;
  const seedCy = cy + levY;

  if (helixExpand > 0.02) {
    const hHalfH = apR * 0.72 * helixExpand;
    const hAmpX = minSide * 0.034 * helixExpand;
    const hRot = cycleNorm * Math.PI * 2 * 3;
    const steps = 22;

    // Two clean intertwined sinusoidal helix ribbons (Strand A: Jade, Strand B: Champagne Gold)
    for (let strand = 0; strand < 2; strand++) {
      const phaseShift = strand === 0 ? 0 : Math.PI;
      ctx.beginPath();
      for (let i = 0; i <= steps; i++) {
        const u = i / steps;
        const hy = lerp(seedCy + hHalfH, seedCy - hHalfH, u);
        const theta = u * Math.PI * 2.2 + hRot + phaseShift;
        const hx = cx + Math.sin(theta) * hAmpX;
        if (i === 0) ctx.moveTo(hx, hy);
        else ctx.lineTo(hx, hy);
      }
      ctx.lineWidth = Math.max(1.8, minSide * 0.0038 * helixExpand);
      ctx.strokeStyle = strand === 0 ? "#2DD4BF" : "#FDE68A";
      ctx.stroke();
    }

    // 4 Sprouting Micro Leaves along Outer Helix Bends (Strictly contained inside open porthole radius!)
    if (leafBud > 0.02) {
      const leafUs = [0.22, 0.44, 0.64, 0.82];
      for (let lu = 0; lu < leafUs.length; lu++) {
        const u = leafUs[lu];
        const sideShift = lu % 2 === 0 ? 0 : Math.PI;
        const theta = u * Math.PI * 2.2 + hRot + sideShift;
        const lx = cx + Math.sin(theta) * hAmpX;
        const ly = lerp(seedCy + hHalfH, seedCy - hHalfH, u);
        const dirSide = Math.sin(theta) >= 0 ? -0.35 : -Math.PI + 0.35;
        drawMicroSproutLeaf(lx, ly, dirSide, minSide * 0.020 * clamp01(leafBud), "#84CC16", darkInk, strokeW * 0.48);
      }
    }
  }

  // 5c. Central Luminous Bio-Seed Core Emblem (Crisp seed pod glowing gold-emerald)
  ctx.save();
  ctx.translate(cx, seedCy);
  const seedScale = 0.85 + 0.25 * clamp01(irisOpen);
  ctx.scale(seedScale, seedScale);

  const seedRx = minSide * 0.015;
  const seedRy = minSide * 0.023;
  ctx.beginPath();
  ctx.moveTo(0, -seedRy);
  ctx.bezierCurveTo(seedRx * 1.15, -seedRy * 0.25, seedRx * 1.05, seedRy * 0.75, 0, seedRy);
  ctx.bezierCurveTo(-seedRx * 1.05, seedRy * 0.75, -seedRx * 1.15, -seedRy * 0.25, 0, -seedRy);
  ctx.closePath();

  const sGrad = ctx.createLinearGradient(0, -seedRy, 0, seedRy);
  sGrad.addColorStop(0, "#FDE68A");
  sGrad.addColorStop(0.5, "#84CC16");
  sGrad.addColorStop(1, "#0F766E");
  ctx.fillStyle = sGrad;
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, strokeW * 0.62);
  ctx.strokeStyle = "#ECFDF5";
  ctx.stroke();

  // Tiny luminous vertical germ line inside seed core
  ctx.beginPath();
  ctx.moveTo(0, seedRy * 0.45);
  ctx.lineTo(0, -seedRy * 0.45);
  ctx.lineWidth = Math.max(1.2, minSide * 0.0024);
  ctx.strokeStyle = "#FEF9C3";
  ctx.stroke();
  ctx.restore();

  // 5d. Vertical Bioluminescent Laser Scanner Sweep inside Chamber (Scene 0)
  if (scanPos >= 0 && scanPos <= 1) {
    const sy = lerp(cy - apR * 0.92, cy + apR * 0.92, scanPos);
    const sAlpha = Math.sin(Math.PI * scanPos) * 0.95;
    ctx.beginPath();
    ctx.moveTo(cx - apR, sy);
    ctx.lineTo(cx + apR, sy);
    ctx.lineWidth = minSide * 0.0068;
    ctx.strokeStyle = "rgba(45, 212, 191, " + (sAlpha * 0.45).toFixed(3) + ")";
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(cx - apR, sy);
    ctx.lineTo(cx + apR, sy);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0026);
    ctx.strokeStyle = "rgba(204, 251, 241, " + sAlpha.toFixed(3) + ")";
    ctx.stroke();
  }

  // Subtle curved interior glass gleam highlight along left inner curve of porthole
  ctx.beginPath();
  ctx.arc(cx, cy, apR * 0.82, Math.PI * 0.65, Math.PI * 1.32);
  ctx.lineWidth = minSide * 0.0055;
  ctx.strokeStyle = "rgba(255, 255, 255, 0.14)";
  ctx.stroke();

  // 5e. Six Mechanical Titanium Aperture Iris Blades (True pivoting iris: seals 100% at t=0, retracts >= 86% clear at open!)
  const pivotR = apR * 1.04;
  const openSweep = clamp01(irisOpen) * 1.04;
  for (let b = 0; b < 6; b++) {
    const pAngle = (b * Math.PI) / 3;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.rotate(pAngle);
    ctx.translate(pivotR, 0);
    ctx.rotate(-openSweep);

    // Pure +Y sector petal relative to pivot (pivotR, 0):
    // Seals straight radial seam along (-pivotR, 0) -> (0,0) at angle 0, covers entire 60-deg wedge up to apR,
    // and swings completely outward beyond 0.86*apR when rotated by -openSweep!
    ctx.beginPath();
    ctx.moveTo(-pivotR, 0);
    ctx.lineTo(apR * 0.25, 0);
    ctx.lineTo(apR * 0.25, pivotR * 0.96);
    ctx.lineTo(-pivotR * 0.52, pivotR * 0.96);
    ctx.closePath();

    ctx.fillStyle = b % 2 === 0 ? "#475569" : "#334155";
    ctx.fill();
    ctx.lineWidth = Math.max(1.5, strokeW * 0.62);
    ctx.strokeStyle = "#94A3B8";
    ctx.stroke();

    ctx.restore();
  }

  // Champagne Gold Central Lock Cap Emblem when iris is closed cleanly (fades out softly as iris starts opening!)
  const centerLockAlpha = 1.0 - smoothRange(irisOpen, 0.0, 0.25);
  if (centerLockAlpha > 0.02) {
    ctx.save();
    ctx.globalAlpha = centerLockAlpha;
    ctx.beginPath();
    ctx.arc(cx, cy, minSide * 0.022, 0, Math.PI * 2);
    ctx.fillStyle = "#1E293B";
    ctx.fill();
    ctx.lineWidth = strokeW * 0.78;
    ctx.strokeStyle = "#FDE68A";
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(cx, cy, minSide * 0.010, 0, Math.PI * 2);
    ctx.fillStyle = lerpColor([253, 230, 138], [45, 212, 191], lockEmblemGlow);
    ctx.fill();
    ctx.restore();
  }

  ctx.restore(); // End chamber clip (keeps all 6 iris blades & interior contents crisp inside circular port!)

  // 6. Outer Mechanical Champagne Gold Aperture Lock Ring & 6 Symmetrical Locking Lugs
  const lockRingR = apR + minSide * 0.012;
  ctx.beginPath();
  ctx.arc(cx, cy, lockRingR, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.022;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, cy, lockRingR, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.014;
  ctx.strokeStyle = lerpColor([203, 213, 225], [253, 230, 138], 0.45 + 0.55 * lockEmblemGlow);
  ctx.stroke();

  // Inner dark circular separator rim around glass edge
  ctx.beginPath();
  ctx.arc(cx, cy, apR, 0, Math.PI * 2);
  ctx.lineWidth = Math.max(1.8, strokeW * 0.72);
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // 6 Rotating Mechanical Key Lugs mounted on the Champagne Gold Lock Collar
  ctx.save();
  ctx.translate(cx, cy);
  ctx.rotate(lockAngle);
  for (let l = 0; l < 6; l++) {
    ctx.rotate(Math.PI / 3);
    roundedRectPath(lockRingR - minSide * 0.010, -minSide * 0.007, minSide * 0.020, minSide * 0.014, minSide * 0.004);
    ctx.fillStyle = "#1E293B";
    ctx.fill();
    ctx.lineWidth = Math.max(1.2, strokeW * 0.48);
    ctx.strokeStyle = "#FDE68A";
    ctx.stroke();
  }
  ctx.restore();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutBackSoft(x) {
    const k = clamp01(x);
    const c1 = 1.15;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2);
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function bellEnvelope(p, start, end) {
    if (p <= start || p >= end) return 0;
    return Math.sin(Math.PI * ((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function tracePolylineTrim(pts, prog) {
    const p = clamp01(prog);
    if (p <= 0.005 || pts.length < 2) return null;
    let totalLen = 0;
    const segLens = [];
    for (let i = 0; i < pts.length - 1; i++) {
      const d = Math.hypot(pts[i + 1][0] - pts[i][0], pts[i + 1][1] - pts[i][1]);
      segLens.push(d);
      totalLen += d;
    }
    const targetDist = totalLen * p;
    let acc = 0;
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    let tip = [pts[0][0], pts[0][1]];
    for (let i = 0; i < segLens.length; i++) {
      const sl = segLens[i];
      if (acc + sl <= targetDist) {
        ctx.lineTo(pts[i + 1][0], pts[i + 1][1]);
        tip = [pts[i + 1][0], pts[i + 1][1]];
        acc += sl;
      } else {
        const rem = (targetDist - acc) / (sl || 1);
        tip = [lerp(pts[i][0], pts[i + 1][0], rem), lerp(pts[i][1], pts[i + 1][1], rem)];
        ctx.lineTo(tip[0], tip[1]);
        break;
      }
    }
    return tip;
  }

  function pointOnQuad(p0, pc, p1, u) {
    const om = 1 - u;
    return [
      om * om * p0[0] + 2 * om * u * pc[0] + u * u * p1[0],
      om * om * p0[1] + 2 * om * u * pc[1] + u * u * p1[1]
    ];
  }

  function drawVectorLeaf(x, y, angle, length, fillMain, fillDark, ink, lineW) {
    if (length <= 1) return;
    const halfW = length * 0.44;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(length * 0.30, -halfW, length * 0.78, -halfW * 0.70, length, 0);
    ctx.bezierCurveTo(length * 0.78, halfW * 0.70, length * 0.30, halfW, 0, 0);
    ctx.closePath();
    ctx.fillStyle = fillMain;
    ctx.fill();

    ctx.save();
    ctx.clip();
    ctx.fillStyle = fillDark;
    ctx.fillRect(0, 0, length, halfW);
    ctx.restore();

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(length * 0.30, -halfW, length * 0.78, -halfW * 0.70, length, 0);
    ctx.bezierCurveTo(length * 0.78, halfW * 0.70, length * 0.30, halfW, 0, 0);
    ctx.closePath();
    ctx.lineWidth = lineW;
    ctx.strokeStyle = ink;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(length * 0.1, 0);
    ctx.lineTo(length * 0.74, 0);
    ctx.lineWidth = Math.max(1.2, lineW * 0.65);
    ctx.strokeStyle = "rgba(236, 253, 245, 0.55)";
    ctx.stroke();
    ctx.restore();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (Dark Gunmetal Teal, zero glow, zero edge border)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#0A0F14");
  bgGrad.addColorStop(0.52, "#101B23");
  bgGrad.addColorStop(1, "#172733");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let rootCharge = 0.25;
  let trunkTrim = 0.15;
  let branchTrim = 0;
  let nodeReveal = 0;
  let leafBloom = 0;
  let arcAlpha = 0;
  let balanceWave = 0;
  let sweepRing = -1;
  let syncPulse = 0;

  if (currentScene === 0) {
    // Scene 0: Root core pulses bright -> trunk & PCB branches bloom bottom-to-top via trim-path -> canopy icons pop in
    rootCharge = 0.25 + 0.75 * smoothRange(sceneProgress, 0.04, 0.45);
    trunkTrim = 0.15 + 0.85 * smoothRange(sceneProgress, 0.12, 0.52);
    branchTrim = smoothRange(sceneProgress, 0.32, 0.78);
    nodeReveal = easeOutBackSoft(clamp01((sceneProgress - 0.54) / 0.34));
    if (sceneProgress <= 0.54) nodeReveal = 0;
    leafBloom = smoothRange(sceneProgress, 0.64, 0.96);
    arcAlpha = 0;
    balanceWave = 0;
    sweepRing = -1;
    syncPulse = 0;
  } else if (currentScene === 1) {
    // Scene 1: Energy nodes light up sequentially & exchange light packets along upper load-balancing arcs while leaves sway
    rootCharge = 1.0;
    trunkTrim = 1.0;
    branchTrim = 1.0;
    nodeReveal = 1.0;
    leafBloom = 1.0;
    arcAlpha = bellEnvelope(sceneProgress, 0.04, 0.96);
    balanceWave = sceneProgress;
    sweepRing = -1;
    syncPulse = 0;
  } else {
    // Scene 2: Unifying energy ring sweeps calmly across canopy -> smooth reverse drain back into resting root state
    sweepRing = (sceneProgress >= 0.05 && sceneProgress <= 0.55) ? (sceneProgress - 0.05) / 0.50 : -1;
    syncPulse = bellEnvelope(sceneProgress, 0.08, 0.52);
    arcAlpha = 0;
    balanceWave = 0;

    const drainRev = smoothRange(sceneProgress, 0.48, 0.92);
    leafBloom = 1.0 - smoothRange(sceneProgress, 0.44, 0.78);
    nodeReveal = 1.0 - smoothRange(sceneProgress, 0.50, 0.82);
    branchTrim = 1.0 - smoothRange(sceneProgress, 0.58, 0.88);
    trunkTrim = 1.0 - 0.85 * smoothRange(sceneProgress, 0.66, 0.94);
    rootCharge = 1.0 - 0.75 * drainRev;
  }

  // 3. Layout Coordinates (Balanced 45-degree PCB circuit tree with completely unobstructed icon bays)
  const cx = width * 0.5;
  const cy = height * 0.52;
  const rootY = cy + minSide * 0.215;
  const forkLowY = cy + minSide * 0.072;
  const nodeR = minSide * 0.042;
  const strokeW = Math.max(2, minSide * 0.0050);
  const darkInk = "#060A0E";

  const nodeTop = [cx, cy - minSide * 0.165];
  const nodeLeft = [cx - minSide * 0.175, cy - minSide * 0.025];
  const nodeRight = [cx + minSide * 0.175, cy - minSide * 0.025];
  const elbowL = [cx - minSide * 0.097, cy - minSide * 0.025];
  const elbowR = [cx + minSide * 0.097, cy - minSide * 0.025];

  // 4. Canopy Outer Unifying Energy Sweep Halo in Scene 2 (Rendered behind canopy hardware so zero crossing occlusion!)
  if (sweepRing >= 0 && sweepRing <= 1) {
    const canopyCenterY = cy - minSide * 0.070;
    const sweepR = minSide * lerp(0.04, 0.265, sweepRing);
    const swAlpha = Math.sin(Math.PI * sweepRing) * 0.78;
    if (swAlpha > 0.03) {
      ctx.beginPath();
      ctx.arc(cx, canopyCenterY, sweepR, 0, Math.PI * 2);
      ctx.lineWidth = minSide * 0.0065;
      ctx.strokeStyle = "rgba(16, 185, 129, " + swAlpha.toFixed(3) + ")";
      ctx.stroke();

      ctx.beginPath();
      ctx.arc(cx, canopyCenterY, sweepR * 0.86, 0, Math.PI * 2);
      ctx.lineWidth = minSide * 0.0030;
      ctx.strokeStyle = "rgba(34, 211, 238, " + (swAlpha * 0.75).toFixed(3) + ")";
      ctx.stroke();
    }
  }

  // 5. Grounded PCB Root Pedestal & Angled Anchor Root Traces
  roundedRectPath(cx - minSide * 0.16, rootY + minSide * 0.026, minSide * 0.32, minSide * 0.013, minSide * 0.0065);
  ctx.fillStyle = "#1E2D3B";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.0028);
  ctx.strokeStyle = "#334D66";
  ctx.stroke();

  // Root PCB side traces
  for (let side = -1; side <= 1; side += 2) {
    const rPts = [
      [cx, rootY],
      [cx + side * minSide * 0.045, rootY],
      [cx + side * minSide * 0.068, rootY + minSide * 0.024],
      [cx + side * minSide * 0.105, rootY + minSide * 0.024]
    ];
    ctx.beginPath();
    ctx.moveTo(rPts[0][0], rPts[0][1]);
    for (let i = 1; i < rPts.length; i++) ctx.lineTo(rPts[i][0], rPts[i][1]);
    ctx.lineWidth = minSide * 0.0085;
    ctx.strokeStyle = "#334155";
    ctx.stroke();

    // Terminal root solder pad
    ctx.beginPath();
    ctx.arc(rPts[3][0], rPts[3][1], minSide * 0.008, 0, Math.PI * 2);
    ctx.fillStyle = lerpColor([71, 85, 105], [16, 185, 129], rootCharge);
    ctx.fill();
    ctx.lineWidth = Math.max(1.2, strokeW * 0.55);
    ctx.strokeStyle = darkInk;
    ctx.stroke();
  }

  // 6. Inactive Ghost PCB Circuit Bus Skeleton (Clean precision blueprint beneath animated energy trim-paths)
  const mainStemPts = [[cx, rootY], nodeTop];
  const leftBranchPts = [[cx, forkLowY], elbowL, nodeLeft];
  const rightBranchPts = [[cx, forkLowY], elbowR, nodeRight];

  const allPaths = [mainStemPts, leftBranchPts, rightBranchPts];
  for (let p = 0; p < allPaths.length; p++) {
    const pts = allPaths[p];
    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
    ctx.lineWidth = minSide * 0.015;
    ctx.strokeStyle = darkInk;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(pts[0][0], pts[0][1]);
    for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
    ctx.lineWidth = minSide * 0.009;
    ctx.strokeStyle = "#263747";
    ctx.stroke();
  }

  // Active Illuminated PCB Trim-Paths & Rising Light Pulse Tip
  if (trunkTrim > 0.02) {
    ctx.lineWidth = minSide * 0.0085;
    ctx.strokeStyle = lerpColor([16, 185, 129], [251, 191, 36], syncPulse * 0.45);
    const stemTip = tracePolylineTrim(mainStemPts, trunkTrim);
    ctx.stroke();

    if (stemTip && trunkTrim < 0.98) {
      ctx.beginPath();
      ctx.arc(stemTip[0], stemTip[1], minSide * 0.009, 0, Math.PI * 2);
      ctx.fillStyle = "#FDE68A";
      ctx.fill();
    }
  }

  if (branchTrim > 0.02) {
    ctx.lineWidth = minSide * 0.0082;
    ctx.strokeStyle = "#06B6D4";
    const tipL = tracePolylineTrim(leftBranchPts, branchTrim);
    ctx.stroke();

    ctx.strokeStyle = "#10B981";
    const tipR = tracePolylineTrim(rightBranchPts, branchTrim);
    ctx.stroke();

    if (branchTrim < 0.98) {
      if (tipL) {
        ctx.beginPath();
        ctx.arc(tipL[0], tipL[1], minSide * 0.008, 0, Math.PI * 2);
        ctx.fillStyle = "#A5F3FC";
        ctx.fill();
      }
      if (tipR) {
        ctx.beginPath();
        ctx.arc(tipR[0], tipR[1], minSide * 0.008, 0, Math.PI * 2);
        ctx.fillStyle = "#A7F3D0";
        ctx.fill();
      }
    }
  }

  // Central Fork Junction Ring Pad
  ctx.beginPath();
  ctx.arc(cx, forkLowY, minSide * 0.013, 0, Math.PI * 2);
  ctx.fillStyle = lerpColor([51, 65, 85], [16, 185, 129], branchTrim);
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, strokeW * 0.65);
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Root Energy Core Node
  const rootPulse = 0.85 + 0.15 * Math.sin(cycleNorm * Math.PI * 2 * 6) * rootCharge;
  ctx.beginPath();
  ctx.arc(cx, rootY, minSide * 0.024, 0, Math.PI * 2);
  ctx.fillStyle = "#1E293B";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, rootY, minSide * 0.013 * rootPulse, 0, Math.PI * 2);
  ctx.fillStyle = lerpColor([52, 211, 153], [245, 158, 11], rootCharge);
  ctx.fill();

  // 7. Upper Load-Balancing Bezier Curves & Traveling Light Packets (Scene 1: Left <-> Top <-> Right)
  // Strictly offset along outer upper chord between node circles so curves NEVER cross branch traces or leaves!
  const arcCtrlL = [cx - minSide * 0.125, cy - minSide * 0.135];
  const arcCtrlR = [cx + minSide * 0.125, cy - minSide * 0.135];
  // Compute clean trim points along node rims
  function rimOffset(pFrom, pTo, rOff) {
    const dx = pTo[0] - pFrom[0];
    const dy = pTo[1] - pFrom[1];
    const len = Math.hypot(dx, dy) || 1;
    return [pFrom[0] + (dx / len) * rOff, pFrom[1] + (dy / len) * rOff];
  }
  const pArcL0 = rimOffset(nodeLeft, arcCtrlL, nodeR + minSide * 0.008);
  const pArcL1 = rimOffset(nodeTop, arcCtrlL, nodeR + minSide * 0.008);
  const pArcR0 = rimOffset(nodeTop, arcCtrlR, nodeR + minSide * 0.008);
  const pArcR1 = rimOffset(nodeRight, arcCtrlR, nodeR + minSide * 0.008);

  if (arcAlpha > 0.02) {
    ctx.save();
    ctx.setLineDash([minSide * 0.008, minSide * 0.010]);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
    ctx.strokeStyle = "rgba(34, 211, 238, " + (arcAlpha * 0.55).toFixed(3) + ")";

    ctx.beginPath();
    ctx.moveTo(pArcL0[0], pArcL0[1]);
    ctx.quadraticCurveTo(arcCtrlL[0], arcCtrlL[1], pArcL1[0], pArcL1[1]);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(pArcR0[0], pArcR0[1]);
    ctx.quadraticCurveTo(arcCtrlR[0], arcCtrlR[1], pArcR1[0], pArcR1[1]);
    ctx.stroke();
    ctx.restore();

    // Smooth back-and-forth load-balancing packet beads along both bezier paths
    const uPing = 0.5 - 0.5 * Math.cos(balanceWave * Math.PI * 4);
    const pktL = pointOnQuad(pArcL0, arcCtrlL, pArcL1, uPing);
    const pktR = pointOnQuad(pArcR0, arcCtrlR, pArcR1, 1 - uPing);

    for (let pk = 0; pk < 2; pk++) {
      const pt = pk === 0 ? pktL : pktR;
      ctx.beginPath();
      ctx.arc(pt[0], pt[1], minSide * 0.0085, 0, Math.PI * 2);
      ctx.fillStyle = pk === 0 ? "rgba(251, 191, 36, " + arcAlpha.toFixed(3) + ")" : "rgba(52, 211, 153, " + arcAlpha.toFixed(3) + ")";
      ctx.fill();
      ctx.lineWidth = Math.max(1.2, minSide * 0.0022);
      ctx.strokeStyle = "rgba(248, 250, 252, " + arcAlpha.toFixed(3) + ")";
      ctx.stroke();
    }
  }

  // 8. Botanical Outer Leaves Flanking Node Hubs (Pure exterior radial sprouts, swaying smoothly, zero overlap!)
  if (leafBloom > 0.02) {
    const sway = Math.sin(cycleNorm * Math.PI * 2 * 6) * 0.08 * leafBloom;
    const lSize = minSide * 0.052 * leafBloom;
    const leafSpots = [
      { cx: nodeLeft[0], cy: nodeLeft[1], baseA: -Math.PI * 0.88, dark: "#059669", light: "#34D399" },
      { cx: nodeLeft[0], cy: nodeLeft[1], baseA: Math.PI * 0.82, dark: "#047857", light: "#10B981" },
      { cx: nodeRight[0], cy: nodeRight[1], baseA: -Math.PI * 0.12, dark: "#059669", light: "#34D399" },
      { cx: nodeRight[0], cy: nodeRight[1], baseA: Math.PI * 0.18, dark: "#047857", light: "#10B981" }
    ];
    for (let ls = 0; ls < leafSpots.length; ls++) {
      const sp = leafSpots[ls];
      const bx = sp.cx + Math.cos(sp.baseA) * (nodeR + minSide * 0.006);
      const by = sp.cy + Math.sin(sp.baseA) * (nodeR + minSide * 0.006);
      drawVectorLeaf(bx, by, sp.baseA + sway * (ls % 2 === 0 ? 1 : -1), lSize, sp.light, sp.dark, darkInk, strokeW * 0.72);
    }
  }

  // 9. Three Canopy Clean-Energy Node Badges (Wind Left, Solar Top, Hydro Right)
  const nodes = [
    { pos: nodeLeft, borderCol: "#22D3EE", kind: 0, phaseOff: 0.0 },
    { pos: nodeTop, borderCol: "#F59E0B", kind: 1, phaseOff: 0.33 },
    { pos: nodeRight, borderCol: "#10B981", kind: 2, phaseOff: 0.66 }
  ];

  for (let n = 0; n < nodes.length; n++) {
    const nd = nodes[n];
    const s = Math.max(0.001, nodeReveal);
    if (nodeReveal <= 0.02) continue;

    // Sequential brightness pulse in Scene 1 + global sync glow ring in Scene 2
    const seqActive = arcAlpha > 0.05 ? (0.5 + 0.5 * Math.sin(cycleNorm * Math.PI * 2 * 6 - n * 2.1)) * arcAlpha : 0;
    const ringBoost = clamp01(seqActive * 0.65 + syncPulse * 0.85);

    ctx.save();
    ctx.translate(nd.pos[0], nd.pos[1]);
    ctx.scale(s, s);

    // Outer node housing circle
    ctx.beginPath();
    ctx.arc(0, 0, nodeR, 0, Math.PI * 2);
    ctx.fillStyle = "#0E1722";
    ctx.fill();
    ctx.lineWidth = strokeW * lerp(0.9, 1.35, ringBoost);
    ctx.strokeStyle = nd.borderCol;
    ctx.stroke();

    if (nd.kind === 0) {
      // Wind Turbine Mini Icon (Electric Sky cyan-white rotating rotor)
      ctx.save();
      ctx.rotate(cycleNorm * Math.PI * 2 * 4);
      for (let b = 0; b < 3; b++) {
        ctx.rotate((Math.PI * 2) / 3);
        ctx.beginPath();
        ctx.moveTo(0, -minSide * 0.003);
        ctx.quadraticCurveTo(minSide * 0.011, -minSide * 0.014, 0, -nodeR * 0.64);
        ctx.quadraticCurveTo(-minSide * 0.005, -minSide * 0.014, 0, -minSide * 0.003);
        ctx.closePath();
        ctx.fillStyle = "#38BDF8";
        ctx.fill();
      }
      ctx.beginPath();
      ctx.arc(0, 0, minSide * 0.0052, 0, Math.PI * 2);
      ctx.fillStyle = "#F8FAFC";
      ctx.fill();
      ctx.restore();
    } else if (nd.kind === 1) {
      // Solar Sun Mini Icon (Circuit Gold core + crisp 8 radial rays spinning calmly)
      ctx.save();
      ctx.rotate(cycleNorm * Math.PI * 2 * 2);
      for (let r = 0; r < 8; r++) {
        ctx.rotate(Math.PI / 4);
        ctx.beginPath();
        ctx.moveTo(nodeR * 0.44, 0);
        ctx.lineTo(nodeR * 0.64, 0);
        ctx.lineWidth = Math.max(1.5, minSide * 0.0034);
        ctx.strokeStyle = "#FDE047";
        ctx.stroke();
      }
      ctx.restore();
      ctx.beginPath();
      ctx.arc(0, 0, nodeR * 0.30, 0, Math.PI * 2);
      ctx.fillStyle = "#F59E0B";
      ctx.fill();
      ctx.lineWidth = Math.max(1.2, minSide * 0.0022);
      ctx.strokeStyle = "#FEF3C7";
      ctx.stroke();
    } else {
      // Hydro Water Droplet Mini Icon (Electric Sky / Emerald teal clean vector drop)
      ctx.beginPath();
      ctx.moveTo(0, -nodeR * 0.56);
      ctx.bezierCurveTo(nodeR * 0.46, -nodeR * 0.04, nodeR * 0.46, nodeR * 0.54, 0, nodeR * 0.54);
      ctx.bezierCurveTo(-nodeR * 0.46, nodeR * 0.54, -nodeR * 0.46, -nodeR * 0.04, 0, -nodeR * 0.56);
      ctx.closePath();
      const dropGrad = ctx.createLinearGradient(0, -nodeR * 0.5, 0, nodeR * 0.5);
      dropGrad.addColorStop(0, "#34D399");
      dropGrad.addColorStop(1, "#06B6D4");
      ctx.fillStyle = dropGrad;
      ctx.fill();

      // Tiny inner droplet highlight crescent
      ctx.beginPath();
      ctx.arc(-nodeR * 0.12, nodeR * 0.18, nodeR * 0.14, Math.PI * 0.65, Math.PI * 1.15);
      ctx.lineWidth = Math.max(1.2, minSide * 0.0026);
      ctx.strokeStyle = "#ECFEFF";
      ctx.stroke();
    }

    ctx.restore();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function bellEnvelope(p, start, end) {
    if (p <= start || p >= end) return 0;
    return Math.sin(Math.PI * ((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function traceBunsenFlame(baseX, baseY, flameW, flameH, swayTip, bulgeAmt) {
    ctx.beginPath();
    ctx.moveTo(baseX, baseY);
    // Smooth symmetrical vector flame envelope rising cleanly from burner tip
    ctx.bezierCurveTo(
      baseX + flameW * (1.0 + bulgeAmt), baseY - flameH * 0.22,
      baseX + flameW * 0.68 + swayTip * 0.45, baseY - flameH * 0.62,
      baseX + swayTip, baseY - flameH
    );
    ctx.bezierCurveTo(
      baseX - flameW * 0.68 + swayTip * 0.45, baseY - flameH * 0.62,
      baseX - flameW * (1.0 + bulgeAmt), baseY - flameH * 0.22,
      baseX, baseY
    );
    ctx.closePath();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (Deep Plum Slate, zero glow, zero border/brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#120C1C");
  bgGrad.addColorStop(0.52, "#1D132C");
  bgGrad.addColorStop(1, "#291A3D");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let pressureLevel = 0.16;
  let domeExpand = 0.14;
  let bubbleAlpha = 0.35;
  let pipeFlowAlpha = 0;
  let flamePower = 0.16;
  let heatRippleAlpha = 0;

  if (currentScene === 0) {
    // Scene 0: Bio-slurry ferments & bubbles rise; upper membrane dome swells elastically; left manometer needle climbs
    pressureLevel = 0.16 + 0.74 * smoothRange(sceneProgress, 0.10, 0.90);
    domeExpand = 0.14 + 0.86 * smoothRange(sceneProgress, 0.12, 0.92);
    bubbleAlpha = 0.35 + 0.65 * smoothRange(sceneProgress, 0.08, 0.72);
    pipeFlowAlpha = smoothRange(sceneProgress, 0.74, 1.0);
    flamePower = 0.16;
    heatRippleAlpha = 0;
  } else if (currentScene === 1) {
    // Scene 1: Gas pulses stream through curved copper conduit -> clean Bunsen blue/gold flame ignites vigorously with heat ripples
    pressureLevel = 0.90 - 0.12 * smoothRange(sceneProgress, 0.72, 1.0);
    domeExpand = 1.0 - 0.14 * smoothRange(sceneProgress, 0.72, 1.0);
    bubbleAlpha = 1.0;
    pipeFlowAlpha = 1.0;
    flamePower = 0.16 + 0.84 * smoothRange(sceneProgress, 0.04, 0.30);
    heatRippleAlpha = smoothRange(sceneProgress, 0.18, 0.50);
  } else {
    // Scene 2: Controlled taper back to calm pilot flame & deflated resting dome membrane for seamless loop
    pressureLevel = 0.78 - 0.62 * smoothRange(sceneProgress, 0.18, 0.88);
    domeExpand = 0.86 - 0.72 * smoothRange(sceneProgress, 0.16, 0.88);
    bubbleAlpha = 1.0 - 0.65 * smoothRange(sceneProgress, 0.20, 0.86);
    pipeFlowAlpha = 1.0 - smoothRange(sceneProgress, 0.10, 0.58);
    flamePower = 1.0 - 0.84 * smoothRange(sceneProgress, 0.18, 0.82);
    heatRippleAlpha = 1.0 - smoothRange(sceneProgress, 0.12, 0.60);
  }

  // 3. Layout Coordinates (Left Analog Gauge, Center Reactor & Dome, Right Conduit Arch -> Overhead Centered Burner)
  const cx = width * 0.5;
  const cy = height * 0.54;
  const strokeW = Math.max(2, minSide * 0.0052);
  const darkInk = "#0D0814";

  const tankW = minSide * 0.218;
  const tankL = cx - tankW * 0.5;
  const tankR = cx + tankW * 0.5;
  const tankTopY = cy + minSide * 0.026;
  const tankBotY = cy + minSide * 0.212;
  const tankH = tankBotY - tankTopY;

  // Burner pedestal anchored clearly ABOVE max dome expansion (max dome apex at cy - 0.068, burner sits at cy - 0.158 -> 0.090 clear air gap!)
  const burnerY = cy - minSide * 0.158;
  const pipeRightX = tankR + minSide * 0.064;

  // 4. Heavy Slate Reactor Pedestal Base
  roundedRectPath(tankL - minSide * 0.045, tankBotY, tankW + minSide * 0.090, minSide * 0.017, minSide * 0.008);
  ctx.fillStyle = "#2E2245";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // 5. Right-Side Arched Gas Conduit Pipe & Traveling Bio-Lime Gas Pulses (tankR -> pipeRightX -> centered burner base)
  function traceGasConduit() {
    ctx.beginPath();
    ctx.moveTo(tankR - minSide * 0.004, tankTopY + minSide * 0.032);
    ctx.lineTo(pipeRightX - minSide * 0.022, tankTopY + minSide * 0.032);
    ctx.quadraticCurveTo(pipeRightX, tankTopY + minSide * 0.032, pipeRightX, tankTopY + minSide * 0.010);
    ctx.lineTo(pipeRightX, burnerY + minSide * 0.034);
    ctx.quadraticCurveTo(pipeRightX, burnerY + minSide * 0.010, pipeRightX - minSide * 0.024, burnerY + minSide * 0.010);
    ctx.lineTo(cx, burnerY + minSide * 0.010);
  }

  traceGasConduit();
  ctx.lineWidth = minSide * 0.018;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  traceGasConduit();
  ctx.lineWidth = minSide * 0.011;
  ctx.strokeStyle = "#C46349";
  ctx.stroke();

  // Animated Bio-Lime Gas Flow Dashes Inside Conduit Pipe
  if (pipeFlowAlpha > 0.02) {
    const flowShift = (cycleNorm * 12) % 1;
    ctx.save();
    ctx.setLineDash([minSide * 0.016, minSide * 0.016]);
    ctx.lineDashOffset = -flowShift * minSide * 0.032;
    traceGasConduit();
    ctx.lineWidth = minSide * 0.0052;
    ctx.strokeStyle = "rgba(129, 230, 217, " + (pipeFlowAlpha * 0.92).toFixed(3) + ")";
    ctx.stroke();
    ctx.restore();
  }

  // 6. Left-Side Analog Manometer Gauge & Stub Tube
  const gaugeR = minSide * 0.042;
  const gaugeCx = tankL - minSide * 0.088;
  const gaugeCy = tankTopY + minSide * 0.056;

  // Connecting bronze stub pipe
  ctx.beginPath();
  ctx.moveTo(gaugeCx + gaugeR * 0.8, gaugeCy);
  ctx.lineTo(tankL + minSide * 0.002, gaugeCy);
  ctx.lineWidth = minSide * 0.015;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(gaugeCx + gaugeR * 0.8, gaugeCy);
  ctx.lineTo(tankL + minSide * 0.002, gaugeCy);
  ctx.lineWidth = minSide * 0.009;
  ctx.strokeStyle = "#E07A5F";
  ctx.stroke();

  // Manometer Brass Rim & Dark Dial Face
  ctx.beginPath();
  ctx.arc(gaugeCx, gaugeCy, gaugeR, 0, Math.PI * 2);
  ctx.fillStyle = "#160F24";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.95;
  ctx.strokeStyle = "#E07A5F";
  ctx.stroke();

  // Scale Track & Active Bio-Lime Safe Arc
  const mStart = Math.PI * 0.78;
  const mEnd = Math.PI * 2.22;
  ctx.beginPath();
  ctx.arc(gaugeCx, gaugeCy, gaugeR * 0.68, mStart, mEnd);
  ctx.lineWidth = minSide * 0.0062;
  ctx.strokeStyle = "#2E2245";
  ctx.stroke();

  const curAngle = lerp(mStart, mEnd, pressureLevel);
  ctx.beginPath();
  ctx.arc(gaugeCx, gaugeCy, gaugeR * 0.68, mStart, curAngle);
  ctx.lineWidth = minSide * 0.0062;
  ctx.strokeStyle = lerpColor([129, 230, 217], [56, 189, 248], pressureLevel);
  ctx.stroke();

  // Damped Analog Needle
  ctx.save();
  ctx.translate(gaugeCx, gaugeCy);
  ctx.rotate(curAngle + Math.sin(cycleNorm * Math.PI * 2 * 10) * 0.025 * pressureLevel);
  ctx.beginPath();
  ctx.moveTo(-gaugeR * 0.15, 0);
  ctx.lineTo(gaugeR * 0.60, 0);
  ctx.lineWidth = Math.max(1.8, minSide * 0.0038);
  ctx.strokeStyle = "#FDE047";
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(0, 0, minSide * 0.0060, 0, Math.PI * 2);
  ctx.fillStyle = "#F8FAFC";
  ctx.fill();
  ctx.restore();

  // 7. Elastic Expanding Pressure Gasometer Membrane Dome atop Reactor Vessel
  const domeHalfW = tankW * 0.45;
  const domeH = minSide * lerp(0.050, 0.092, domeExpand);
  const domeLeftX = cx - domeHalfW;
  const domeRightX = cx + domeHalfW;

  ctx.beginPath();
  ctx.moveTo(domeLeftX, tankTopY);
  ctx.bezierCurveTo(
    domeLeftX - minSide * 0.010 * domeExpand, tankTopY - domeH * 1.15,
    domeRightX + minSide * 0.010 * domeExpand, tankTopY - domeH * 1.15,
    domeRightX, tankTopY
  );
  ctx.closePath();

  const domeGrad = ctx.createLinearGradient(0, tankTopY - domeH, 0, tankTopY);
  domeGrad.addColorStop(0, lerpColor([184, 80, 56], [45, 212, 191], domeExpand * 0.42));
  domeGrad.addColorStop(1, "#B85038");
  ctx.fillStyle = domeGrad;
  ctx.fill();

  // Subtle curved pressure ribs inside membrane dome clip
  ctx.save();
  ctx.clip();
  for (let rib = -1; rib <= 1; rib++) {
    ctx.beginPath();
    ctx.moveTo(cx + rib * domeHalfW * 0.46, tankTopY);
    ctx.quadraticCurveTo(cx + rib * domeHalfW * 0.56, tankTopY - domeH * 0.72, cx, tankTopY - domeH * 0.94);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
    ctx.strokeStyle = "rgba(255, 241, 230, 0.20)";
    ctx.stroke();
  }
  ctx.restore();

  ctx.beginPath();
  ctx.moveTo(domeLeftX, tankTopY);
  ctx.bezierCurveTo(
    domeLeftX - minSide * 0.010 * domeExpand, tankTopY - domeH * 1.15,
    domeRightX + minSide * 0.010 * domeExpand, tankTopY - domeH * 1.15,
    domeRightX, tankTopY
  );
  ctx.closePath();
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // 8. Central Copper-Bronze Digester Vessel, Curved Glass Window & Bio-Lime Fermenting Slurry
  roundedRectPath(tankL, tankTopY, tankW, tankH, minSide * 0.018);
  const tankGrad = ctx.createLinearGradient(tankL, 0, tankR, 0);
  tankGrad.addColorStop(0, "#F29F80");
  tankGrad.addColorStop(0.28, "#E07A5F");
  tankGrad.addColorStop(0.85, "#B85038");
  tankGrad.addColorStop(1, "#9A3F2B");
  ctx.fillStyle = tankGrad;
  ctx.fill();
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Top Flange Ring Separating Tank & Membrane Dome
  roundedRectPath(tankL - minSide * 0.007, tankTopY - minSide * 0.008, tankW + minSide * 0.014, minSide * 0.018, minSide * 0.006);
  ctx.fillStyle = "#475569";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Reactor Glass Sight Window
  const winW = tankW * 0.62;
  const winH = tankH * 0.62;
  const winX = cx - winW * 0.5;
  const winY = tankTopY + minSide * 0.036;

  roundedRectPath(winX, winY, winW, winH, minSide * 0.022);
  ctx.fillStyle = "#160F24";
  ctx.fill();

  ctx.save();
  roundedRectPath(winX + strokeW * 0.35, winY + strokeW * 0.35, winW - strokeW * 0.7, winH - strokeW * 0.7, minSide * 0.019);
  ctx.clip();

  // Undulating Bio-Lime Fermenting Slurry at Bottom of Sight Window
  const slurryY = winY + winH * 0.44;
  const sWavePhase = cycleNorm * Math.PI * 2 * 8;
  const sAmp = minSide * 0.0052;
  ctx.beginPath();
  ctx.moveTo(winX - 2, winY + winH + 4);
  for (let i = 0; i <= 16; i++) {
    const u = i / 16;
    const sx = lerp(winX - 2, winX + winW + 2, u);
    const sy = slurryY + Math.sin(u * Math.PI * 2 + sWavePhase) * sAmp;
    ctx.lineTo(sx, sy);
  }
  ctx.lineTo(winX + winW + 2, winY + winH + 4);
  ctx.closePath();

  const slurryGrad = ctx.createLinearGradient(0, slurryY, 0, winY + winH);
  slurryGrad.addColorStop(0, "#81E6D9");
  slurryGrad.addColorStop(0.55, "#2DD4BF");
  slurryGrad.addColorStop(1, "#0F766E");
  ctx.fillStyle = slurryGrad;
  ctx.fill();

  // Crisp light meniscus line
  ctx.beginPath();
  for (let i = 0; i <= 16; i++) {
    const u = i / 16;
    const sx = lerp(winX - 2, winX + winW + 2, u);
    const sy = slurryY + Math.sin(u * Math.PI * 2 + sWavePhase) * sAmp;
    if (i === 0) ctx.moveTo(sx, sy);
    else ctx.lineTo(sx, sy);
  }
  ctx.lineWidth = Math.max(1.8, minSide * 0.0036);
  ctx.strokeStyle = "#CCFBF1";
  ctx.stroke();

  // Fermenting Gas Bubbles rising smoothly through slurry & into upper headspace inside window
  if (bubbleAlpha > 0.04) {
    for (let b = 0; b < 5; b++) {
      const bp = (cycleNorm * 8 + b * 0.2) % 1;
      const bx = lerp(winX + winW * 0.18, winX + winW * 0.82, (b * 0.24));
      const by = lerp(winY + winH - minSide * 0.010, winY + minSide * 0.016, bp);
      const ba = Math.sin(Math.PI * bp) * bubbleAlpha * 0.88;
      if (ba > 0.04) {
        ctx.beginPath();
        ctx.arc(bx + Math.sin(bp * Math.PI * 3 + b) * minSide * 0.004, by, minSide * (0.0036 + (b % 2) * 0.0014), 0, Math.PI * 2);
        ctx.fillStyle = "rgba(129, 230, 217, " + ba.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // Diagonal flat glass specular streak
  ctx.beginPath();
  ctx.moveTo(winX + winW * 0.14, winY + minSide * 0.010);
  ctx.lineTo(winX + winW * 0.30, winY + minSide * 0.010);
  ctx.lineTo(winX + winW * 0.10, winY + winH - minSide * 0.010);
  ctx.lineTo(winX - minSide * 0.006, winY + winH - minSide * 0.010);
  ctx.closePath();
  ctx.fillStyle = "rgba(255, 255, 255, 0.12)";
  ctx.fill();

  ctx.restore(); // End window clip

  roundedRectPath(winX, winY, winW, winH, minSide * 0.022);
  ctx.lineWidth = strokeW * 0.82;
  ctx.strokeStyle = "#F5B8A3";
  ctx.stroke();

  // 9. Overhead Bunsen Burner Nozzle & Clean Multi-Harmonic Blue + Golden Flame (Well above dome!)
  // Burner base flange anchored cleanly atop horizontal end of conduit pipe at (cx, burnerY)
  roundedRectPath(cx - minSide * 0.024, burnerY - minSide * 0.006, minSide * 0.048, minSide * 0.024, minSide * 0.006);
  ctx.fillStyle = "#475569";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.8;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Brass nozzle tip
  const nozzleTopY = burnerY - minSide * 0.022;
  roundedRectPath(cx - minSide * 0.013, nozzleTopY, minSide * 0.026, minSide * 0.018, minSide * 0.004);
  ctx.fillStyle = "#F29F80";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.72;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Sharp Multi-Harmonic Flat-Vector Bunsen Flame (No blur, crisp Bezier teardrop contour!)
  const flameBaseY = nozzleTopY - minSide * 0.002;
  const fHarA = Math.sin(cycleNorm * Math.PI * 2 * 10);
  const fHarB = Math.cos(cycleNorm * Math.PI * 2 * 16);
  const flameH = minSide * lerp(0.032, 0.118, flamePower) * (1 + 0.055 * fHarA * flamePower);
  const flameW = minSide * lerp(0.016, 0.042, flamePower) * (1 + 0.04 * fHarB * flamePower);
  const swayTip = (fHarA * 0.6 + fHarB * 0.4) * minSide * 0.007 * flamePower;

  // Outer Clean Blue Flame Shell
  traceBunsenFlame(cx, flameBaseY, flameW, flameH, swayTip, 0.05 * fHarB);
  const blueFlameGrad = ctx.createLinearGradient(cx, flameBaseY, cx, flameBaseY - flameH);
  blueFlameGrad.addColorStop(0, "#0284C7");
  blueFlameGrad.addColorStop(0.55, "#38BDF8");
  blueFlameGrad.addColorStop(1, "#BAE6FD");
  ctx.fillStyle = blueFlameGrad;
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, strokeW * 0.65);
  ctx.strokeStyle = "#E0F2FE";
  ctx.stroke();

  // Inner Golden Flame Core Teardrop
  const coreH = flameH * lerp(0.46, 0.56, flamePower);
  const coreW = flameW * 0.52;
  traceBunsenFlame(cx, flameBaseY - minSide * 0.002, coreW, coreH, swayTip * 0.45, 0.04 * fHarA);
  ctx.fillStyle = "#FDE047";
  ctx.fill();

  // Rising Clean Geometric Heat Wave Ripples above Flame Tip (Scene 1 active burn)
  if (heatRippleAlpha > 0.03) {
    for (let h = 0; h < 2; h++) {
      const hp = (cycleNorm * 6 + h * 0.5) % 1;
      const hy = flameBaseY - flameH - minSide * (0.016 + hp * 0.044);
      const hr = minSide * (0.020 + hp * 0.022);
      const ha = Math.sin(Math.PI * hp) * heatRippleAlpha * 0.72;
      if (ha > 0.04) {
        ctx.beginPath();
        ctx.arc(cx, hy + hr * 0.5, hr, -Math.PI * 0.76, -Math.PI * 0.24);
        ctx.lineWidth = Math.max(1.5, minSide * 0.0030);
        ctx.strokeStyle = "rgba(186, 230, 253, " + ha.toFixed(3) + ")";
        ctx.stroke();
      }
    }
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutBackSoft(x) {
    const k = clamp01(x);
    const c1 = 1.10;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2);
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function bellEnvelope(p, start, end) {
    if (p <= start || p >= end) return 0;
    return Math.sin(Math.PI * ((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawHexCrystal(x, y, r, rot, colorStr, alpha) {
    if (alpha <= 0.02 || r <= 0.5) return;
    ctx.save();
    ctx.globalAlpha = alpha;
    ctx.translate(x, y);
    ctx.rotate(rot);
    ctx.strokeStyle = colorStr;
    ctx.lineWidth = Math.max(1.2, r * 0.22);
    for (let k = 0; k < 3; k++) {
      ctx.save();
      ctx.rotate((k * Math.PI) / 3);
      ctx.beginPath();
      ctx.moveTo(-r, 0);
      ctx.lineTo(r, 0);
      ctx.stroke();
      ctx.restore();
    }
    ctx.beginPath();
    ctx.arc(0, 0, r * 0.34, 0, Math.PI * 2);
    ctx.fillStyle = colorStr;
    ctx.fill();
    ctx.restore();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (Arctic Midnight Blue, zero glow, zero edge border)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#05101F");
  bgGrad.addColorStop(0.52, "#0A203B");
  bgGrad.addColorStop(1, "#102F57");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let seaRatio = 0.36;
  let iceScale = 1.0;
  let dripAlpha = 0;
  let chillWindAlpha = 0;
  let freezeTrim = 0;
  let sheenPos = -1;
  let alertLevel = 0;

  if (currentScene === 0) {
    // Scene 0: Sea waves swell upward toward Alert Coral threshold; glacier loses height smoothly & drips water drops
    seaRatio = 0.36 + 0.22 * smoothRange(sceneProgress, 0.08, 0.88);
    iceScale = 1.0 - 0.26 * smoothRange(sceneProgress, 0.10, 0.86);
    dripAlpha = bellEnvelope(sceneProgress, 0.10, 0.86);
    chillWindAlpha = 0;
    freezeTrim = 0;
    sheenPos = -1;
    alertLevel = smoothRange(sceneProgress, 0.45, 0.88);
  } else if (currentScene === 1) {
    // Scene 1: Arctic wind spirals carry hex frost crystals -> crystal trim-path refreezes peaks -> ice recovers & sea recedes
    chillWindAlpha = bellEnvelope(sceneProgress, 0.04, 0.86);
    freezeTrim = smoothRange(sceneProgress, 0.12, 0.68) * (1 - smoothRange(sceneProgress, 0.72, 0.96));
    const regrow = easeOutBackSoft(clamp01((sceneProgress - 0.20) / 0.66));
    iceScale = sceneProgress <= 0.20 ? 0.74 : lerp(0.74, 1.0, regrow);
    seaRatio = 0.58 - 0.22 * smoothRange(sceneProgress, 0.22, 0.90);
    dripAlpha = 0;
    sheenPos = -1;
    alertLevel = 1.0 - smoothRange(sceneProgress, 0.25, 0.68);
  } else {
    // Scene 2: Calm weighted buoyancy floating & crisp facet sheen sweep across ice
    seaRatio = 0.36;
    iceScale = 1.0;
    dripAlpha = 0;
    chillWindAlpha = 0;
    freezeTrim = 0;
    alertLevel = 0;
    sheenPos = (sceneProgress >= 0.14 && sceneProgress <= 0.64) ? (sceneProgress - 0.14) / 0.50 : -1;
  }

  // 3. Layout Coordinates (Circular Arctic Emblem left-center + Non-overlapping Sea-Level Gauge bar on right)
  const cx = width * 0.5;
  const cy = height * 0.51;
  const emblemCx = cx - minSide * 0.036;
  const emblemCy = cy;
  const emblemR = minSide * 0.218;
  const strokeW = Math.max(2, minSide * 0.0052);
  const darkInk = "#04101E";

  // Synchronized continuous sea level Y & gentle ocean harmonics (exact integer periods -> zero loop seam)
  const gaugeTopY = emblemCy - minSide * 0.165;
  const gaugeBotY = emblemCy + minSide * 0.165;
  const gaugeH = gaugeBotY - gaugeTopY;
  const seaSurfaceY = lerp(gaugeBotY, gaugeTopY, seaRatio);

  const wavePhase = cycleNorm * Math.PI * 2 * 6;
  const buoyBobY = Math.sin(cycleNorm * Math.PI * 2 * 4) * minSide * 0.006;
  const buoyTilt = Math.sin(cycleNorm * Math.PI * 2 * 4 - 0.5) * 0.026;

  // 4. Circular Arctic Window Frame & Clipped Scene Contents
  ctx.beginPath();
  ctx.arc(emblemCx, emblemCy, emblemR, 0, Math.PI * 2);
  const skyGrad = ctx.createLinearGradient(0, emblemCy - emblemR, 0, emblemCy + emblemR);
  skyGrad.addColorStop(0, "#06162A");
  skyGrad.addColorStop(0.55, "#0B2442");
  skyGrad.addColorStop(1, "#091B33");
  ctx.fillStyle = skyGrad;
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(emblemCx, emblemCy, emblemR - strokeW * 0.45, 0, Math.PI * 2);
  ctx.clip();

  // Back Deep Ocean Water Layer (Submerged depth color below wave crest)
  const deepWaveAmp = minSide * 0.0065;
  ctx.beginPath();
  ctx.moveTo(emblemCx - emblemR - 4, emblemCy + emblemR + 4);
  for (let i = 0; i <= 26; i++) {
    const u = i / 26;
    const wx = lerp(emblemCx - emblemR - 4, emblemCx + emblemR + 4, u);
    const wy = seaSurfaceY + Math.sin(u * Math.PI * 3 + wavePhase) * deepWaveAmp;
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(emblemCx + emblemR + 4, emblemCy + emblemR + 4);
  ctx.closePath();
  const deepGrad = ctx.createLinearGradient(0, seaSurfaceY, 0, emblemCy + emblemR);
  deepGrad.addColorStop(0, "#0284C7");
  deepGrad.addColorStop(1, "#07345E");
  ctx.fillStyle = deepGrad;
  ctx.fill();

  // 5. Geometric Flat-Vector Multi-Faceted Iceberg Buoyant Body
  const iceW = minSide * 0.132 * (0.86 + 0.14 * iceScale);
  const iceAboveH = minSide * 0.168 * iceScale;
  const iceSubH = minSide * 0.088 * (0.82 + 0.18 * iceScale);
  const iceAnchorY = seaSurfaceY + buoyBobY;

  ctx.save();
  ctx.translate(emblemCx, iceAnchorY);
  ctx.rotate(buoyTilt);

  // Define crisp flat-vector facet coordinates relative to waterline (0,0)
  const pLeftW = [-iceW * 0.92, minSide * 0.004];
  const pLeftSh = [-iceW * 0.56, -iceAboveH * 0.56];
  const pSubLeft = [-iceW * 0.70, iceSubH * 0.68];
  const pPeak = [-iceW * 0.06, -iceAboveH];
  const pMidRidge = [-iceW * 0.08, -iceAboveH * 0.34];
  const pSubBot = [iceW * 0.06, iceSubH];
  const pRightSec = [iceW * 0.44, -iceAboveH * 0.62];
  const pRightW = [iceW * 0.90, minSide * 0.004];
  const pSubRight = [iceW * 0.62, iceSubH * 0.62];

  // Submerged Glacier Keel Facets (underwater refracted cyan-teal tones)
  ctx.beginPath();
  ctx.moveTo(pLeftW[0], pLeftW[1]);
  ctx.lineTo(pSubLeft[0], pSubLeft[1]);
  ctx.lineTo(pSubBot[0], pSubBot[1]);
  ctx.lineTo(pSubRight[0], pSubRight[1]);
  ctx.lineTo(pRightW[0], pRightW[1]);
  ctx.closePath();
  ctx.fillStyle = "rgba(56, 189, 248, 0.38)";
  ctx.fill();
  ctx.lineWidth = Math.max(1.4, minSide * 0.003);
  ctx.strokeStyle = "rgba(125, 211, 252, 0.45)";
  ctx.stroke();

  // Above-Water Iceberg Facet 1 (Sunlit Left White Ice)
  ctx.beginPath();
  ctx.moveTo(pLeftW[0], pLeftW[1]);
  ctx.lineTo(pLeftSh[0], pLeftSh[1]);
  ctx.lineTo(pPeak[0], pPeak[1]);
  ctx.lineTo(pMidRidge[0], pMidRidge[1]);
  ctx.lineTo(-iceW * 0.14, minSide * 0.004);
  ctx.closePath();
  ctx.fillStyle = "#F0F9FF";
  ctx.fill();

  // Facet 2 (Central Cool Frost Blue Facet)
  ctx.beginPath();
  ctx.moveTo(pPeak[0], pPeak[1]);
  ctx.lineTo(pRightSec[0], pRightSec[1]);
  ctx.lineTo(iceW * 0.24, minSide * 0.004);
  ctx.lineTo(-iceW * 0.14, minSide * 0.004);
  ctx.lineTo(pMidRidge[0], pMidRidge[1]);
  ctx.closePath();
  ctx.fillStyle = "#BAE6FD";
  ctx.fill();

  // Facet 3 (Right Shaded Arctic Facet)
  ctx.beginPath();
  ctx.moveTo(pRightSec[0], pRightSec[1]);
  ctx.lineTo(pRightW[0], pRightW[1]);
  ctx.lineTo(iceW * 0.24, minSide * 0.004);
  ctx.closePath();
  ctx.fillStyle = "#7DD3FC";
  ctx.fill();

  // Facet 4 (Craggy Mid-Left Step Accent)
  ctx.beginPath();
  ctx.moveTo(pLeftW[0], pLeftW[1]);
  ctx.lineTo(pLeftSh[0], pLeftSh[1]);
  ctx.lineTo(pMidRidge[0], pMidRidge[1]);
  ctx.lineTo(-iceW * 0.36, minSide * 0.004);
  ctx.closePath();
  ctx.fillStyle = "#E0F2FE";
  ctx.fill();

  // Scene 2 Diagonal Specular Sheen Sweep Clipped Strictly to Above-Water Glacier Facets
  if (sheenPos >= 0 && sheenPos <= 1) {
    ctx.save();
    ctx.beginPath();
    ctx.moveTo(pLeftW[0], pLeftW[1]);
    ctx.lineTo(pLeftSh[0], pLeftSh[1]);
    ctx.lineTo(pPeak[0], pPeak[1]);
    ctx.lineTo(pRightSec[0], pRightSec[1]);
    ctx.lineTo(pRightW[0], pRightW[1]);
    ctx.closePath();
    ctx.clip();

    const sx = lerp(-iceW * 1.3, iceW * 1.3, sheenPos);
    ctx.beginPath();
    ctx.moveTo(sx, -iceAboveH * 1.1);
    ctx.lineTo(sx + minSide * 0.032, -iceAboveH * 1.1);
    ctx.lineTo(sx - minSide * 0.025, minSide * 0.015);
    ctx.lineTo(sx - minSide * 0.057, minSide * 0.015);
    ctx.closePath();
    ctx.fillStyle = "rgba(255, 255, 255, 0.55)";
    ctx.fill();
    ctx.restore();
  }

  // Crisp Silhouette Border Around Glacier Ridge
  ctx.beginPath();
  ctx.moveTo(pLeftW[0], pLeftW[1]);
  ctx.lineTo(pLeftSh[0], pLeftSh[1]);
  ctx.lineTo(pPeak[0], pPeak[1]);
  ctx.lineTo(pRightSec[0], pRightSec[1]);
  ctx.lineTo(pRightW[0], pRightW[1]);
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Scene 1 Crystal Refreezing Trim-Path Highlight Tracing Peak Ridges
  if (freezeTrim > 0.02) {
    const ridgePts = [pLeftW, pLeftSh, pPeak, pRightSec, pRightW];
    const segs = ridgePts.length - 1;
    const progS = freezeTrim * segs;
    const full = Math.floor(progS);
    const part = progS - full;
    ctx.beginPath();
    ctx.moveTo(ridgePts[0][0], ridgePts[0][1]);
    for (let s = 0; s < segs; s++) {
      if (s < full) {
        ctx.lineTo(ridgePts[s + 1][0], ridgePts[s + 1][1]);
      } else if (s === full && part > 0.001) {
        ctx.lineTo(lerp(ridgePts[s][0], ridgePts[s + 1][0], part), lerp(ridgePts[s][1], ridgePts[s + 1][1], part));
      }
    }
    ctx.lineWidth = minSide * 0.0068;
    ctx.strokeStyle = "#38BDF8";
    ctx.stroke();
  }

  ctx.restore(); // End iceberg transform

  // Scene 0 Melting Water Droplets dripping from glacier ledges strictly INTO ocean crest (vanish at waterline)
  if (dripAlpha > 0.02) {
    const drops = [-0.105, 0.095];
    for (let d = 0; d < drops.length; d++) {
      const dp = (cycleNorm * 8 + d * 0.5) % 1;
      const startY = iceAnchorY - iceAboveH * 0.35;
      const endY = seaSurfaceY - minSide * 0.004;
      if (endY > startY + minSide * 0.015) {
        const dy = lerp(startY, endY, dp * dp * 0.6 + dp * 0.4);
        const dx = emblemCx + minSide * drops[d];
        const da = Math.sin(Math.PI * dp) * dripAlpha;
        if (da > 0.04) {
          ctx.save();
          ctx.globalAlpha = da;
          ctx.beginPath();
          ctx.moveTo(dx, dy - minSide * 0.012);
          ctx.quadraticCurveTo(dx + minSide * 0.008, dy + minSide * 0.002, dx, dy + minSide * 0.007);
          ctx.quadraticCurveTo(dx - minSide * 0.008, dy + minSide * 0.002, dx, dy - minSide * 0.012);
          ctx.closePath();
          ctx.fillStyle = "#7DD3FC";
          ctx.fill();
          ctx.restore();
        }
      }
    }
  }

  // Scene 1 Arctic Chill Wind Arcs & Hexagonal Frost Crystals strictly arcing clear above glacier summit
  if (chillWindAlpha > 0.02) {
    const skyBaseY = emblemCy - minSide * 0.173;
    // Crisp curved breeze streamlines clearly overhead glacier arch (zero peak touch)
    for (let w = 0; w < 2; w++) {
      const wp = (cycleNorm * 5 + w * 0.5) % 1;
      const wAlpha = Math.sin(Math.PI * wp) * chillWindAlpha * 0.65;
      if (wAlpha > 0.03) {
        const yOff = (w === 0 ? -0.004 : 0.003) * minSide;
        const arcCenterX = lerp(emblemCx - minSide * 0.11, emblemCx + minSide * 0.11, wp);
        ctx.beginPath();
        ctx.moveTo(arcCenterX - minSide * 0.036, skyBaseY + yOff);
        ctx.quadraticCurveTo(arcCenterX, skyBaseY + yOff - minSide * 0.016, arcCenterX + minSide * 0.036, skyBaseY + yOff);
        ctx.lineWidth = Math.max(1.4, minSide * 0.0028);
        ctx.strokeStyle = "rgba(186, 230, 253, " + wAlpha.toFixed(3) + ")";
        ctx.stroke();
      }
    }
    for (let k = 0; k < 3; k++) {
      const wp = (cycleNorm * 6 + k * 0.33) % 1;
      const wx = lerp(emblemCx - minSide * 0.140, emblemCx + minSide * 0.140, wp);
      const archLift = Math.sin(Math.PI * wp) * minSide * 0.015;
      const wy = skyBaseY + (k - 1) * minSide * 0.006 - archLift;
      const wa = Math.sin(Math.PI * wp) * chillWindAlpha * 0.92;
      drawHexCrystal(wx, wy, minSide * 0.0080, wp * Math.PI * 1.5, "#BAE6FD", wa);
    }
  }

  // Foreground Translucent Water Crest Overlay (Exact integer harmonic period 5 -> zero loop jump!)
  const wavePhaseFront = cycleNorm * Math.PI * 2 * 5;
  ctx.beginPath();
  ctx.moveTo(emblemCx - emblemR - 4, emblemCy + emblemR + 4);
  for (let i = 0; i <= 26; i++) {
    const u = i / 26;
    const wx = lerp(emblemCx - emblemR - 4, emblemCx + emblemR + 4, u);
    const wy = seaSurfaceY + Math.cos(u * Math.PI * 2.5 - wavePhaseFront) * (deepWaveAmp * 0.78);
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(emblemCx + emblemR + 4, emblemCy + emblemR + 4);
  ctx.closePath();
  ctx.fillStyle = "rgba(14, 165, 233, 0.36)";
  ctx.fill();

  // Crisp Foam/Waterline Stroke
  ctx.beginPath();
  for (let i = 0; i <= 26; i++) {
    const u = i / 26;
    const wx = lerp(emblemCx - emblemR - 4, emblemCx + emblemR + 4, u);
    const wy = seaSurfaceY + Math.cos(u * Math.PI * 2.5 - wavePhaseFront) * (deepWaveAmp * 0.78);
    if (i === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.lineWidth = Math.max(2, minSide * 0.0046);
  ctx.strokeStyle = "#7DD3FC";
  ctx.stroke();

  ctx.restore(); // End circular emblem clip

  // Outer Circular Emblem Border Ring
  ctx.beginPath();
  ctx.arc(emblemCx, emblemCy, emblemR, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.0095;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(emblemCx, emblemCy, emblemR, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.0052;
  ctx.strokeStyle = "#38BDF8";
  ctx.stroke();

  // 6. Right-Side Vertical Sea-Level Equilibrium Scale Bar (Strictly clear of circular emblem, synchronized to seaSurfaceY!)
  const gWidth = minSide * 0.032;
  const gX = emblemCx + emblemR + minSide * 0.052;
  const gLeft = gX - gWidth * 0.5;
  const alertY = lerp(gaugeBotY, gaugeTopY, 0.54); // Threshold line matching rising high-water level

  // Gauge capsule track housing
  roundedRectPath(gLeft, gaugeTopY - minSide * 0.014, gWidth, gaugeH + minSide * 0.028, gWidth * 0.5);
  ctx.fillStyle = "#081729";
  ctx.fill();

  // Clipped liquid level fill bar inside gauge column
  ctx.save();
  roundedRectPath(gLeft + strokeW * 0.4, gaugeTopY - minSide * 0.010, gWidth - strokeW * 0.8, gaugeH + minSide * 0.020, gWidth * 0.42);
  ctx.clip();

  const barColTop = lerpColor([56, 189, 248], [251, 113, 133], alertLevel * 0.85);
  const barColBot = "#0284C7";
  const barGrad = ctx.createLinearGradient(0, seaSurfaceY, 0, gaugeBotY + minSide * 0.015);
  barGrad.addColorStop(0, barColTop);
  barGrad.addColorStop(0.55, "#0EA5E9");
  barGrad.addColorStop(1, barColBot);
  ctx.fillStyle = barGrad;
  ctx.fillRect(gLeft, seaSurfaceY, gWidth, gaugeBotY + minSide * 0.02 - seaSurfaceY);

  // Top meniscus highlight line inside gauge bar
  ctx.beginPath();
  ctx.moveTo(gLeft, seaSurfaceY);
  ctx.lineTo(gLeft + gWidth, seaSurfaceY);
  ctx.lineWidth = Math.max(2, minSide * 0.0038);
  ctx.strokeStyle = "#F0F9FF";
  ctx.stroke();
  ctx.restore();

  // Outer gauge rim border
  roundedRectPath(gLeft, gaugeTopY - minSide * 0.014, gWidth, gaugeH + minSide * 0.028, gWidth * 0.5);
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = "#7DD3FC";
  ctx.stroke();

  // Horizontal Scale Tick Marks along Left Edge of Gauge & Alert Coral Threshold Bar
  for (let tk = 0; tk <= 4; tk++) {
    const ty = lerp(gaugeBotY, gaugeTopY, tk / 4);
    ctx.beginPath();
    ctx.moveTo(gLeft - minSide * 0.010, ty);
    ctx.lineTo(gLeft - minSide * 0.002, ty);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0026);
    ctx.strokeStyle = "rgba(186, 230, 253, 0.55)";
    ctx.stroke();
  }

  // Alert Coral Threshold Indicator Line & Beacon Dot above Gauge
  ctx.beginPath();
  ctx.moveTo(gLeft - minSide * 0.014, alertY);
  ctx.lineTo(gLeft + gWidth + minSide * 0.014, alertY);
  ctx.lineWidth = Math.max(2, minSide * 0.0036);
  ctx.strokeStyle = "#FB7185";
  ctx.stroke();

  // Sliding Sea-Level Pointer Triangle on Right Side of Gauge Track
  const ptrX = gLeft + gWidth + minSide * 0.006;
  ctx.beginPath();
  ctx.moveTo(ptrX, seaSurfaceY);
  ctx.lineTo(ptrX + minSide * 0.016, seaSurfaceY - minSide * 0.010);
  ctx.lineTo(ptrX + minSide * 0.016, seaSurfaceY + minSide * 0.010);
  ctx.closePath();
  ctx.fillStyle = lerpColor([240, 249, 255], [251, 113, 133], alertLevel);
  ctx.fill();
  ctx.lineWidth = Math.max(1.2, strokeW * 0.55);
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutBackSoft(x) {
    const k = clamp01(x);
    const c1 = 1.15;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2);
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function bellEnvelope(p, start, end) {
    if (p <= start || p >= end) return 0;
    return Math.sin(Math.PI * ((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function traceShieldPath(cxS, cyS, halfW, halfH) {
    ctx.beginPath();
    ctx.moveTo(cxS, cyS - halfH);
    ctx.lineTo(cxS + halfW, cyS - halfH * 0.62);
    ctx.bezierCurveTo(
      cxS + halfW, cyS + halfH * 0.16,
      cxS + halfW * 0.56, cyS + halfH * 0.72,
      cxS, cyS + halfH
    );
    ctx.bezierCurveTo(
      cxS - halfW * 0.56, cyS + halfH * 0.72,
      cxS - halfW, cyS + halfH * 0.16,
      cxS - halfW, cyS - halfH * 0.62
    );
    ctx.closePath();
  }

  function drawMicroLeaf(x, y, angle, len, fillMain, ink, lineW) {
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);
    const hw = len * 0.42;
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(len * 0.30, -hw, len * 0.80, -hw * 0.70, len, 0);
    ctx.bezierCurveTo(len * 0.80, hw * 0.70, len * 0.30, hw, 0, 0);
    ctx.closePath();
    ctx.fillStyle = fillMain;
    ctx.fill();
    if (ink) {
      ctx.lineWidth = lineW;
      ctx.strokeStyle = ink;
      ctx.stroke();
    }
    ctx.restore();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (Deep Charcoal Emerald, zero glow, zero border/brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#081014");
  bgGrad.addColorStop(0.52, "#0D1E24");
  bgGrad.addColorStop(1, "#122B33");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let devExpand = 0;
  let screenAlpha = 0;
  let chartTrim = 0;
  let kpiFill = 0;
  let popShield = 0;
  let shieldCircuit = 0;
  let shieldCheck = 0;
  let popCard = 0;
  let coinStage = 0;
  let levAmp = 0;
  let gleamSweep = -1;

  if (currentScene === 0) {
    // Scene 0: Mint capsule morphs smoothly into central Slate Obsidian Eco-Tracker + green downward carbon line draws
    devExpand = easeOutBackSoft(clamp01((sceneProgress - 0.06) / 0.42));
    if (sceneProgress <= 0.06) devExpand = 0;
    screenAlpha = smoothRange(sceneProgress, 0.36, 0.62);
    chartTrim = smoothRange(sceneProgress, 0.48, 0.94);
    kpiFill = smoothRange(sceneProgress, 0.56, 0.96);
    popShield = 0;
    shieldCircuit = 0;
    shieldCheck = 0;
    popCard = 0;
    coinStage = 0;
    levAmp = 0;
    gleamSweep = -1;
  } else if (currentScene === 1) {
    // Scene 1: Staggered fan-out into disjoint outer lanes: Left Aqua Shield -> Top-Right Carbon Card -> Bottom-Right Gold Coin Stack
    devExpand = 1;
    screenAlpha = 1;
    chartTrim = 1;
    kpiFill = 1;
    popShield = easeOutBackSoft(clamp01((sceneProgress - 0.04) / 0.28));
    if (sceneProgress <= 0.04) popShield = 0;
    shieldCircuit = smoothRange(sceneProgress, 0.20, 0.54);
    shieldCheck = smoothRange(sceneProgress, 0.36, 0.66);
    popCard = easeOutBackSoft(clamp01((sceneProgress - 0.18) / 0.30));
    if (sceneProgress <= 0.18) popCard = 0;
    coinStage = smoothRange(sceneProgress, 0.34, 0.90);
    levAmp = 0;
    gleamSweep = -1;
  } else {
    // Scene 2: Calm coordinated levitation + Earth badge gleam, then reverse smooth tuck-in back to starting Mint capsule
    levAmp = bellEnvelope(sceneProgress, 0.0, 0.56) * minSide * 0.0075;
    gleamSweep = (sceneProgress >= 0.06 && sceneProgress <= 0.46) ? (sceneProgress - 0.06) / 0.40 : -1;

    const revS = 1 - smoothRange(sceneProgress, 0.46, 0.72);
    const revC = 1 - smoothRange(sceneProgress, 0.42, 0.68);
    const revCoins = 1 - smoothRange(sceneProgress, 0.38, 0.66);
    popShield = revS;
    shieldCircuit = revS;
    shieldCheck = revS;
    popCard = revC;
    coinStage = revCoins;

    screenAlpha = 1 - smoothRange(sceneProgress, 0.68, 0.84);
    chartTrim = 1 - smoothRange(sceneProgress, 0.64, 0.80);
    kpiFill = 1 - smoothRange(sceneProgress, 0.62, 0.78);
    devExpand = 1 - smoothRange(sceneProgress, 0.76, 0.96);
  }

  // 3. Layout Coordinates (Strictly disjoint zones: >= 0.045 * minSide clearance around central tablet!)
  const cx = width * 0.5;
  const cy = height * 0.50;
  const strokeW = Math.max(2, minSide * 0.0050);
  const darkInk = "#060B0E";

  const devW = lerp(minSide * 0.176, minSide * 0.252, devExpand);
  const devH = lerp(minSide * 0.066, minSide * 0.336, devExpand);
  const devFloatY = Math.sin(cycleNorm * Math.PI * 2 * 4) * levAmp;
  const devCy = cy + devFloatY;

  // Satellite Z-layer behind opaque central device (strictly clean separation without overlapping lines)

  // 4. Left Satellite: Aqua Leaf Verification Shield (cx - 0.242 * minSide -> 0.054 clear gap from device!)
  if (popShield > 0.02) {
    const shFloat = Math.sin(cycleNorm * Math.PI * 2 * 4 + 1.2) * levAmp;
    const shX = lerp(cx, cx - minSide * 0.242, popShield);
    const shY = lerp(cy, cy - minSide * 0.010 + shFloat, clamp01(popShield));
    const shScale = clamp01(popShield * 1.1);

    ctx.save();
    ctx.translate(shX, shY);
    ctx.scale(shScale, shScale);

    const shW = minSide * 0.060;
    const shH = minSide * 0.074;
    traceShieldPath(0, 0, shW, shH);
    const shGrad = ctx.createLinearGradient(0, -shH, 0, shH);
    shGrad.addColorStop(0, "#134E4A");
    shGrad.addColorStop(1, "#0F2F32");
    ctx.fillStyle = shGrad;
    ctx.fill();

    // Inner circuit trace lines clipped nicely inside shield
    if (shieldCircuit > 0.01) {
      ctx.save();
      traceShieldPath(0, 0, shW * 0.88, shH * 0.88);
      ctx.clip();

      ctx.beginPath();
      ctx.moveTo(0, -shH * 0.62);
      ctx.lineTo(0, -shH * 0.30);
      ctx.moveTo(-shW * 0.55, -shH * 0.20);
      ctx.lineTo(-shW * 0.22, -shH * 0.20);
      ctx.moveTo(shW * 0.55, -shH * 0.20);
      ctx.lineTo(shW * 0.22, -shH * 0.20);
      ctx.moveTo(0, shH * 0.34);
      ctx.lineTo(0, shH * 0.66);
      ctx.lineWidth = Math.max(1.5, minSide * 0.0028);
      ctx.strokeStyle = "rgba(45, 212, 191, " + (shieldCircuit * 0.85).toFixed(3) + ")";
      ctx.stroke();
      ctx.restore();
    }

    // Crisp Aqua Shield Outer Rim
    traceShieldPath(0, 0, shW, shH);
    ctx.lineWidth = strokeW * 0.92;
    ctx.strokeStyle = "#2DD4BF";
    ctx.stroke();

    // Animated Verification Leaf Checkmark inside Shield Center
    if (shieldCheck > 0.02) {
      ctx.beginPath();
      const x0 = -minSide * 0.020;
      const y0 = minSide * 0.002;
      const x1 = -minSide * 0.004;
      const y1 = minSide * 0.018;
      const x2 = minSide * 0.024;
      const y2 = -minSide * 0.018;
      ctx.moveTo(x0, y0);
      if (shieldCheck <= 0.45) {
        const k = shieldCheck / 0.45;
        ctx.lineTo(lerp(x0, x1, k), lerp(y0, y1, k));
      } else {
        const k = (shieldCheck - 0.45) / 0.55;
        ctx.lineTo(x1, y1);
        ctx.lineTo(lerp(x1, x2, k), lerp(y1, y2, k));
      }
      ctx.lineWidth = minSide * 0.0072;
      ctx.strokeStyle = "#34D399";
      ctx.stroke();
    }
    ctx.restore();
  }

  // 5. Upper-Right Satellite: Tilted Carbon Offset Credit Card (cx + 0.252 * minSide, cy - 0.088 * minSide -> clear of device & coins!)
  if (popCard > 0.02) {
    const cdFloat = Math.sin(cycleNorm * Math.PI * 2 * 4 + 2.4) * levAmp;
    const cdX = lerp(cx, cx + minSide * 0.252, popCard);
    const cdY = lerp(cy, cy - minSide * 0.088 + cdFloat, clamp01(popCard));
    const cdScale = clamp01(popCard * 1.1);

    ctx.save();
    ctx.translate(cdX, cdY);
    ctx.rotate(-0.14 * clamp01(popCard));
    ctx.scale(cdScale, cdScale);

    const cw = minSide * 0.130;
    const ch = minSide * 0.082;
    roundedRectPath(-cw * 0.5, -ch * 0.5, cw, ch, minSide * 0.014);
    const cardGrad = ctx.createLinearGradient(-cw * 0.5, -ch * 0.5, cw * 0.5, ch * 0.5);
    cardGrad.addColorStop(0, "#10B981");
    cardGrad.addColorStop(0.55, "#059669");
    cardGrad.addColorStop(1, "#047857");
    ctx.fillStyle = cardGrad;
    ctx.fill();

    // Specular diagonal band clipped inside card
    if (gleamSweep >= 0 && gleamSweep <= 1) {
      ctx.save();
      ctx.clip();
      const gx = lerp(-cw * 0.85, cw * 0.85, gleamSweep);
      ctx.beginPath();
      ctx.moveTo(gx, -ch);
      ctx.lineTo(gx + minSide * 0.026, -ch);
      ctx.lineTo(gx - minSide * 0.014, ch);
      ctx.lineTo(gx - minSide * 0.040, ch);
      ctx.closePath();
      ctx.fillStyle = "rgba(255, 255, 255, 0.26)";
      ctx.fill();
      ctx.restore();
    }

    roundedRectPath(-cw * 0.5, -ch * 0.5, cw, ch, minSide * 0.014);
    ctx.lineWidth = strokeW * 0.88;
    ctx.strokeStyle = "#6EE7B7";
    ctx.stroke();

    // Amber EMV Smart Chip
    roundedRectPath(-cw * 0.36, -ch * 0.16, minSide * 0.024, minSide * 0.018, minSide * 0.004);
    ctx.fillStyle = "#FBBF24";
    ctx.fill();
    ctx.lineWidth = Math.max(1.2, minSide * 0.0022);
    ctx.strokeStyle = "#78350F";
    ctx.stroke();

    // Mini flat leaf emblem upper-right of card
    drawMicroLeaf(cw * 0.18, -ch * 0.18, -0.5, minSide * 0.024, "#ECFDF5", null, 0);

    // Sleek Credit Balance Stripes
    roundedRectPath(-cw * 0.36, ch * 0.20, cw * 0.42, minSide * 0.007, minSide * 0.0035);
    ctx.fillStyle = "rgba(236, 253, 245, 0.82)";
    ctx.fill();
    roundedRectPath(cw * 0.12, ch * 0.20, cw * 0.24, minSide * 0.007, minSide * 0.0035);
    ctx.fillStyle = "#FBBF24";
    ctx.fill();

    ctx.restore();
  }

  // 6. Lower-Right Satellite: Stacked Amber-Gold Eco Coins (cx + 0.242 * minSide, base cy + 0.145 * minSide)
  if (coinStage > 0.01) {
    const cnFloat = Math.sin(cycleNorm * Math.PI * 2 * 4 + 3.6) * levAmp;
    const coinCx = cx + minSide * 0.242;
    const coinBaseY = cy + minSide * 0.142 + cnFloat;
    const coinRx = minSide * 0.044;
    const coinRy = minSide * 0.013;
    const discH = minSide * 0.014;
    const stepH = minSide * 0.017;

    for (let c = 0; c < 4; c++) {
      const cLocal = clamp01((coinStage - c * 0.16) / 0.36);
      if (cLocal <= 0.02) continue;

      // Coin clears horizontally smoothly first, then drops straight vertically onto aligned stack column
      const horizReach = smoothRange(cLocal, 0.0, 0.38);
      const dropNorm = smoothRange(cLocal, 0.28, 1.0);
      const cxCur = lerp(cx, coinCx, horizReach);
      const restY = coinBaseY - c * stepH;
      const startDropY = restY - minSide * 0.052;
      const cyCur = lerp(startDropY, restY, dropNorm);

      ctx.save();
      ctx.globalAlpha = clamp01(cLocal * 3.0);

      // Cylinder edge skirt
      ctx.beginPath();
      ctx.moveTo(cxCur - coinRx, cyCur);
      ctx.lineTo(cxCur - coinRx, cyCur + discH);
      ctx.ellipse(cxCur, cyCur + discH, coinRx, coinRy, 0, Math.PI, 0, true);
      ctx.lineTo(cxCur + coinRx, cyCur);
      ctx.closePath();
      ctx.fillStyle = "#D97706";
      ctx.fill();
      ctx.lineWidth = Math.max(1.5, strokeW * 0.65);
      ctx.strokeStyle = darkInk;
      ctx.stroke();

      // Coin top bright face
      ctx.beginPath();
      ctx.ellipse(cxCur, cyCur, coinRx, coinRy, 0, 0, Math.PI * 2);
      ctx.fillStyle = "#FBBF24";
      ctx.fill();
      ctx.lineWidth = Math.max(1.5, strokeW * 0.65);
      ctx.strokeStyle = darkInk;
      ctx.stroke();

      // Inner coin ring accent & tiny leaf emboss on top coin
      if (c === 3) {
        ctx.beginPath();
        ctx.ellipse(cxCur, cyCur, coinRx * 0.72, coinRy * 0.72, 0, 0, Math.PI * 2);
        ctx.lineWidth = Math.max(1.2, minSide * 0.0022);
        ctx.strokeStyle = "#FEF3C7";
        ctx.stroke();

        ctx.save();
        ctx.translate(cxCur, cyCur);
        ctx.scale(1.0, 0.34);
        drawMicroLeaf(-minSide * 0.011, 0, -0.15, minSide * 0.022, "#065F46", null, 0);
        ctx.restore();
      }
      ctx.restore();
    }
  }

  // 7. Central Morphing Capsule -> Slate Obsidian Eco-Tracker Device & Animated ESG Interface
  const devX = cx - devW * 0.5;
  const devY = devCy - devH * 0.5;
  const chassisRad = lerp(minSide * 0.033, minSide * 0.028, devExpand);

  roundedRectPath(devX, devY, devW, devH, chassisRad);
  // Smooth visual color morph from bright Mint Capsule Pill (#10B981) -> Dark Slate Obsidian Device (#1E293B)
  const bodyTopCol = lerpColor([52, 211, 153], [30, 41, 59], smoothRange(devExpand, 0.15, 0.75));
  const bodyBotCol = lerpColor([16, 185, 129], [15, 23, 42], smoothRange(devExpand, 0.15, 0.75));
  const dGrad = ctx.createLinearGradient(devX, devY, devX, devY + devH);
  dGrad.addColorStop(0, bodyTopCol);
  dGrad.addColorStop(1, bodyBotCol);
  ctx.fillStyle = dGrad;
  ctx.fill();

  // Chassis outer border stroke
  roundedRectPath(devX, devY, devW, devH, chassisRad);
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = lerpColor([167, 243, 208], [71, 85, 105], smoothRange(devExpand, 0.15, 0.75));
  ctx.stroke();

  // Compact Capsule Pill Icon (visible when collapsed at t=0 and t=20!)
  const pillAlpha = 1 - smoothRange(devExpand, 0.05, 0.35);
  if (pillAlpha > 0.02) {
    ctx.save();
    ctx.globalAlpha = pillAlpha;
    drawMicroLeaf(cx - minSide * 0.042, devCy + minSide * 0.006, -0.35, minSide * 0.034, "#064E3B", null, 0);
    roundedRectPath(cx - minSide * 0.005, devCy - minSide * 0.007, minSide * 0.052, minSide * 0.014, minSide * 0.007);
    ctx.fillStyle = "#064E3B";
    ctx.fill();
    ctx.restore();
  }

  // Full Device Screen & ESG Carbon Reduction UI
  if (screenAlpha > 0.02) {
    const padX = minSide * 0.020;
    const padTop = minSide * 0.024;
    const scrX = devX + padX;
    const scrY = devY + padTop;
    const scrW = devW - padX * 2;
    const scrH = devH - padTop * 2;

    ctx.save();
    ctx.globalAlpha = screenAlpha;

    // Inner OLED screen panel
    roundedRectPath(scrX, scrY, scrW, scrH, minSide * 0.018);
    ctx.fillStyle = "#0B121D";
    ctx.fill();
    ctx.clip();

    // 7a. Top Screen Header: Micro Rotating/Gleaming Earth Emblem + ESG Status Bar
    const hCenterY = scrY + minSide * 0.034;
    const globeR = minSide * 0.021;
    const globeX = scrX + minSide * 0.030;

    ctx.beginPath();
    ctx.arc(globeX, hCenterY, globeR, 0, Math.PI * 2);
    ctx.fillStyle = "#0284C7";
    ctx.fill();

    // Mini continents inside globe
    ctx.save();
    ctx.beginPath();
    ctx.arc(globeX, hCenterY, globeR, 0, Math.PI * 2);
    ctx.clip();
    ctx.beginPath();
    ctx.ellipse(globeX - globeR * 0.32, hCenterY - globeR * 0.15, globeR * 0.45, globeR * 0.32, -0.3, 0, Math.PI * 2);
    ctx.ellipse(globeX + globeR * 0.36, hCenterY + globeR * 0.25, globeR * 0.40, globeR * 0.28, 0.2, 0, Math.PI * 2);
    ctx.fillStyle = "#34D399";
    ctx.fill();

    // Sparkling Gleam across Earth emblem in Scene 2
    if (gleamSweep >= 0 && gleamSweep <= 1) {
      const gx = lerp(globeX - globeR * 1.4, globeX + globeR * 1.4, gleamSweep);
      ctx.beginPath();
      ctx.moveTo(gx, hCenterY - globeR);
      ctx.lineTo(gx + minSide * 0.012, hCenterY - globeR);
      ctx.lineTo(gx - minSide * 0.008, hCenterY + globeR);
      ctx.lineTo(gx - minSide * 0.020, hCenterY + globeR);
      ctx.closePath();
      ctx.fillStyle = "rgba(255, 255, 255, 0.48)";
      ctx.fill();
    }
    ctx.restore();

    ctx.beginPath();
    ctx.arc(globeX, hCenterY, globeR, 0, Math.PI * 2);
    ctx.lineWidth = Math.max(1.2, minSide * 0.0024);
    ctx.strokeStyle = "#38BDF8";
    ctx.stroke();

    // Top-right ESG score bars
    const barX = globeX + globeR + minSide * 0.016;
    const barMaxW = scrX + scrW - minSide * 0.016 - barX;
    roundedRectPath(barX, hCenterY - minSide * 0.012, barMaxW, minSide * 0.010, minSide * 0.005);
    ctx.fillStyle = "#1E293B";
    ctx.fill();
    roundedRectPath(barX, hCenterY - minSide * 0.012, barMaxW * clamp01(0.25 + 0.65 * kpiFill), minSide * 0.010, minSide * 0.005);
    ctx.fillStyle = "#34D399";
    ctx.fill();

    roundedRectPath(barX, hCenterY + minSide * 0.004, barMaxW * 0.65, minSide * 0.008, minSide * 0.004);
    ctx.fillStyle = "#334155";
    ctx.fill();

    // 7b. Center Chart Area: Carbon Emissions Downward Reduction Graph
    const chX = scrX + minSide * 0.014;
    const chY = scrY + minSide * 0.072;
    const chW = scrW - minSide * 0.028;
    const chH = minSide * 0.128;

    roundedRectPath(chX, chY, chW, chH, minSide * 0.012);
    ctx.fillStyle = "#111C2D";
    ctx.fill();

    // Clean horizontal chart grid lines
    for (let g = 1; g <= 3; g++) {
      const gy = chY + (chH * g) / 4;
      ctx.beginPath();
      ctx.moveTo(chX + minSide * 0.012, gy);
      ctx.lineTo(chX + chW - minSide * 0.012, gy);
      ctx.lineWidth = Math.max(1, minSide * 0.0018);
      ctx.strokeStyle = "rgba(148, 163, 184, 0.16)";
      ctx.stroke();
    }

    // Downward carbon curve points (starts high Amber upper-left -> settles low Mint lower-right)
    const chartPts = [
      [chX + chW * 0.10, chY + chH * 0.24],
      [chX + chW * 0.36, chY + chH * 0.32],
      [chX + chW * 0.64, chY + chH * 0.58],
      [chX + chW * 0.90, chY + chH * 0.78]
    ];

    if (chartTrim > 0.02) {
      const maxSeg = chartPts.length - 1;
      const segFloat = chartTrim * maxSeg;
      const fullSegs = Math.floor(segFloat);
      const partSeg = segFloat - fullSegs;

      // Interpolate active trimmed polyline up to curX, curY
      const drawnPts = [chartPts[0]];
      for (let s = 0; s < maxSeg; s++) {
        if (s < fullSegs) {
          drawnPts.push(chartPts[s + 1]);
        } else if (s === fullSegs && partSeg > 0.001) {
          drawnPts.push([
            lerp(chartPts[s][0], chartPts[s + 1][0], partSeg),
            lerp(chartPts[s][1], chartPts[s + 1][1], partSeg)
          ]);
        }
      }

      if (drawnPts.length >= 2) {
        // Subtle gradient area under drawn carbon reduction curve
        ctx.beginPath();
        ctx.moveTo(drawnPts[0][0], chY + chH - minSide * 0.006);
        for (let p = 0; p < drawnPts.length; p++) {
          ctx.lineTo(drawnPts[p][0], drawnPts[p][1]);
        }
        ctx.lineTo(drawnPts[drawnPts.length - 1][0], chY + chH - minSide * 0.006);
        ctx.closePath();
        const areaGrad = ctx.createLinearGradient(0, chY, 0, chY + chH);
        areaGrad.addColorStop(0, "rgba(251, 191, 36, 0.22)");
        areaGrad.addColorStop(1, "rgba(52, 211, 153, 0.05)");
        ctx.fillStyle = areaGrad;
        ctx.fill();

        // Crisp Amber-to-Mint Reduction Line Stroke
        ctx.beginPath();
        ctx.moveTo(drawnPts[0][0], drawnPts[0][1]);
        for (let p = 1; p < drawnPts.length; p++) {
          ctx.lineTo(drawnPts[p][0], drawnPts[p][1]);
        }
        const lineGrad = ctx.createLinearGradient(chartPts[0][0], 0, chartPts[3][0], 0);
        lineGrad.addColorStop(0, "#FBBF24");
        lineGrad.addColorStop(0.5, "#2DD4BF");
        lineGrad.addColorStop(1, "#34D399");
        ctx.lineWidth = minSide * 0.0065;
        ctx.strokeStyle = lineGrad;
        ctx.stroke();

        // Endpoint beacon circle
        const lastPt = drawnPts[drawnPts.length - 1];
        ctx.beginPath();
        ctx.arc(lastPt[0], lastPt[1], minSide * 0.0065, 0, Math.PI * 2);
        ctx.fillStyle = chartTrim > 0.75 ? "#34D399" : "#FBBF24";
        ctx.fill();
        ctx.lineWidth = Math.max(1.2, minSide * 0.0022);
        ctx.strokeStyle = "#ECFDF5";
        ctx.stroke();
      }
    }

    // 7c. Bottom Screen Metric Trio Pills (Well below chart box)
    const botY = chY + chH + minSide * 0.016;
    const pillH = scrY + scrH - botY - minSide * 0.010;
    const gapP = minSide * 0.010;
    const pillW = (chW - gapP * 2) / 3;
    const kpiColors = ["#34D399", "#2DD4BF", "#FBBF24"];
    const kpiHeights = [0.76, 0.88, 0.54];

    for (let k = 0; k < 3; k++) {
      const px = chX + k * (pillW + gapP);
      roundedRectPath(px, botY, pillW, pillH, minSide * 0.009);
      ctx.fillStyle = "#162235";
      ctx.fill();

      const fillBarW = pillW * 0.68 * kpiFill * kpiHeights[k];
      roundedRectPath(px + pillW * 0.16, botY + pillH * 0.56, pillW * 0.68, minSide * 0.007, minSide * 0.0035);
      ctx.fillStyle = "#0B121D";
      ctx.fill();
      if (fillBarW > 1) {
        roundedRectPath(px + pillW * 0.16, botY + pillH * 0.56, fillBarW, minSide * 0.007, minSide * 0.0035);
        ctx.fillStyle = kpiColors[k];
        ctx.fill();
      }

      // Crisp colored status dot above bar
      ctx.beginPath();
      ctx.arc(px + pillW * 0.5, botY + pillH * 0.30, minSide * 0.0050, 0, Math.PI * 2);
      ctx.fillStyle = kpiColors[k];
      ctx.fill();
    }

    ctx.restore();
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function easeOutBackSoft(x) {
    const k = clamp01(x);
    const c1 = 1.25;
    const c3 = c1 + 1;
    return 1 + c3 * Math.pow(k - 1, 3) + c1 * Math.pow(k - 1, 2);
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function bellEnvelope(p, start, end) {
    if (p <= start || p >= end) return 0;
    return Math.sin(Math.PI * ((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawSproutLeaf(x, y, angle, length, widthFactor, fillLight, fillDark, ink, lineW) {
    if (length <= 0.5) return;
    const halfW = length * widthFactor;
    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(length * 0.28, -halfW, length * 0.78, -halfW * 0.72, length, 0);
    ctx.bezierCurveTo(length * 0.78, halfW * 0.72, length * 0.28, halfW, 0, 0);
    ctx.closePath();
    ctx.fillStyle = fillLight;
    ctx.fill();

    ctx.save();
    ctx.clip();
    ctx.fillStyle = fillDark;
    ctx.fillRect(0, 0, length, halfW);
    ctx.restore();

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(length * 0.28, -halfW, length * 0.78, -halfW * 0.72, length, 0);
    ctx.bezierCurveTo(length * 0.78, halfW * 0.72, length * 0.28, halfW, 0, 0);
    ctx.closePath();
    ctx.lineWidth = lineW;
    ctx.strokeStyle = ink;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(length * 0.1, 0);
    ctx.lineTo(length * 0.76, 0);
    ctx.lineWidth = Math.max(1.2, lineW * 0.65);
    ctx.strokeStyle = "rgba(240, 253, 244, 0.55)";
    ctx.stroke();

    ctx.restore();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (Dark Olive Umber, zero glow, zero edge border)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#11130A");
  bgGrad.addColorStop(0.52, "#1B200F");
  bgGrad.addColorStop(1, "#262D16");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let lidOpen = 0;
  let fillLevel = 0.22;
  let drumTilt = 0;
  let crankAngle = 0;
  let microbeAlpha = 0;
  let humusShift = 0;
  let tempGauge = 0.20;
  let drawerOpen = 0;
  let sproutGrow = 0;
  let scrapProgress = -1;

  if (currentScene === 0) {
    // Scene 0: Top hatch opens -> organic scraps drop into tumbler -> hatch latches shut
    const openUp = easeOutBackSoft(clamp01((sceneProgress - 0.04) / 0.18));
    const closeDown = smoothRange(sceneProgress, 0.76, 0.94);
    lidOpen = sceneProgress < 0.76 ? openUp * clamp01(sceneProgress / 0.04 + 0.0) : (1 - closeDown);
    if (sceneProgress <= 0.04) lidOpen = 0;
    scrapProgress = (sceneProgress >= 0.14 && sceneProgress <= 0.74) ? (sceneProgress - 0.14) / 0.60 : -1;
    fillLevel = 0.22 + 0.58 * smoothRange(sceneProgress, 0.24, 0.74);
    drumTilt = 0;
    crankAngle = 0;
    microbeAlpha = 0;
    humusShift = 0;
    tempGauge = 0.20;
    drawerOpen = 0;
    sproutGrow = 0;
  } else if (currentScene === 1) {
    // Scene 1: Crank spins smoothly through 2 full revolutions, drum tumbles, microbes ferment -> humus + temp rises
    lidOpen = 0;
    scrapProgress = -1;
    fillLevel = 0.80;
    const crankEase = smoothRange(sceneProgress, 0.04, 0.96);
    crankAngle = crankEase * Math.PI * 4; // Exact 2 revolutions -> 0 mod 2PI cleanly at scene boundaries
    drumTilt = Math.sin(sceneProgress * Math.PI * 8) * bellEnvelope(sceneProgress, 0.04, 0.96) * 0.17;
    microbeAlpha = bellEnvelope(sceneProgress, 0.08, 0.94);
    humusShift = smoothRange(sceneProgress, 0.18, 0.88);
    tempGauge = 0.20 + 0.68 * smoothRange(sceneProgress, 0.15, 0.90);
    drawerOpen = 0;
    sproutGrow = 0;
  } else {
    // Scene 2: Bottom tray slides down cleanly on rails, humus & 3 leaf sprouts spring up -> cleanly resets before loop end
    lidOpen = 0;
    scrapProgress = -1;
    crankAngle = 0;
    drumTilt = 0;
    microbeAlpha = 0;
    const dIn = smoothRange(sceneProgress, 0.04, 0.28);
    const dOut = 1 - smoothRange(sceneProgress, 0.70, 0.95);
    drawerOpen = sceneProgress < 0.5 ? dIn : dOut;

    const sIn = easeOutBackSoft(clamp01((sceneProgress - 0.20) / 0.22));
    const sOut = 1 - smoothRange(sceneProgress, 0.58, 0.76);
    sproutGrow = sceneProgress < 0.20 ? 0 : (sceneProgress < 0.58 ? sIn : sOut);

    fillLevel = 0.80 - 0.58 * smoothRange(sceneProgress, 0.06, 0.45);
    humusShift = 1.0 - smoothRange(sceneProgress, 0.55, 0.92);
    tempGauge = 0.88 - 0.68 * smoothRange(sceneProgress, 0.45, 0.90);
  }

  // 3. Layout Coordinates (Huge clean clearances: overhead drop zone, upper-left dial outside hatch swing, lower drawer cleanly below drum)
  const cx = width * 0.5;
  const cy = height * 0.50;
  const groundY = cy + minSide * 0.255;
  const drumCy = cy - minSide * 0.042;
  const drumW = minSide * 0.228;
  const drumH = minSide * 0.146;
  const strokeW = Math.max(2, minSide * 0.0050);
  const darkInk = "#0C0F06";

  // Frame Pillar Anchors (Left & Right A-Frame bearings strictly outside rotating drum)
  const postTopX = minSide * 0.140;
  const postBotX = minSide * 0.172;
  const leftBearingX = cx - postTopX;
  const rightBearingX = cx + postTopX;

  // 4. Clean Ground Baseline Bar
  roundedRectPath(cx - minSide * 0.28, groundY, minSide * 0.56, minSide * 0.013, minSide * 0.0065);
  ctx.fillStyle = "#2E351A";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.0028);
  ctx.strokeStyle = "#4B562B";
  ctx.stroke();

  // 5. Lower Centered Harvest Cradle & Unobstructed Pop-Open Compost Drawer (Zero overhead crossbar!)
  const trayW = minSide * 0.168;
  const cradleH = minSide * 0.052;
  const cradleTopY = groundY - cradleH;
  const binRise = drawerOpen * minSide * 0.016;
  const binTopY = cradleTopY - binRise;

  // Back recessed cradle housing walls
  roundedRectPath(cx - trayW * 0.52, cradleTopY, trayW * 1.04, cradleH, minSide * 0.008);
  ctx.fillStyle = "#334155";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Emergent Humus Mound & 3 Leaf Sprouts growing cleanly UPWARD into 100% open bay below drum!
  if (drawerOpen > 0.05) {
    const soilReveal = smoothRange(drawerOpen, 0.10, 0.72);
    const soilW = trayW * 0.78 * soilReveal;
    const soilH = minSide * 0.025 * soilReveal;
    if (soilW > 1 && soilH > 1) {
      ctx.beginPath();
      ctx.ellipse(cx, binTopY + minSide * 0.003, soilW * 0.5, soilH, 0, Math.PI, 0);
      ctx.fillStyle = "#451A03";
      ctx.fill();
      ctx.lineWidth = Math.max(1.2, strokeW * 0.65);
      ctx.strokeStyle = darkInk;
      ctx.stroke();
    }

    // 3 Vibrant Green Sprouts growing unobstructed from soil crest up into open space below drum
    if (sproutGrow > 0.02) {
      const sway = Math.sin(cycleNorm * Math.PI * 2 * 6) * minSide * 0.004 * sproutGrow;
      const stemBaseY = binTopY - minSide * 0.003;
      const stemH = minSide * 0.058 * sproutGrow;

      ctx.beginPath();
      ctx.moveTo(cx, stemBaseY);
      ctx.quadraticCurveTo(cx + sway * 0.4, stemBaseY - stemH * 0.55, cx + sway, stemBaseY - stemH);
      ctx.lineWidth = Math.max(1.8, minSide * 0.0052);
      ctx.strokeStyle = "#22C55E";
      ctx.stroke();

      const leafScale = sproutGrow;
      drawSproutLeaf(cx + sway * 0.55, stemBaseY - stemH * 0.52, -Math.PI + 0.55, minSide * 0.036 * leafScale, 0.44, "#4ADE80", "#16A34A", darkInk, strokeW * 0.65);
      drawSproutLeaf(cx + sway * 0.55, stemBaseY - stemH * 0.52, -0.55, minSide * 0.036 * leafScale, 0.44, "#4ADE80", "#16A34A", darkInk, strokeW * 0.65);
      drawSproutLeaf(cx + sway, stemBaseY - stemH, -Math.PI * 0.5 + sway * 0.04, minSide * 0.034 * leafScale, 0.45, "#84CC16", "#4D7C0F", darkInk, strokeW * 0.65);
    }
  }

  // Sliding Brown Compost Drawer Bin (Elevates cleanly inside lower cradle without any top barrier!)
  roundedRectPath(cx - trayW * 0.48, binTopY, trayW * 0.96, cradleH - minSide * 0.004 + binRise * 0.4, minSide * 0.008);
  ctx.fillStyle = "#92400E";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.88;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Front Lower Apron Door Face (Slides down neatly in front of cradle groove as bin opens!)
  const frontGateShift = drawerOpen * minSide * 0.022;
  const gateH = cradleH * 0.68;
  const gateY = groundY - gateH;
  roundedRectPath(cx - trayW * 0.50, gateY + frontGateShift * 0.15, trayW * 1.00, gateH - frontGateShift * 0.15, minSide * 0.007);
  ctx.fillStyle = "#475569";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.80;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Drawer Front Handle Bar
  roundedRectPath(cx - minSide * 0.034, gateY + gateH * 0.36 + frontGateShift * 0.10, minSide * 0.068, minSide * 0.010, minSide * 0.005);
  ctx.fillStyle = "#CBD5E1";
  ctx.fill();
  ctx.lineWidth = Math.max(1.2, strokeW * 0.55);
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // 6. Side A-Frame Support Legs & Lower Side Gusset Struts (Never crosses center sprout bay!)
  for (let side = -1; side <= 1; side += 2) {
    const legAtStrutX = lerp(cx + side * postTopX, cx + side * postBotX, (groundY - cradleH * 0.5 - drumCy) / (groundY - drumCy));
    const cradleWallX = cx + side * (trayW * 0.52);
    const strutY = groundY - cradleH * 0.5;
    ctx.beginPath();
    ctx.moveTo(legAtStrutX, strutY);
    ctx.lineTo(cradleWallX, strutY);
    ctx.lineWidth = minSide * 0.011;
    ctx.strokeStyle = "#475569";
    ctx.stroke();

    const topX = cx + side * postTopX;
    const botX = cx + side * postBotX;
    ctx.beginPath();
    ctx.moveTo(topX, drumCy);
    ctx.lineTo(botX, groundY);
    ctx.lineWidth = minSide * 0.020;
    ctx.strokeStyle = darkInk;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(topX, drumCy);
    ctx.lineTo(botX, groundY);
    ctx.lineWidth = minSide * 0.012;
    ctx.strokeStyle = "#64748B";
    ctx.stroke();
  }

  // 7. Upper-Left Microbial Temperature Gauge Dial (Offset cleanly to left of drum & open hatch swing!)
  const gaugeCx = cx - minSide * 0.212;
  const gaugeCy = cy - minSide * 0.145;
  const gaugeR = minSide * 0.038;

  // Support bracket arm connecting left A-frame bearing cleanly up-left to gauge dial
  ctx.beginPath();
  ctx.moveTo(leftBearingX, drumCy);
  ctx.lineTo(leftBearingX - minSide * 0.042, drumCy - minSide * 0.038);
  ctx.lineTo(gaugeCx, gaugeCy);
  ctx.lineWidth = minSide * 0.014;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(leftBearingX, drumCy);
  ctx.lineTo(leftBearingX - minSide * 0.042, drumCy - minSide * 0.038);
  ctx.lineTo(gaugeCx, gaugeCy);
  ctx.lineWidth = minSide * 0.008;
  ctx.strokeStyle = "#64748B";
  ctx.stroke();

  // Dial Disc Case
  ctx.beginPath();
  ctx.arc(gaugeCx, gaugeCy, gaugeR, 0, Math.PI * 2);
  ctx.fillStyle = "#1E293B";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.9;
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  // Thermal color arc inside dial (Cool Olive -> Active Warm Ochre)
  const gSpanStart = Math.PI * 0.78;
  const gSpanEnd = Math.PI * 2.22;
  ctx.beginPath();
  ctx.arc(gaugeCx, gaugeCy, gaugeR * 0.68, gSpanStart, gSpanEnd);
  ctx.lineWidth = minSide * 0.0062;
  ctx.strokeStyle = "#334155";
  ctx.stroke();

  const curGaugeEnd = lerp(gSpanStart, gSpanEnd, tempGauge);
  ctx.beginPath();
  ctx.arc(gaugeCx, gaugeCy, gaugeR * 0.68, gSpanStart, curGaugeEnd);
  ctx.lineWidth = minSide * 0.0062;
  ctx.strokeStyle = lerpColor([132, 204, 22], [245, 158, 11], tempGauge);
  ctx.stroke();

  // Rotating Dial Needle
  ctx.save();
  ctx.translate(gaugeCx, gaugeCy);
  ctx.rotate(curGaugeEnd);
  ctx.beginPath();
  ctx.moveTo(-gaugeR * 0.14, 0);
  ctx.lineTo(gaugeR * 0.62, 0);
  ctx.lineWidth = Math.max(1.8, minSide * 0.0038);
  ctx.strokeStyle = "#F8FAFC";
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(0, 0, minSide * 0.0055, 0, Math.PI * 2);
  ctx.fillStyle = "#F59E0B";
  ctx.fill();
  ctx.restore();

  // 8. Scene 0 Falling Organic Scraps (Strictly centered overhead above drum hatch aperture, vanishes smoothly into aperture)
  if (scrapProgress >= 0 && scrapProgress <= 1) {
    const skyTopY = cy - minSide * 0.300;
    const targetInY = drumCy - drumH * 0.32;
    const scraps = [
      { offX: -0.022, delay: 0.00, dur: 0.36, kind: 0, rot: -0.4 },
      { offX: 0.020, delay: 0.18, dur: 0.36, kind: 1, rot: 0.3 },
      { offX: -0.010, delay: 0.36, dur: 0.36, kind: 2, rot: 0.2 },
      { offX: 0.012, delay: 0.54, dur: 0.36, kind: 0, rot: 0.5 }
    ];
    for (let i = 0; i < scraps.length; i++) {
      const sc = scraps[i];
      const sp = clamp01((scrapProgress - sc.delay) / sc.dur);
      if (sp > 0.01 && sp < 0.99) {
        const sx = cx + minSide * sc.offX + Math.sin(sp * Math.PI * 2) * minSide * 0.005;
        const sy = lerp(skyTopY, targetInY, sp * sp * 0.4 + sp * 0.6);
        const sAlpha = Math.sin(Math.PI * clamp01(sp / 0.22)) * (1 - smoothRange(sp, 0.72, 1.0));
        if (sAlpha > 0.03) {
          ctx.save();
          ctx.globalAlpha = sAlpha;
          ctx.translate(sx, sy);
          ctx.rotate(sc.rot + sp * 1.4);
          if (sc.kind === 0) {
            drawSproutLeaf(-minSide * 0.013, 0, 0, minSide * 0.026, 0.45, "#84CC16", "#4D7C0F", darkInk, strokeW * 0.55);
          } else if (sc.kind === 1) {
            roundedRectPath(-minSide * 0.011, -minSide * 0.011, minSide * 0.022, minSide * 0.022, minSide * 0.006);
            ctx.fillStyle = "#F59E0B";
            ctx.fill();
            ctx.lineWidth = Math.max(1.2, strokeW * 0.55);
            ctx.strokeStyle = darkInk;
            ctx.stroke();
          } else {
            ctx.beginPath();
            ctx.arc(0, 0, minSide * 0.012, 0, Math.PI);
            ctx.closePath();
            ctx.fillStyle = "#D97706";
            ctx.fill();
            ctx.lineWidth = Math.max(1.2, strokeW * 0.55);
            ctx.strokeStyle = darkInk;
            ctx.stroke();
          }
          ctx.restore();
        }
      }
    }
  }

  // 9. Central Tilting Bio-Compost Tumbler Drum, Sight Window, Hinged Top Hatch & Fermentation Texture
  // Axle Shaft Connecting Bearings Behind Drum
  ctx.beginPath();
  ctx.moveTo(leftBearingX, drumCy);
  ctx.lineTo(rightBearingX + minSide * 0.022, drumCy);
  ctx.lineWidth = minSide * 0.014;
  ctx.strokeStyle = "#94A3B8";
  ctx.stroke();

  ctx.save();
  ctx.translate(cx, drumCy);
  ctx.rotate(drumTilt);

  const dHalfW = drumW * 0.5;
  const dHalfH = drumH * 0.5;

  // Main Cylindrical Drum Shell
  roundedRectPath(-dHalfW, -dHalfH, drumW, drumH, minSide * 0.028);
  const drumGrad = ctx.createLinearGradient(0, -dHalfH, 0, dHalfH);
  drumGrad.addColorStop(0, "#F59E0B");
  drumGrad.addColorStop(0.50, "#D97706");
  drumGrad.addColorStop(1, "#B45309");
  ctx.fillStyle = drumGrad;
  ctx.fill();

  // Crisp Structural Ribs Clipped Inside Drum Body
  ctx.save();
  roundedRectPath(-dHalfW, -dHalfH, drumW, drumH, minSide * 0.028);
  ctx.clip();

  // Horizontal subtle top highlight band inside drum
  ctx.fillStyle = "rgba(254, 243, 199, 0.16)";
  ctx.fillRect(-dHalfW, -dHalfH, drumW, minSide * 0.022);

  // Twin vertical structural ribbing bands flanking central sight window
  const ribXs = [-dHalfW * 0.72, dHalfW * 0.72];
  for (let r = 0; r < ribXs.length; r++) {
    ctx.beginPath();
    ctx.moveTo(ribXs[r], -dHalfH);
    ctx.lineTo(ribXs[r], dHalfH);
    ctx.lineWidth = minSide * 0.011;
    ctx.strokeStyle = "#92400E";
    ctx.stroke();
  }
  ctx.restore();

  // Drum Outer Outline
  roundedRectPath(-dHalfW, -dHalfH, drumW, drumH, minSide * 0.028);
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Curved Front Glass Sight Window inside Drum Face
  const winW = drumW * 0.54;
  const winH = drumH * 0.56;
  const winX = -winW * 0.5;
  const winY = -winH * 0.42;

  roundedRectPath(winX, winY, winW, winH, minSide * 0.018);
  ctx.fillStyle = "#14180B";
  ctx.fill();

  // Clipped Internal Compost Material, Sloshing Rotation Shift & Golden Fermentation Microbes
  ctx.save();
  roundedRectPath(winX + strokeW * 0.35, winY + strokeW * 0.35, winW - strokeW * 0.7, winH - strokeW * 0.7, minSide * 0.015);
  ctx.clip();

  const matTopY = lerp(winY + winH, winY + minSide * 0.012, fillLevel);
  const matColorTop = lerpColor([132, 204, 22], [120, 53, 15], humusShift);
  const matColorBot = lerpColor([77, 124, 15], [69, 26, 3], humusShift);

  // Dynamic curved compost crest inside sight window
  const mixWavePhase = cycleNorm * Math.PI * 2 * 6;
  const mixAmp = minSide * 0.0045 * (microbeAlpha + 0.15);
  ctx.beginPath();
  ctx.moveTo(winX - 2, winY + winH + 4);
  for (let i = 0; i <= 14; i++) {
    const u = i / 14;
    const mx = lerp(winX - 2, winX + winW + 2, u);
    const my = matTopY + Math.sin(u * Math.PI * 2 + mixWavePhase) * mixAmp;
    ctx.lineTo(mx, my);
  }
  ctx.lineTo(winX + winW + 2, winY + winH + 4);
  ctx.closePath();

  const mGrad = ctx.createLinearGradient(0, matTopY, 0, winY + winH);
  mGrad.addColorStop(0, matColorTop);
  mGrad.addColorStop(1, matColorBot);
  ctx.fillStyle = mGrad;
  ctx.fill();

  // Crisp tumbling organic flecks inside compost bed
  const fleckPos = [
    { x: -0.28, y: 0.35, r: 0.0055, c: "#84CC16" },
    { x: 0.05, y: 0.55, r: 0.0065, c: "#D97706" },
    { x: 0.28, y: 0.30, r: 0.0050, c: "#A3E635" },
    { x: -0.14, y: 0.72, r: 0.0055, c: "#F59E0B" }
  ];
  for (let fl = 0; fl < fleckPos.length; fl++) {
    const fp = fleckPos[fl];
    const fx = fp.x * winW + Math.sin(mixWavePhase + fl * 1.6) * minSide * 0.006 * microbeAlpha;
    const fy = lerp(matTopY + minSide * 0.010, winY + winH - minSide * 0.008, fp.y);
    if (fy > matTopY + minSide * 0.004) {
      ctx.beginPath();
      ctx.arc(fx, fy, minSide * fp.r, 0, Math.PI * 2);
      ctx.fillStyle = lerpColor([163, 230, 53], [146, 64, 14], humusShift);
      ctx.fill();
    }
  }

  // Active golden microbial spark particles glowing gently inside window during fermentation
  if (microbeAlpha > 0.03) {
    for (let m = 0; m < 5; m++) {
      const mp = (cycleNorm * 8 + m * 0.2) % 1;
      const mx = lerp(-winW * 0.36, winW * 0.36, (m * 0.23 + 0.08));
      const my = lerp(winY + winH * 0.85, winY + winH * 0.16, mp);
      const ma = Math.sin(Math.PI * mp) * microbeAlpha * 0.92;
      if (ma > 0.04) {
        ctx.beginPath();
        ctx.arc(mx, my, minSide * 0.0038, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(253, 224, 71, " + ma.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // Diagonal clean glass sheen inside sight window
  ctx.beginPath();
  ctx.moveTo(winX + winW * 0.14, winY + minSide * 0.008);
  ctx.lineTo(winX + winW * 0.30, winY + minSide * 0.008);
  ctx.lineTo(winX + winW * 0.12, winY + winH - minSide * 0.008);
  ctx.lineTo(winX - minSide * 0.004, winY + winH - minSide * 0.008);
  ctx.closePath();
  ctx.fillStyle = "rgba(255, 255, 255, 0.12)";
  ctx.fill();

  ctx.restore(); // End glass window clip

  // Outer Glass Window Rim
  roundedRectPath(winX, winY, winW, winH, minSide * 0.018);
  ctx.lineWidth = Math.max(1.8, strokeW * 0.8);
  ctx.strokeStyle = "#FDE68A";
  ctx.stroke();

  // Top Loading Aperture Collar & Hinged Moss-Olive Lid (Swings upward-left smoothly clear of dial!)
  const lidW = minSide * 0.098;
  const lidH = minSide * 0.018;
  const hingeX = -lidW * 0.5;
  const hingeY = -dHalfH;

  // Dark loading collar lip when hatch is open
  roundedRectPath(-lidW * 0.46, hingeY - minSide * 0.005, lidW * 0.92, minSide * 0.010, minSide * 0.004);
  ctx.fillStyle = "#1C1917";
  ctx.fill();

  ctx.save();
  ctx.translate(hingeX, hingeY);
  ctx.rotate(-lidOpen * 1.72); // Smoothly pivots ~98 deg open leftward & up cleanly clear of dial!
  roundedRectPath(0, -lidH, lidW, lidH, minSide * 0.008);
  ctx.fillStyle = "#84CC16";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Top handle grip on hinged hatch
  roundedRectPath(lidW * 0.34, -lidH - minSide * 0.011, lidW * 0.32, minSide * 0.011, minSide * 0.005);
  ctx.fillStyle = "#CBD5E1";
  ctx.fill();
  ctx.lineWidth = Math.max(1.2, strokeW * 0.65);
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Hinge pivot bolt
  ctx.beginPath();
  ctx.arc(minSide * 0.006, -minSide * 0.003, minSide * 0.006, 0, Math.PI * 2);
  ctx.fillStyle = "#CBD5E1";
  ctx.fill();
  ctx.lineWidth = Math.max(1.2, strokeW * 0.55);
  ctx.strokeStyle = darkInk;
  ctx.stroke();
  ctx.restore();

  ctx.restore(); // End tilting drum frame

  // Left & Right A-Frame Bearing Caps (Crisp foreground mechanical caps)
  for (let side = -1; side <= 1; side += 2) {
    const bx = cx + side * postTopX;
    ctx.beginPath();
    ctx.arc(bx, drumCy, minSide * 0.015, 0, Math.PI * 2);
    ctx.fillStyle = "#334155";
    ctx.fill();
    ctx.lineWidth = strokeW * 0.78;
    ctx.strokeStyle = darkInk;
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(bx, drumCy, minSide * 0.006, 0, Math.PI * 2);
    ctx.fillStyle = "#F8FAFC";
    ctx.fill();
  }

  // 10. Right-Side Rotary Crank Handle (Spins outside right bearing with zero collision!)
  const crankPivotX = rightBearingX + minSide * 0.022;
  const crankLen = minSide * 0.044;
  ctx.save();
  ctx.translate(crankPivotX, drumCy);
  ctx.rotate(crankAngle);

  roundedRectPath(-minSide * 0.007, -minSide * 0.007, crankLen + minSide * 0.014, minSide * 0.014, minSide * 0.007);
  ctx.fillStyle = "#CBD5E1";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, strokeW * 0.72);
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Moss-olive rotating grip knob at outer tip of crank arm
  ctx.beginPath();
  ctx.arc(crankLen, 0, minSide * 0.0115, 0, Math.PI * 2);
  ctx.fillStyle = "#84CC16";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, strokeW * 0.72);
  ctx.strokeStyle = darkInk;
  ctx.stroke();
  ctx.restore();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function bellEnvelope(p, start, end) {
    if (p <= start || p >= end) return 0;
    return Math.sin(Math.PI * ((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  // Draw sculpted multi-lobe organic flat-vector landmass inside Earth clip
  function traceSculptedContinent(ox, oy, rUnit, variant) {
    ctx.beginPath();
    if (variant === 0) {
      // Sculpted Americas/Western-style double-bay contour
      ctx.moveTo(ox - rUnit * 0.24, oy - rUnit * 0.16);
      ctx.bezierCurveTo(ox - rUnit * 0.12, oy - rUnit * 0.28, ox + rUnit * 0.16, oy - rUnit * 0.24, ox + rUnit * 0.22, oy - rUnit * 0.08);
      ctx.bezierCurveTo(ox + rUnit * 0.26, oy + rUnit * 0.04, ox + rUnit * 0.08, oy + rUnit * 0.08, ox + rUnit * 0.15, oy + rUnit * 0.22);
      ctx.bezierCurveTo(ox + rUnit * 0.20, oy + rUnit * 0.34, ox - rUnit * 0.04, oy + rUnit * 0.36, ox - rUnit * 0.10, oy + rUnit * 0.22);
      ctx.bezierCurveTo(ox - rUnit * 0.14, oy + rUnit * 0.10, ox - rUnit * 0.32, oy - rUnit * 0.04, ox - rUnit * 0.24, oy - rUnit * 0.16);
    } else if (variant === 1) {
      // Sculpted Afro-Eurasian broad multi-peninsula contour
      ctx.moveTo(ox - rUnit * 0.28, oy - rUnit * 0.08);
      ctx.bezierCurveTo(ox - rUnit * 0.22, oy - rUnit * 0.25, ox + rUnit * 0.12, oy - rUnit * 0.28, ox + rUnit * 0.30, oy - rUnit * 0.14);
      ctx.bezierCurveTo(ox + rUnit * 0.38, oy - rUnit * 0.02, ox + rUnit * 0.24, oy + rUnit * 0.12, ox + rUnit * 0.12, oy + rUnit * 0.14);
      ctx.bezierCurveTo(ox + rUnit * 0.04, oy + rUnit * 0.16, ox + rUnit * 0.08, oy + rUnit * 0.30, ox - rUnit * 0.08, oy + rUnit * 0.32);
      ctx.bezierCurveTo(ox - rUnit * 0.22, oy + rUnit * 0.26, ox - rUnit * 0.16, oy + rUnit * 0.10, ox - rUnit * 0.28, oy - rUnit * 0.08);
    } else {
      // Compact Pacific / Archipelago island silhouette
      ctx.moveTo(ox - rUnit * 0.18, oy - rUnit * 0.08);
      ctx.bezierCurveTo(ox - rUnit * 0.08, oy - rUnit * 0.20, ox + rUnit * 0.16, oy - rUnit * 0.16, ox + rUnit * 0.22, oy - rUnit * 0.02);
      ctx.bezierCurveTo(ox + rUnit * 0.25, oy + rUnit * 0.10, ox + rUnit * 0.06, oy + rUnit * 0.20, ox - rUnit * 0.08, oy + rUnit * 0.14);
      ctx.bezierCurveTo(ox - rUnit * 0.20, oy + rUnit * 0.10, ox - rUnit * 0.24, oy + rUnit * 0.00, ox - rUnit * 0.18, oy - rUnit * 0.08);
    }
    ctx.closePath();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (Cosmic Deep Indigo, zero glow, zero border/brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#06071A");
  bgGrad.addColorStop(0.52, "#0E1132");
  bgGrad.addColorStop(1, "#161B4A");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let shieldStrength = 0.24;
  let trimProgress = 0;
  let nodeCharge = 0;
  let uvIntensity = 0;
  let deflectActive = 0;
  let tremorAmp = 0;
  let sweepAlpha = 0;
  let sweepNorm = 0;

  if (currentScene === 0) {
    // Scene 0: UV magenta beams strike thin ozone arc -> localized shield tremor & ripple
    shieldStrength = 0.24;
    trimProgress = 0;
    nodeCharge = 0;
    uvIntensity = bellEnvelope(sceneProgress, 0.05, 0.92);
    deflectActive = 0;
    tremorAmp = uvIntensity * 1.0;
    sweepAlpha = 0;
    sweepNorm = 0;
  } else if (currentScene === 1) {
    // Scene 1: O3 nodes illuminate & connect via trim-path -> dual cyan dome hardens -> UV beams bounce outward cleanly
    trimProgress = smoothRange(sceneProgress, 0.05, 0.52);
    nodeCharge = smoothRange(sceneProgress, 0.12, 0.62);
    shieldStrength = 0.24 + 0.76 * smoothRange(sceneProgress, 0.14, 0.60);
    uvIntensity = bellEnvelope(sceneProgress, 0.18, 0.94);
    deflectActive = smoothRange(sceneProgress, 0.16, 0.42);
    tremorAmp = 0;
    sweepAlpha = 0;
    sweepNorm = 0;
  } else {
    // Scene 2: Clean radial protective sweep glides across fortified dome, then calmly resets for cycle start
    uvIntensity = 0;
    deflectActive = 0;
    tremorAmp = 0;
    sweepNorm = clamp01((sceneProgress - 0.06) / 0.58);
    sweepAlpha = bellEnvelope(sceneProgress, 0.06, 0.64);
    trimProgress = 1.0 - smoothRange(sceneProgress, 0.48, 0.88);
    nodeCharge = 1.0 - smoothRange(sceneProgress, 0.52, 0.92);
    shieldStrength = 1.0 - 0.76 * smoothRange(sceneProgress, 0.54, 0.94);
  }

  // 3. Layout Coordinates (Strict concentric buffer separation: Earth <= 0.142, Shield 0.228..0.268, UV >= 0.282)
  const cx = width * 0.5;
  const earthCy = height * 0.64;
  const earthR = minSide * 0.142;
  const arcCenterY = earthCy;
  const tremorShift = tremorAmp * Math.sin(cycleNorm * Math.PI * 2 * 16) * minSide * 0.0028;
  const shieldInnerR = minSide * 0.226 + tremorShift * 0.7;
  const shieldMidR = minSide * 0.247 + tremorShift * 0.85;
  const shieldOuterR = minSide * 0.268 + tremorShift;
  const arcStartA = -Math.PI * 0.86;
  const arcEndA = -Math.PI * 0.14;
  const strokeW = Math.max(2, minSide * 0.0050);

  // 4. Lower-Center Flat-Vector Rotating Earth Emblem
  ctx.beginPath();
  ctx.arc(cx, earthCy, earthR + minSide * 0.004, 0, Math.PI * 2);
  ctx.fillStyle = "#080D24";
  ctx.fill();

  ctx.beginPath();
  ctx.arc(cx, earthCy, earthR, 0, Math.PI * 2);
  const oceanGrad = ctx.createLinearGradient(cx - earthR * 0.8, earthCy - earthR * 0.8, cx + earthR * 0.8, earthCy + earthR * 0.8);
  oceanGrad.addColorStop(0, "#60A5FA");
  oceanGrad.addColorStop(0.5, "#3B82F6");
  oceanGrad.addColorStop(1, "#1D4ED8");
  ctx.fillStyle = oceanGrad;
  ctx.fill();

  // Clipped Seamlessly Rotating Sculpted Emerald Continents, Latitude Grid & Polar Ice Caps
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, earthCy, earthR, 0, Math.PI * 2);
  ctx.clip();

  // Subtle curved horizontal latitude parallels
  for (let lat = -1; lat <= 1; lat++) {
    const ly = earthCy + lat * earthR * 0.42;
    ctx.beginPath();
    ctx.moveTo(cx - earthR, ly);
    ctx.lineTo(cx + earthR, ly);
    ctx.lineWidth = Math.max(1.2, minSide * 0.0022);
    ctx.strokeStyle = "rgba(191, 219, 254, 0.20)";
    ctx.stroke();
  }

  // Tile period matches exact 1 full rotation across 20s duration (seamless loop at t=0 and t=20)
  const tileW = earthR * 3.2;
  const scrollX = cycleNorm * tileW;
  const contDefs = [
    { x: 0.16, y: -0.14, scale: 1.05, variant: 0 },
    { x: 0.52, y: 0.06, scale: 1.00, variant: 1 },
    { x: 0.84, y: -0.20, scale: 0.85, variant: 2 }
  ];

  for (let rep = -1; rep <= 1; rep++) {
    const tileOriginX = cx - earthR + scrollX + rep * tileW;
    for (let c = 0; c < contDefs.length; c++) {
      const cd = contDefs[c];
      const lx = tileOriginX + cd.x * tileW;
      const ly = earthCy + cd.y * earthR;
      if (lx + earthR * 0.55 < cx - earthR || lx - earthR * 0.55 > cx + earthR) continue;

      traceSculptedContinent(lx, ly, earthR * cd.scale, cd.variant);
      const landGrad = ctx.createLinearGradient(lx, ly - earthR * 0.3, lx, ly + earthR * 0.3);
      landGrad.addColorStop(0, "#34D399");
      landGrad.addColorStop(1, "#059669");
      ctx.fillStyle = landGrad;
      ctx.fill();
      ctx.lineWidth = Math.max(1.2, minSide * 0.0024);
      ctx.strokeStyle = "rgba(6, 78, 59, 0.42)";
      ctx.stroke();
    }
  }

  // Subtle North & South Polar Ice Caps inside globe clip
  ctx.beginPath();
  ctx.ellipse(cx, earthCy - earthR * 0.94, earthR * 0.48, earthR * 0.16, 0, 0, Math.PI * 2);
  ctx.ellipse(cx, earthCy + earthR * 0.95, earthR * 0.44, earthR * 0.14, 0, 0, Math.PI * 2);
  ctx.fillStyle = "rgba(224, 242, 254, 0.72)";
  ctx.fill();

  // Smooth Curved Orbital Rim Shadow on Bottom-Right Hemisphere
  ctx.beginPath();
  ctx.arc(cx - earthR * 0.26, earthCy - earthR * 0.22, earthR * 1.06, 0, Math.PI * 2, false);
  ctx.arc(cx, earthCy, earthR * 1.25, 0, Math.PI * 2, true);
  ctx.fillStyle = "rgba(9, 13, 40, 0.24)";
  ctx.fill();

  // Crisp Top-Left Specular Crescent
  ctx.beginPath();
  ctx.arc(cx, earthCy, earthR * 0.84, -Math.PI * 0.80, -Math.PI * 0.48);
  ctx.lineWidth = minSide * 0.0085;
  ctx.strokeStyle = "rgba(219, 234, 254, 0.38)";
  ctx.stroke();

  ctx.restore(); // End globe clip

  // Outer Globe Border Stroke
  ctx.beginPath();
  ctx.arc(cx, earthCy, earthR, 0, Math.PI * 2);
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = "#93C5FD";
  ctx.stroke();

  // 5. Unified Curved Ozone Dome Shield Arch Housing (Clean semicircular end caps, zero protruding notches!)
  const archThick = shieldOuterR - shieldInnerR;
  const endCapR = archThick * 0.5;
  const startCapX = cx + Math.cos(arcStartA) * shieldMidR;
  const startCapY = arcCenterY + Math.sin(arcStartA) * shieldMidR;
  const endCapX = cx + Math.cos(arcEndA) * shieldMidR;
  const endCapY = arcCenterY + Math.sin(arcEndA) * shieldMidR;

  function traceDomeHousingPath() {
    ctx.beginPath();
    ctx.arc(cx, arcCenterY, shieldOuterR, arcStartA, arcEndA, false);
    ctx.arc(endCapX, endCapY, endCapR, arcEndA, arcEndA + Math.PI, false);
    ctx.arc(cx, arcCenterY, shieldInnerR, arcEndA, arcStartA, true);
    ctx.arc(startCapX, startCapY, endCapR, arcStartA + Math.PI, arcStartA + Math.PI * 2, false);
    ctx.closePath();
  }

  // Translucent cyan atmospheric belt body inside arch housing
  traceDomeHousingPath();
  ctx.fillStyle = "rgba(14, 116, 144, " + lerp(0.18, 0.34, shieldStrength).toFixed(3) + ")";
  ctx.fill();

  // Crisp Outer Shield Boundary & Rounded End Caps (Single continuous closed outline, zero frame gaps)
  traceDomeHousingPath();
  ctx.lineWidth = minSide * lerp(0.0045, 0.0072, shieldStrength);
  ctx.strokeStyle = lerpColor([56, 189, 248], [165, 243, 252], shieldStrength);
  ctx.stroke();

  // Highlight Inner Rim Track when fortified in Scene 1/2
  if (shieldStrength > 0.25) {
    ctx.beginPath();
    ctx.arc(cx, arcCenterY, shieldOuterR - minSide * 0.006, arcStartA + 0.04, arcEndA - 0.04);
    ctx.lineWidth = minSide * 0.0045;
    ctx.strokeStyle = "rgba(34, 211, 238, " + ((shieldStrength - 0.25) * 0.95).toFixed(3) + ")";
    ctx.stroke();
  }

  // Trim-path linking arc connecting O3 nodes smoothly along shieldMidR
  if (trimProgress > 0.01) {
    const nodeStartA = -Math.PI * 0.80;
    const nodeEndA = -Math.PI * 0.20;
    const curEndA = lerp(nodeStartA, nodeEndA, trimProgress);
    ctx.beginPath();
    ctx.arc(cx, arcCenterY, shieldMidR, nodeStartA, curEndA);
    ctx.lineWidth = Math.max(2, minSide * 0.0048);
    ctx.strokeStyle = "#22D3EE";
    ctx.stroke();
  }

  // 5 Tri-Circle Ozone (O3) Symbolic Molecular Nodes evenly spaced inside Dome Housing
  const nodeAngles = [-0.80 * Math.PI, -0.65 * Math.PI, -0.50 * Math.PI, -0.35 * Math.PI, -0.20 * Math.PI];
  for (let n = 0; n < nodeAngles.length; n++) {
    const na = nodeAngles[n];
    const nx = cx + Math.cos(na) * shieldMidR;
    const ny = arcCenterY + Math.sin(na) * shieldMidR;
    const seqCharge = clamp01((nodeCharge - n * 0.12) / 0.50);

    ctx.save();
    ctx.translate(nx, ny);
    ctx.rotate(na + Math.PI * 0.5);

    const atomR = minSide * lerp(0.0048, 0.0062, seqCharge);
    const spreadX = minSide * 0.0078;
    const apexY = -minSide * 0.0058;
    const baseY = minSide * 0.0042;

    ctx.beginPath();
    ctx.moveTo(-spreadX, baseY);
    ctx.lineTo(0, apexY);
    ctx.lineTo(spreadX, baseY);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0024);
    ctx.strokeStyle = lerpColor([71, 85, 105], [165, 243, 252], seqCharge);
    ctx.stroke();

    const pts = [[0, apexY], [-spreadX, baseY], [spreadX, baseY]];
    const atomFill = lerpColor([30, 58, 95], [34, 211, 238], seqCharge);
    for (let pt = 0; pt < 3; pt++) {
      ctx.beginPath();
      ctx.arc(pts[pt][0], pts[pt][1], atomR, 0, Math.PI * 2);
      ctx.fillStyle = atomFill;
      ctx.fill();
      ctx.lineWidth = Math.max(1.2, minSide * 0.0020);
      ctx.strokeStyle = "#080D24";
      ctx.stroke();
    }
    ctx.restore();
  }

  // Radial Protective Sweep Highlight clipped strictly inside Dome Housing in Scene 2
  if (sweepAlpha > 0.02) {
    ctx.save();
    traceDomeHousingPath();
    ctx.clip();
    const swSpan = 0.22 * Math.PI;
    const swMid = lerp(arcStartA + swSpan * 0.4, arcEndA - swSpan * 0.4, sweepNorm);
    ctx.beginPath();
    ctx.arc(cx, arcCenterY, shieldMidR, swMid - swSpan * 0.5, swMid + swSpan * 0.5);
    ctx.lineWidth = archThick * 1.1;
    ctx.strokeStyle = "rgba(224, 242, 254, " + (sweepAlpha * 0.52).toFixed(3) + ")";
    ctx.stroke();
    ctx.restore();
  }

  // 6. Disjoint UV Radiation Beams & True Outward Deflection Physics (Strictly cleared at hitR = shieldOuterR + 0.015 * minSide)
  if (uvIntensity > 0.02) {
    const hitClearR = shieldOuterR + minSide * 0.015;
    const rayLanes = [
      { hitA: -0.70 * Math.PI, inDirX: 0.22, inDirY: 0.975, phaseOff: 0.00 },
      { hitA: -0.50 * Math.PI, inDirX: -0.24, inDirY: 0.970, phaseOff: 0.34 },
      { hitA: -0.30 * Math.PI, inDirX: -0.22, inDirY: 0.975, phaseOff: 0.67 }
    ];

    const rayTravel = minSide * 0.195;
    const segLen = minSide * 0.090;

    for (let i = 0; i < rayLanes.length; i++) {
      const rl = rayLanes[i];
      const normX = Math.cos(rl.hitA);
      const normY = Math.sin(rl.hitA);
      const hitX = cx + normX * hitClearR;
      const hitY = arcCenterY + normY * hitClearR;

      const startX = hitX - rl.inDirX * rayTravel;
      const startY = hitY - rl.inDirY * rayTravel;

      const dotIN = rl.inDirX * normX + rl.inDirY * normY;
      const refDirX = rl.inDirX - 2 * dotIN * normX;
      const refDirY = rl.inDirY - 2 * dotIN * normY;
      const endX = hitX + refDirX * rayTravel;
      const endY = hitY + refDirY * rayTravel;

      const prog = (cycleNorm * 6 + rl.phaseOff) % 1;
      const headS = prog * (1 + segLen / rayTravel);
      const tailS = headS - (segLen / rayTravel);

      // Scene 0 stops squarely at hitClearR (zero contact overlap); Scene 1 bends & deflects outward cleanly
      const maxAllowS = lerp(0.50, 1.0, deflectActive);
      const cTail = clamp01(Math.min(tailS, maxAllowS));
      const cHead = clamp01(Math.min(headS, maxAllowS));

      if (cHead > cTail + 0.01) {
        function posOnPath(u) {
          if (u <= 0.5) {
            const k = u * 2;
            return [lerp(startX, hitX, k), lerp(startY, hitY, k)];
          } else {
            const k = (u - 0.5) * 2;
            return [lerp(hitX, endX, k), lerp(hitY, endY, k)];
          }
        }

        const pTail = posOnPath(cTail);
        const pHead = posOnPath(cHead);
        const rayAlpha = uvIntensity * Math.sin(Math.PI * prog);

        if (rayAlpha > 0.03) {
          ctx.beginPath();
          ctx.moveTo(pTail[0], pTail[1]);
          if (cTail < 0.5 && cHead > 0.5) {
            ctx.lineTo(hitX, hitY);
          }
          ctx.lineTo(pHead[0], pHead[1]);
          ctx.lineWidth = minSide * 0.0082;
          ctx.strokeStyle = "rgba(232, 121, 249, " + (rayAlpha * 0.92).toFixed(3) + ")";
          ctx.stroke();

          ctx.beginPath();
          ctx.moveTo(pTail[0], pTail[1]);
          if (cTail < 0.5 && cHead > 0.5) {
            ctx.lineTo(hitX, hitY);
          }
          ctx.lineTo(pHead[0], pHead[1]);
          ctx.lineWidth = minSide * 0.0034;
          ctx.strokeStyle = "rgba(250, 232, 255, " + (rayAlpha * 0.95).toFixed(3) + ")";
          ctx.stroke();
        }
      }

      // Crisp Split-Wing Shockwave Brackets strictly hugging outer dome gap (never cuts across UV rays)
      if (prog > 0.40 && prog < 0.86) {
        const hitAge = (prog - 0.40) / 0.46;
        const ripAlpha = Math.sin(Math.PI * hitAge) * uvIntensity * 0.90;
        const ripR = shieldOuterR + minSide * (0.006 + hitAge * 0.006);
        const wingGap = 0.028 * Math.PI + hitAge * 0.032 * Math.PI;
        const wingLen = 0.048 * Math.PI;
        const wingColor = deflectActive > 0.4
          ? "rgba(34, 211, 238, " + ripAlpha.toFixed(3) + ")"
          : "rgba(232, 121, 249, " + ripAlpha.toFixed(3) + ")";

        ctx.lineWidth = Math.max(1.5, minSide * 0.0034 * (1 - hitAge * 0.35));
        ctx.strokeStyle = wingColor;

        // Left flanking shockwave wing
        ctx.beginPath();
        ctx.arc(cx, arcCenterY, ripR, rl.hitA - wingGap - wingLen, rl.hitA - wingGap);
        ctx.stroke();

        // Right flanking shockwave wing
        ctx.beginPath();
        ctx.arc(cx, arcCenterY, ripR, rl.hitA + wingGap, rl.hitA + wingGap + wingLen);
        ctx.stroke();

        // Compact deflection core flare centered at hitX, hitY (never penetrates shieldOuterR)
        if (hitAge < 0.48) {
          const spK = 1 - hitAge / 0.48;
          const spR = minSide * 0.0085 * spK;
          ctx.beginPath();
          ctx.arc(hitX, hitY, spR, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(250, 232, 255, " + (uvIntensity * spK * 0.85).toFixed(3) + ")";
          ctx.fill();
        }
      }
    }
  }

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function bellEnvelope(p, start, end) {
    if (p <= start || p >= end) return 0;
    return Math.sin(Math.PI * ((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  function drawLeaf(x, y, angle, length, widthFactor, fillMain, fillShadow, rimColor, rimW) {
    if (length <= 0.5) return;
    const halfW = length * widthFactor;

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(angle);

    // Outer crisp rim path
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(length * 0.30, -halfW, length * 0.78, -halfW * 0.72, length, 0);
    ctx.bezierCurveTo(length * 0.78, halfW * 0.72, length * 0.30, halfW, 0, 0);
    ctx.closePath();
    ctx.fillStyle = fillMain;
    ctx.fill();

    // Lower half subtle flat shadow
    ctx.save();
    ctx.clip();
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(length, 0);
    ctx.lineTo(length, halfW);
    ctx.lineTo(0, halfW);
    ctx.closePath();
    ctx.fillStyle = fillShadow;
    ctx.fill();
    ctx.restore();

    // Leaf outline and center midrib
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.bezierCurveTo(length * 0.30, -halfW, length * 0.78, -halfW * 0.72, length, 0);
    ctx.bezierCurveTo(length * 0.78, halfW * 0.72, length * 0.30, halfW, 0, 0);
    ctx.closePath();
    ctx.lineWidth = rimW;
    ctx.strokeStyle = rimColor;
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(length * 0.08, 0);
    ctx.lineTo(length * 0.76, 0);
    ctx.lineWidth = Math.max(1.2, rimW * 0.75);
    ctx.strokeStyle = "rgba(236, 253, 245, 0.55)";
    ctx.stroke();

    ctx.restore();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (Deep Stormy Navy, zero glow, zero border/brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#09121B");
  bgGrad.addColorStop(0.52, "#0F1F30");
  bgGrad.addColorStop(1, "#152B40");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let rainAlpha = 0;
  let roofFlow = 0;
  let tankLevel = 0.18;
  let pourAlpha = 0;
  let sloshAmp = 0;
  let sensorActive = 0;
  let valveOpen = 0;
  let pipeFlowAlpha = 0;
  let plantBloom = 0.38;

  if (currentScene === 0) {
    // Scene 0: Rain hits sloped roof -> runs down gutter -> fills tank with sloshing waves
    rainAlpha = bellEnvelope(sceneProgress, 0.04, 0.92);
    roofFlow = smoothRange(sceneProgress, 0.08, 0.26) * (1 - smoothRange(sceneProgress, 0.80, 0.98));
    pourAlpha = smoothRange(sceneProgress, 0.12, 0.30) * (1 - smoothRange(sceneProgress, 0.84, 0.98));
    tankLevel = 0.18 + 0.68 * smoothRange(sceneProgress, 0.16, 0.95);
    sloshAmp = bellEnvelope(sceneProgress, 0.12, 0.98) * 1.0;
    sensorActive = 0;
    valveOpen = 0;
    pipeFlowAlpha = 0;
    plantBloom = 0.38;
  } else if (currentScene === 1) {
    // Scene 1: Buoyant float triggers Mint Sensor LED -> valve rotates open -> water irrigates plant into vibrant bloom
    rainAlpha = 0;
    roofFlow = 0;
    pourAlpha = 0;
    sensorActive = smoothRange(sceneProgress, 0.04, 0.28);
    valveOpen = smoothRange(sceneProgress, 0.22, 0.48);
    pipeFlowAlpha = smoothRange(sceneProgress, 0.30, 0.52);
    tankLevel = 0.86 - 0.30 * smoothRange(sceneProgress, 0.38, 0.96);
    sloshAmp = bellEnvelope(sceneProgress, 0.32, 0.98) * 0.45;
    plantBloom = 0.38 + 0.62 * smoothRange(sceneProgress, 0.42, 0.94);
  } else {
    // Scene 2: Tank drains evenly to base reserve, valve closes cleanly, leaves settle softly to idle rest
    rainAlpha = 0;
    roofFlow = 0;
    pourAlpha = 0;
    tankLevel = 0.56 - 0.38 * smoothRange(sceneProgress, 0.0, 0.72);
    sloshAmp = bellEnvelope(sceneProgress, 0.02, 0.78) * 0.35;
    pipeFlowAlpha = 1.0 - smoothRange(sceneProgress, 0.35, 0.70);
    valveOpen = 1.0 - smoothRange(sceneProgress, 0.52, 0.84);
    sensorActive = 1.0 - smoothRange(sceneProgress, 0.46, 0.82);
    plantBloom = 1.0 - 0.62 * smoothRange(sceneProgress, 0.38, 0.90);
  }

  // 3. Layout Coordinates (Strict disjoint horizontal zones aligned to clean architectural ground baseline)
  const cx = width * 0.5;
  const cy = height * 0.54;
  const groundY = cy + minSide * 0.175;
  const strokeW = Math.max(2, minSide * 0.0052);
  const darkInk = "#0B1320";

  // Left Zone: House dimensions (x: cx - 0.315 to cx - 0.065)
  const houseL = cx - minSide * 0.305;
  const houseR = cx - minSide * 0.065;
  const houseW = houseR - houseL;
  const roofLeftX = houseL - minSide * 0.022;
  const roofLeftY = cy - minSide * 0.135;
  const roofRightX = houseR + minSide * 0.024;
  const roofRightY = cy - minSide * 0.028;
  const roofThick = minSide * 0.026;

  function roofTopYAt(xPos) {
    const u = clamp01((xPos - roofLeftX) / (roofRightX - roofLeftX));
    return lerp(roofLeftY, roofRightY, u);
  }

  // Center-Right Zone: Cistern Tank (x: cx + 0.015 to cx + 0.135 -> 0.080*minSide gap from house wall)
  const tankL = cx + minSide * 0.015;
  const tankW = minSide * 0.118;
  const tankR = tankL + tankW;
  const tankCx = tankL + tankW * 0.5;
  const tankTop = cy - minSide * 0.032;
  const tankPlinthH = minSide * 0.018;
  const tankInnerBot = groundY - tankPlinthH;
  const tankInnerTop = tankTop + minSide * 0.016;
  const tankInnerH = tankInnerBot - tankInnerTop;

  // Far-Right Zone: Terracotta Planter Pot & Sprout (x: cx + 0.228 to cx + 0.336 -> 0.093*minSide gap from tank)
  const potCx = cx + minSide * 0.282;
  const potTopW = minSide * 0.110;
  const potBotW = minSide * 0.076;
  const potH = minSide * 0.086;
  const potTopY = groundY - potH;

  // 4. Architectural Ground Baseline Bar (Anchors House, Cistern, and Pot on one aligned level)
  roundedRectPath(houseL - minSide * 0.04, groundY, minSide * 0.72, minSide * 0.013, minSide * 0.0065);
  ctx.fillStyle = "#1E344B";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.003);
  ctx.strokeStyle = "#334E6B";
  ctx.stroke();

  // 5. Scene 0 Angled Raindrops (Strictly confined ABOVE roofTopYAt(x) so zero overlap with roof/house)
  if (rainAlpha > 0.02) {
    const rainXStart = [0.08, 0.22, 0.37, 0.52, 0.67, 0.82];
    const dropLen = minSide * 0.030;
    const dropDx = minSide * 0.007;
    const dropDy = minSide * 0.028;

    for (let i = 0; i < rainXStart.length; i++) {
      const rxBase = lerp(roofLeftX + minSide * 0.025, roofRightX - minSide * 0.025, rainXStart[i]);
      const prog = (cycleNorm * 10 + i * 0.37) % 1;
      const startY = cy - minSide * 0.355;
      const endY = roofTopYAt(rxBase) - minSide * 0.008;
      const dropY = lerp(startY, endY, prog);
      const dropX = rxBase - (1 - prog) * minSide * 0.028;
      const fade = Math.sin(Math.PI * prog) * rainAlpha;

      if (fade > 0.03) {
        ctx.beginPath();
        ctx.moveTo(dropX - dropDx, dropY - dropDy);
        ctx.lineTo(dropX, dropY);
        ctx.lineWidth = Math.max(2, minSide * 0.0050);
        ctx.strokeStyle = "rgba(56, 189, 248, " + fade.toFixed(3) + ")";
        ctx.stroke();

        // Crisp impact micro-splash strictly above roof surface near end of drop cycle
        if (prog > 0.78) {
          const sp = (prog - 0.78) / 0.22;
          const impactY = roofTopYAt(rxBase) - minSide * 0.006;
          const spAlpha = (1 - sp) * rainAlpha * 0.9;
          ctx.beginPath();
          ctx.arc(rxBase - sp * minSide * 0.012, impactY - Math.sin(sp * Math.PI) * minSide * 0.016, minSide * 0.0042, 0, Math.PI * 2);
          ctx.arc(rxBase + sp * minSide * 0.012, impactY - Math.sin(sp * Math.PI) * minSide * 0.013, minSide * 0.0042, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(186, 230, 253, " + spAlpha.toFixed(3) + ")";
          ctx.fill();
        }
      }
    }
  }

  // 6. House Wall Structure, Architectural Window & Sloped Terracotta Roof
  // Clean house polygon beneath roof overhang
  const bodyLeftTopY = roofTopYAt(houseL) + roofThick * 0.65;
  const bodyRightTopY = roofTopYAt(houseR) + roofThick * 0.65;

  ctx.beginPath();
  ctx.moveTo(houseL, groundY);
  ctx.lineTo(houseL, bodyLeftTopY);
  ctx.lineTo(houseR, bodyRightTopY);
  ctx.lineTo(houseR, groundY);
  ctx.closePath();

  const wallGrad = ctx.createLinearGradient(houseL, bodyLeftTopY, houseR, groundY);
  wallGrad.addColorStop(0, "#E2E8F0");
  wallGrad.addColorStop(1, "#CBD5E1");
  ctx.fillStyle = wallGrad;
  ctx.fill();

  // Subtle architectural panel shade on right third of house wall (aligned inside wall)
  ctx.save();
  ctx.clip();
  ctx.fillStyle = "rgba(15, 23, 42, 0.08)";
  ctx.fillRect(houseR - houseW * 0.28, bodyLeftTopY, houseW * 0.28, groundY - bodyLeftTopY);
  ctx.restore();

  ctx.beginPath();
  ctx.moveTo(houseL, groundY);
  ctx.lineTo(houseL, bodyLeftTopY);
  ctx.lineTo(houseR, bodyRightTopY);
  ctx.lineTo(houseR, groundY);
  ctx.closePath();
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Clean Modern Door (right side of facade) & Window (left side, glows warmly with mint eco power)
  const doorW = minSide * 0.048;
  const doorH = minSide * 0.095;
  const doorX = houseR - doorW - minSide * 0.026;
  const doorY = groundY - doorH;
  roundedRectPath(doorX, doorY, doorW, doorH, minSide * 0.008);
  ctx.fillStyle = "#334155";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.78;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Door handle dot
  ctx.beginPath();
  ctx.arc(doorX + doorW * 0.24, doorY + doorH * 0.54, minSide * 0.0035, 0, Math.PI * 2);
  ctx.fillStyle = "#94A3B8";
  ctx.fill();

  // Architectural Double Window Pane
  const winW = minSide * 0.072;
  const winH = minSide * 0.062;
  const winX = houseL + minSide * 0.028;
  const winY = groundY - doorH - minSide * 0.012;
  roundedRectPath(winX, winY, winW, winH, minSide * 0.009);
  ctx.fillStyle = lerpColor([30, 41, 59], [45, 212, 191], sensorActive * 0.65);
  ctx.fill();
  ctx.lineWidth = strokeW * 0.78;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Window clean mullion divider + specular gleam
  ctx.beginPath();
  ctx.moveTo(winX + winW * 0.5, winY);
  ctx.lineTo(winX + winW * 0.5, winY + winH);
  ctx.lineWidth = Math.max(1.5, strokeW * 0.6);
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  // Sloped Terracotta Roof Slab (Plumb vertical bevel ends for flush eave & gutter fit)
  const beamBotLeftY = roofLeftY + roofThick;
  const beamBotRightY = roofRightY + roofThick;
  ctx.beginPath();
  ctx.moveTo(roofLeftX, roofLeftY);
  ctx.lineTo(roofRightX, roofRightY);
  ctx.lineTo(roofRightX, beamBotRightY);
  ctx.lineTo(roofLeftX, beamBotLeftY);
  ctx.closePath();

  const rGrad = ctx.createLinearGradient(roofLeftX, roofLeftY, roofRightX, beamBotRightY);
  rGrad.addColorStop(0, "#FB923C");
  rGrad.addColorStop(0.55, "#F97316");
  rGrad.addColorStop(1, "#EA580C");
  ctx.fillStyle = rGrad;
  ctx.fill();
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Crisp terracotta roof top highlight edge
  ctx.beginPath();
  ctx.moveTo(roofLeftX + minSide * 0.012, roofLeftY + minSide * 0.005);
  ctx.lineTo(roofRightX - minSide * 0.012, roofRightY + minSide * 0.001);
  ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
  ctx.strokeStyle = "#FED7AA";
  ctx.stroke();

  // Active Water Flow Film sliding down upper roof edge into right gutter
  if (roofFlow > 0.02) {
    const flowPhase = (cycleNorm * 8) % 1;
    ctx.beginPath();
    ctx.moveTo(roofLeftX + minSide * 0.018, roofLeftY - minSide * 0.003);
    ctx.lineTo(roofRightX - minSide * 0.004, roofRightY - minSide * 0.007);
    ctx.lineWidth = Math.max(2.5, minSide * 0.0075);
    ctx.strokeStyle = "rgba(56, 189, 248, " + (roofFlow * 0.92).toFixed(3) + ")";
    ctx.stroke();

    // Animated white-aqua crest dashes sliding down slope
    ctx.save();
    ctx.setLineDash([minSide * 0.016, minSide * 0.024]);
    ctx.lineDashOffset = -flowPhase * minSide * 0.040;
    ctx.beginPath();
    ctx.moveTo(roofLeftX + minSide * 0.024, roofLeftY - minSide * 0.004);
    ctx.lineTo(roofRightX - minSide * 0.006, roofRightY - minSide * 0.008);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0036);
    ctx.strokeStyle = "rgba(224, 242, 254, " + (roofFlow * 0.95).toFixed(3) + ")";
    ctx.stroke();
    ctx.restore();
  }

  // 7. Overhead Gutter Pipe Connecting Roof Eave Cleanly to Cistern Top Intake
  const gutterX = roofRightX + minSide * 0.012;
  const gutterY = roofRightY + roofThick * 0.55;
  const pipeBendX = tankCx;
  const pipeEndY = tankTop - minSide * 0.002;

  ctx.beginPath();
  ctx.moveTo(gutterX, gutterY);
  ctx.lineTo(pipeBendX - minSide * 0.016, gutterY);
  ctx.quadraticCurveTo(pipeBendX, gutterY, pipeBendX, gutterY + minSide * 0.016);
  ctx.lineTo(pipeBendX, pipeEndY);
  ctx.lineWidth = minSide * 0.016;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(gutterX, gutterY);
  ctx.lineTo(pipeBendX - minSide * 0.016, gutterY);
  ctx.quadraticCurveTo(pipeBendX, gutterY, pipeBendX, gutterY + minSide * 0.016);
  ctx.lineTo(pipeBendX, pipeEndY);
  ctx.lineWidth = minSide * 0.010;
  ctx.strokeStyle = "#94A3B8";
  ctx.stroke();

  // Gutter catch cup docked flush outside right roof eave (zero overlap with terracotta edge)
  roundedRectPath(roofRightX + minSide * 0.002, roofRightY - minSide * 0.002, minSide * 0.022, minSide * 0.026, minSide * 0.005);
  ctx.fillStyle = "#CBD5E1";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.8;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // 8. Lower Horizontal Irrigation Pipe + Rotating Mechanical Valve (Tank -> Planter Soil)
  const valvePipeY = groundY - minSide * 0.040;
  const valveX = (tankR + (potCx - potTopW * 0.36)) * 0.5;
  const pipeInX = tankR - minSide * 0.002;
  const pipeOutX = potCx - potTopW * 0.35;

  // Pipe dark border + metallic body
  ctx.beginPath();
  ctx.moveTo(pipeInX, valvePipeY);
  ctx.lineTo(pipeOutX, valvePipeY);
  ctx.lineWidth = minSide * 0.017;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(pipeInX, valvePipeY);
  ctx.lineTo(pipeOutX, valvePipeY);
  ctx.lineWidth = minSide * 0.011;
  ctx.strokeStyle = "#64748B";
  ctx.stroke();

  // Animated aqua stream inside pipe when valve is open
  if (pipeFlowAlpha > 0.02 && valveOpen > 0.15) {
    const flowDash = (cycleNorm * 12) % 1;
    ctx.save();
    ctx.setLineDash([minSide * 0.014, minSide * 0.012]);
    ctx.lineDashOffset = -flowDash * minSide * 0.026;
    ctx.beginPath();
    ctx.moveTo(pipeInX + minSide * 0.005, valvePipeY);
    ctx.lineTo(pipeOutX - minSide * 0.004, valvePipeY);
    ctx.lineWidth = minSide * 0.0058;
    ctx.strokeStyle = "rgba(56, 189, 248, " + (pipeFlowAlpha * 0.95).toFixed(3) + ")";
    ctx.stroke();
    ctx.restore();
  }

  // Mechanical Rotary Valve Wheel centered cleanly in gap above pipe
  const wheelY = valvePipeY - minSide * 0.026;
  const wheelR = minSide * 0.015;
  // Valve stem connecting pipe to wheel
  ctx.beginPath();
  ctx.moveTo(valveX, valvePipeY - minSide * 0.006);
  ctx.lineTo(valveX, wheelY);
  ctx.lineWidth = minSide * 0.007;
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  // Valve housing collar on pipe
  roundedRectPath(valveX - minSide * 0.012, valvePipeY - minSide * 0.011, minSide * 0.024, minSide * 0.022, minSide * 0.005);
  ctx.fillStyle = "#334155";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.7;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Rotating Valve Wheel
  ctx.save();
  ctx.translate(valveX, wheelY);
  ctx.rotate(valveOpen * Math.PI * 0.5);
  ctx.beginPath();
  ctx.arc(0, 0, wheelR, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.0048;
  ctx.strokeStyle = lerpColor([249, 115, 22], [45, 212, 191], valveOpen);
  ctx.stroke();

  for (let s = 0; s < 4; s++) {
    ctx.rotate(Math.PI * 0.5);
    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(wheelR * 0.85, 0);
    ctx.lineWidth = minSide * 0.0036;
    ctx.strokeStyle = "#E2E8F0";
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.arc(0, 0, minSide * 0.0048, 0, Math.PI * 2);
  ctx.fillStyle = "#F8FAFC";
  ctx.fill();
  ctx.restore();

  // 9. Center-Right Glass Cistern Tank, Sloshing Water, Buoyant Sensor & Top Mint Indicator
  // Tank pedestal plinth
  roundedRectPath(tankL - minSide * 0.008, tankInnerBot, tankW + minSide * 0.016, tankPlinthH, minSide * 0.006);
  ctx.fillStyle = "#334155";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Glass tank dark translucent interior
  roundedRectPath(tankL, tankTop, tankW, tankInnerBot - tankTop, minSide * 0.018);
  ctx.fillStyle = "rgba(15, 28, 44, 0.88)";
  ctx.fill();

  // Clip interior contents cleanly inside glass wall
  ctx.save();
  roundedRectPath(tankL + strokeW * 0.4, tankTop + strokeW * 0.4, tankW - strokeW * 0.8, tankInnerBot - tankTop - strokeW * 0.8, minSide * 0.015);
  ctx.clip();

  // Clamped liquid surface height
  const waterY = tankInnerBot - tankInnerH * tankLevel;
  const waveAmp = minSide * 0.0065 * sloshAmp;
  const wavePhase = cycleNorm * Math.PI * 2 * 10;

  // Vertical incoming pour stream inside tank from top intake nozzle down to waterY
  if (pourAlpha > 0.02) {
    ctx.beginPath();
    ctx.moveTo(tankCx, tankTop + minSide * 0.016);
    ctx.lineTo(tankCx, waterY + minSide * 0.008);
    ctx.lineWidth = minSide * 0.011;
    ctx.strokeStyle = "rgba(56, 189, 248, " + (pourAlpha * 0.88).toFixed(3) + ")";
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(tankCx - minSide * 0.002, tankTop + minSide * 0.016);
    ctx.lineTo(tankCx - minSide * 0.002, waterY + minSide * 0.008);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
    ctx.strokeStyle = "rgba(224, 242, 254, " + (pourAlpha * 0.92).toFixed(3) + ")";
    ctx.stroke();
  }

  // Engineered intake nozzle collar inside tank roof
  roundedRectPath(tankCx - minSide * 0.012, tankTop, minSide * 0.024, minSide * 0.018, minSide * 0.004);
  ctx.fillStyle = "#64748B";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, strokeW * 0.65);
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Aqua Water Body with smooth dual-sine sloshing surface
  ctx.beginPath();
  ctx.moveTo(tankL - 2, tankInnerBot + 4);
  const wSteps = 22;
  for (let i = 0; i <= wSteps; i++) {
    const u = i / wSteps;
    const wx = lerp(tankL - 2, tankR + 2, u);
    const wy = waterY +
      Math.sin(u * Math.PI * 2 + wavePhase) * waveAmp +
      Math.cos(u * Math.PI * 3 - wavePhase * 0.7) * (waveAmp * 0.35);
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(tankR + 2, tankInnerBot + 4);
  ctx.closePath();

  const wGrad = ctx.createLinearGradient(0, waterY, 0, tankInnerBot);
  wGrad.addColorStop(0, "#38BDF8");
  wGrad.addColorStop(0.5, "#0EA5E9");
  wGrad.addColorStop(1, "#0369A1");
  ctx.fillStyle = wGrad;
  ctx.fill();

  // Crisp water surface meniscus highlight line
  ctx.beginPath();
  for (let i = 0; i <= wSteps; i++) {
    const u = i / wSteps;
    const wx = lerp(tankL - 2, tankR + 2, u);
    const wy = waterY +
      Math.sin(u * Math.PI * 2 + wavePhase) * waveAmp +
      Math.cos(u * Math.PI * 3 - wavePhase * 0.7) * (waveAmp * 0.35);
    if (i === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.lineWidth = Math.max(2, minSide * 0.0042);
  ctx.strokeStyle = "#BAE6FD";
  ctx.stroke();

  // Rising micro-bubbles inside water while filling
  if (pourAlpha > 0.05) {
    for (let b = 0; b < 4; b++) {
      const bProg = (cycleNorm * 8 + b * 0.25) % 1;
      const by = lerp(tankInnerBot - minSide * 0.015, waterY + minSide * 0.012, bProg);
      const bx = tankCx + Math.sin(bProg * Math.PI * 4 + b * 1.7) * (tankW * 0.26);
      const bAlpha = Math.sin(Math.PI * bProg) * pourAlpha * 0.85;
      if (by > waterY + minSide * 0.006 && bAlpha > 0.04) {
        ctx.beginPath();
        ctx.arc(bx, by, minSide * (0.0032 + (b % 2) * 0.0014), 0, Math.PI * 2);
        ctx.fillStyle = "rgba(224, 242, 254, " + bAlpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // Buoyant Vertical Sensor Rod & Floating Capsule (Strictly tracks surface inside tank bounds)
  const rodX = tankR - minSide * 0.028;
  const floatWave = Math.sin(((rodX - tankL) / tankW) * Math.PI * 2 + wavePhase) * waveAmp;
  const floatY = Math.max(tankInnerTop + minSide * 0.018, Math.min(tankInnerBot - minSide * 0.014, waterY + floatWave));

  // Slender guide rod from top lid down to buoyant float
  ctx.beginPath();
  ctx.moveTo(rodX, tankTop);
  ctx.lineTo(rodX, floatY);
  ctx.lineWidth = Math.max(1.5, minSide * 0.0030);
  ctx.strokeStyle = "#94A3B8";
  ctx.stroke();

  // Buoyant Mint Sensor Float Capsule
  const fW = minSide * 0.022;
  const fH = minSide * 0.014;
  roundedRectPath(rodX - fW * 0.5, floatY - fH * 0.5, fW, fH, fH * 0.5);
  ctx.fillStyle = lerpColor([148, 163, 184], [45, 212, 191], sensorActive);
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.0028);
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Clean glass diagonal specular streak inside tank clip
  ctx.beginPath();
  ctx.moveTo(tankL + minSide * 0.014, tankTop + minSide * 0.018);
  ctx.lineTo(tankL + minSide * 0.014, tankInnerBot - minSide * 0.018);
  ctx.lineWidth = minSide * 0.007;
  ctx.strokeStyle = "rgba(255, 255, 255, 0.14)";
  ctx.stroke();

  ctx.restore(); // End tank interior clip

  // Water Gauge Graduation Tick Marks on Left Glass Edge
  for (let tk = 1; tk <= 3; tk++) {
    const ty = tankInnerBot - tankInnerH * (tk * 0.25);
    ctx.beginPath();
    ctx.moveTo(tankL + minSide * 0.004, ty);
    ctx.lineTo(tankL + minSide * 0.020, ty);
    ctx.lineWidth = Math.max(1.5, minSide * 0.0026);
    ctx.strokeStyle = "rgba(203, 213, 225, 0.65)";
    ctx.stroke();
  }

  // Outer Glass Tank Outline & Top Collar Cap
  roundedRectPath(tankL, tankTop, tankW, tankInnerBot - tankTop, minSide * 0.018);
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  roundedRectPath(tankL - minSide * 0.006, tankTop - minSide * 0.008, tankW + minSide * 0.012, minSide * 0.018, minSide * 0.006);
  ctx.fillStyle = "#475569";
  ctx.fill();
  ctx.lineWidth = strokeW * 0.85;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Mint Sensor Beacon Dome perched cleanly on right side of tank cap (aligned directly above sensor rod!)
  const ledY = tankTop - minSide * 0.016;
  ctx.beginPath();
  ctx.arc(rodX, ledY, minSide * 0.0105, Math.PI, 0);
  ctx.closePath();
  ctx.fillStyle = lerpColor([71, 85, 105], [45, 212, 191], sensorActive);
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, strokeW * 0.7);
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Crisp Mint Signal Arcs above Sensor LED when active (Strictly confined above tank cap)
  if (sensorActive > 0.05) {
    const sigPhase = (cycleNorm * 6) % 1;
    for (let s = 0; s < 2; s++) {
      const sp = (sigPhase + s * 0.5) % 1;
      const sr = minSide * (0.018 + sp * 0.024);
      const sAlpha = Math.sin(Math.PI * sp) * sensorActive * 0.90;
      if (sAlpha > 0.04) {
        ctx.beginPath();
        ctx.arc(rodX, ledY - minSide * 0.004, sr, -Math.PI * 0.78, -Math.PI * 0.22);
        ctx.lineWidth = Math.max(1.5, minSide * 0.0032);
        ctx.strokeStyle = "rgba(45, 212, 191, " + sAlpha.toFixed(3) + ")";
        ctx.stroke();
      }
    }
  }

  // 10. Right Zone: Terracotta Planter Pot & Responsive Botanical Leaves
  // Organic Soil Mound inside Pot Rim
  ctx.beginPath();
  ctx.ellipse(potCx, potTopY + minSide * 0.004, potTopW * 0.42, minSide * 0.013, 0, Math.PI, 0);
  ctx.fillStyle = "#451A03";
  ctx.fill();

  // Central Plant Stem & 3 Synchronized Botanical Leaves (Hydrated bloom opens upward & sways naturally)
  const stemBaseY = potTopY - minSide * 0.002;
  const stemH = minSide * lerp(0.068, 0.118, plantBloom);
  const gentleSway = Math.sin(cycleNorm * Math.PI * 2 * 4) * minSide * 0.008 * plantBloom;
  const stemTopX = potCx + gentleSway;
  const stemTopY = stemBaseY - stemH;

  ctx.beginPath();
  ctx.moveTo(potCx, stemBaseY);
  ctx.quadraticCurveTo(potCx + gentleSway * 0.3, stemBaseY - stemH * 0.55, stemTopX, stemTopY);
  ctx.lineWidth = minSide * 0.0075;
  ctx.strokeStyle = "#10B981";
  ctx.stroke();

  const leafLenSide = minSide * lerp(0.036, 0.068, plantBloom);
  const leafLenTop = minSide * lerp(0.032, 0.062, plantBloom);
  const sideLift = lerp(0.28, 0.72, plantBloom);

  // Left & right twin lower-mid leaves (strictly inside pot/right corridor, never touches cistern!)
  const midNodeX = lerp(potCx, stemTopX, 0.52);
  const midNodeY = lerp(stemBaseY, stemTopY, 0.52);
  drawLeaf(midNodeX, midNodeY, -Math.PI + sideLift + gentleSway * 0.04, leafLenSide, 0.42, "#34D399", "#059669", darkInk, strokeW * 0.72);
  drawLeaf(midNodeX, midNodeY, -sideLift + gentleSway * 0.04, leafLenSide, 0.42, "#34D399", "#059669", darkInk, strokeW * 0.72);

  // Crown apex leaf opening upward cleanly
  drawLeaf(stemTopX, stemTopY, -Math.PI * 0.5 + gentleSway * 0.06, leafLenTop, 0.44, "#2DD4BF", "#0D9488", darkInk, strokeW * 0.72);

  // Planter Pot Trapezoid Body (Drawn after stem base so soil rim neatly covers stem bottom)
  ctx.beginPath();
  ctx.moveTo(potCx - potTopW * 0.46, potTopY + minSide * 0.015);
  ctx.lineTo(potCx + potTopW * 0.46, potTopY + minSide * 0.015);
  ctx.lineTo(potCx + potBotW * 0.5, groundY);
  ctx.lineTo(potCx - potBotW * 0.5, groundY);
  ctx.closePath();

  const potGrad = ctx.createLinearGradient(potCx - potTopW * 0.5, potTopY, potCx + potTopW * 0.5, groundY);
  potGrad.addColorStop(0, "#EA580C");
  potGrad.addColorStop(1, "#C2410C");
  ctx.fillStyle = potGrad;
  ctx.fill();
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Planter Pot Upper Collar Rim
  roundedRectPath(potCx - potTopW * 0.52, potTopY, potTopW * 1.04, minSide * 0.020, minSide * 0.006);
  ctx.fillStyle = "#FB923C";
  ctx.fill();
  ctx.lineWidth = strokeW;
  ctx.strokeStyle = darkInk;
  ctx.stroke();

  // Subtle horizontal clean pot rim highlight
  ctx.beginPath();
  ctx.moveTo(potCx - potTopW * 0.42, potTopY + minSide * 0.006);
  ctx.lineTo(potCx + potTopW * 0.12, potTopY + minSide * 0.006);
  ctx.lineWidth = Math.max(1.5, minSide * 0.003);
  ctx.strokeStyle = "#FED7AA";
  ctx.stroke();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function lerp3Color(c0, c1, c2, k) {
    const tK = clamp01(k);
    if (tK <= 0.5) return lerpColor(c0, c1, tK * 2);
    return lerpColor(c1, c2, (tK - 0.5) * 2);
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  // Trace one lung-leaf lobe symmetrically using side = -1 (left) or +1 (right)
  // Coordinates are relative to (cx, lungCy) and scaled by breathScale cleanly
  function traceLungLobe(side, scale) {
    const innerGap = minSide * 0.026 * scale;
    const outerReach = minSide * 0.184 * scale;
    const topY = -minSide * 0.132 * scale;
    const botY = minSide * 0.145 * scale;
    const midY = minSide * 0.012 * scale;

    ctx.beginPath();
    // Start at top-inner apex beside trachea branch
    ctx.moveTo(side * (innerGap + minSide * 0.022 * scale), topY + minSide * 0.024 * scale);
    // Curve smoothly up to rounded apex and down outer convex wing
    ctx.bezierCurveTo(
      side * (innerGap + minSide * 0.075 * scale),
      topY - minSide * 0.015 * scale,
      side * (outerReach * 0.92),
      topY + minSide * 0.028 * scale,
      side * outerReach,
      midY
    );
    // Curve down outer lower lobe to smooth rounded bottom base
    ctx.bezierCurveTo(
      side * (outerReach * 1.04),
      botY - minSide * 0.015 * scale,
      side * (innerGap + minSide * 0.070 * scale),
      botY + minSide * 0.016 * scale,
      side * (innerGap + minSide * 0.014 * scale),
      botY - minSide * 0.012 * scale
    );
    // Smooth concave inner medial edge facing central spine (never touches trachea)
    ctx.bezierCurveTo(
      side * (innerGap + minSide * 0.002 * scale),
      midY + minSide * 0.055 * scale,
      side * (innerGap + minSide * 0.002 * scale),
      midY - minSide * 0.045 * scale,
      side * (innerGap + minSide * 0.022 * scale),
      topY + minSide * 0.024 * scale
    );
    ctx.closePath();
  }

  function drawTrimQuad(x0, y0, cx0, cy0, x1, y1, prog) {
    const p = clamp01(prog);
    if (p <= 0.01) return;
    const steps = 16;
    ctx.beginPath();
    for (let i = 0; i <= steps; i++) {
      const s = (i / steps) * p;
      const omt = 1 - s;
      const px = omt * omt * x0 + 2 * omt * s * cx0 + s * s * x1;
      const py = omt * omt * y0 + 2 * omt * s * cy0 + s * s * y1;
      if (i === 0) ctx.moveTo(px, py);
      else ctx.lineTo(px, py);
    }
    ctx.stroke();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#0A111A");
  bgGrad.addColorStop(0.52, "#121B28");
  bgGrad.addColorStop(1, "#1A2838");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography State
  let breathScale = 1.0;
  let intakeAlpha = 0;
  let purifyScore = 0.08;
  let veinTrim = 0;
  let aqiLevel = 0.24;
  let oxygenOut = 0;

  if (currentScene === 0) {
    // Scene 0: Smooth inhalation expands lung-leaves; haze particles enter top intake
    breathScale = 1.0 + 0.055 * easeInOutSine(sceneProgress);
    intakeAlpha = Math.sin(Math.PI * clamp01((sceneProgress - 0.06) / 0.88));
    purifyScore = 0.08;
    veinTrim = 0;
    aqiLevel = 0.24;
    oxygenOut = 0;
  } else if (currentScene === 1) {
    // Scene 1: Purification wave traces bronchial veins, lobes shift Coral -> Lavender -> Mint, AQI climbs
    breathScale = 1.055 - 0.020 * smoothRange(sceneProgress, 0.55, 1.0);
    intakeAlpha = 0;
    purifyScore = 0.08 + 0.92 * smoothRange(sceneProgress, 0.14, 0.92);
    veinTrim = smoothRange(sceneProgress, 0.08, 0.82);
    aqiLevel = 0.24 + 0.76 * smoothRange(sceneProgress, 0.18, 0.94);
    oxygenOut = smoothRange(sceneProgress, 0.68, 1.0);
  } else {
    // Scene 2: Clean oxygen exhalation orbs drift in outer flank lanes; smooth reset to start
    breathScale = 1.035 - 0.035 * smoothRange(sceneProgress, 0.0, 0.75);
    intakeAlpha = 0;
    purifyScore = 1.0 - 0.92 * smoothRange(sceneProgress, 0.52, 0.96);
    veinTrim = 1.0 - smoothRange(sceneProgress, 0.45, 0.88);
    aqiLevel = 1.0 - 0.76 * smoothRange(sceneProgress, 0.52, 0.95);
    oxygenOut = 1.0 - smoothRange(sceneProgress, 0.40, 0.78);
  }

  // 3. Layout Coordinates (Strict non-overlapping zones)
  const cx = width * 0.5;
  const cy = height * 0.52;
  const lungCy = cy + minSide * 0.022;

  // Vibrant 3-stop thermal-air color transition (Rose Coral -> Warm Lavender -> Fresh Mint, zero muddy grey)
  const lobeFillTop = lerp3Color([251, 113, 133], [192, 132, 252], [52, 211, 153], purifyScore);
  const lobeFillBot = lerp3Color([225, 29, 72], [147, 51, 234], [16, 185, 129], purifyScore);
  const lobeRimColor = lerp3Color([254, 205, 211], [233, 213, 255], [209, 250, 229], purifyScore);
  const aqiColor = lerp3Color([251, 113, 133], [192, 132, 252], [52, 211, 153], purifyScore);

  // 4. Flanking Outer Air Quality Index (AQI) Gauge Arcs (Strictly on left & right flanks, r = 0.278 * minSide)
  const aqiR = minSide * 0.278;
  const aqiSpan = 0.52; // ~60 degrees vertical sweep centered horizontally
  for (let side = -1; side <= 1; side += 2) {
    const midA = side === 1 ? 0 : Math.PI;
    const a0 = midA - aqiSpan;
    const a1 = midA + aqiSpan;

    ctx.beginPath();
    ctx.arc(cx, lungCy, aqiR, a0, a1);
    ctx.lineWidth = minSide * 0.011;
    ctx.strokeStyle = "#172538";
    ctx.stroke();

    const fillSpan = aqiSpan * 2 * aqiLevel;
    const actStart = side === 1 ? a1 - fillSpan : a0;
    const actEnd = side === 1 ? a1 : a0 + fillSpan;
    ctx.beginPath();
    ctx.arc(cx, lungCy, aqiR, actStart, actEnd);
    ctx.lineWidth = minSide * 0.011;
    ctx.strokeStyle = aqiColor;
    ctx.stroke();
  }

  // 5. Top Intake Airway Particles (Scene 0 ONLY, cleanly above trachea intake collar)
  const tracheaTop = cy - minSide * 0.200;
  if (intakeAlpha > 0.02) {
    const skyTop = cy - minSide * 0.335;
    const skyBot = tracheaTop - minSide * 0.022;
    for (let k = 0; k < 3; k++) {
      const prog = (cycleNorm * 5 + k / 3) % 1;
      const py = lerp(skyTop, skyBot, prog);
      const px = cx + Math.sin(prog * Math.PI * 2 + k * 2) * minSide * 0.010;
      const alpha = Math.sin(Math.PI * prog) * intakeAlpha * 0.85;
      if (alpha > 0.04) {
        ctx.beginPath();
        ctx.arc(px, py, minSide * 0.0075, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(192, 132, 252, " + alpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // 6. Exhaled Pure Oxygen Orbs in Outer Clear Lanes (x = cx ± 0.232 * minSide, strictly between lobes and AQI arcs!)
  if (oxygenOut > 0.01) {
    for (let side = -1; side <= 1; side += 2) {
      for (let k = 0; k < 2; k++) {
        const prog = (cycleNorm * 4 + k * 0.5 + (side === 1 ? 0 : 0.25)) % 1;
        const alpha = Math.sin(Math.PI * prog) * oxygenOut * 0.90;
        if (alpha > 0.04) {
          const ox = cx + side * minSide * (0.224 + 0.018 * prog);
          const oy = lungCy + minSide * 0.055 - prog * minSide * 0.125;
          ctx.beginPath();
          ctx.arc(ox, oy, minSide * 0.0072, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(52, 211, 153, " + alpha.toFixed(3) + ")";
          ctx.fill();
        }
      }
    }
  }

  // 7. Central Trachea Stem & Bifurcating Bronchi (Behind inner lobe edges)
  const bifY = cy - minSide * 0.045;
  ctx.beginPath();
  ctx.moveTo(cx, tracheaTop);
  ctx.lineTo(cx, bifY);
  ctx.lineWidth = minSide * 0.018;
  ctx.strokeStyle = "#334155";
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(cx, tracheaTop);
  ctx.lineTo(cx, bifY);
  ctx.lineWidth = minSide * 0.009;
  ctx.strokeStyle = "#F1F5F9";
  ctx.stroke();

  // Horizontal Trachea Intake Ring Collar
  const colW = minSide * 0.046;
  const colH = minSide * 0.016;
  roundedRectPath(cx - colW * 0.5, tracheaTop - colH * 0.5, colW, colH, colH * 0.5);
  ctx.fillStyle = "#1E293B";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
  ctx.strokeStyle = "#F1F5F9";
  ctx.stroke();

  // Left & Right Bronchial Branch Connectors
  for (let side = -1; side <= 1; side += 2) {
    const entryX = cx + side * minSide * 0.062 * breathScale;
    const entryY = lungCy - minSide * 0.012 * breathScale;

    ctx.beginPath();
    ctx.moveTo(cx, bifY);
    ctx.quadraticCurveTo(cx + side * minSide * 0.020, bifY + minSide * 0.025, entryX, entryY);
    ctx.lineWidth = minSide * 0.014;
    ctx.strokeStyle = "#334155";
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(cx, bifY);
    ctx.quadraticCurveTo(cx + side * minSide * 0.020, bifY + minSide * 0.025, entryX, entryY);
    ctx.lineWidth = minSide * 0.007;
    ctx.strokeStyle = "#F1F5F9";
    ctx.stroke();
  }

  // 8. Left & Right Symmetrical Botanical Lung-Leaf Lobes
  ctx.save();
  ctx.translate(cx, lungCy);

  for (let side = -1; side <= 1; side += 2) {
    traceLungLobe(side, breathScale);
    const lGrad = ctx.createLinearGradient(0, -minSide * 0.14, 0, minSide * 0.15);
    lGrad.addColorStop(0, lobeFillTop);
    lGrad.addColorStop(1, lobeFillBot);
    ctx.fillStyle = lGrad;
    ctx.fill();

    // Clipped flat-vector lateral shading & branching botanical veins
    ctx.save();
    traceLungLobe(side, breathScale);
    ctx.clip();

    // Smooth organic curved outer rim shadow inside clip
    traceLungLobe(side, breathScale * 0.96);
    ctx.lineWidth = minSide * 0.022;
    ctx.strokeStyle = "rgba(10, 17, 26, 0.14)";
    ctx.stroke();

    // Base dark bronchial vein guide lines
    const vx0 = side * minSide * 0.044 * breathScale;
    const vy0 = -minSide * 0.022 * breathScale;

    const veinTargets = [
      { cx: 0.088, cy: -0.088, x1: 0.120, y1: -0.102 },
      { cx: 0.102, cy: -0.028, x1: 0.152, y1: -0.012 },
      { cx: 0.098, cy: 0.045, x1: 0.146, y1: 0.072 },
      { cx: 0.075, cy: 0.078, x1: 0.092, y1: 0.118 },
    ];

    ctx.strokeStyle = "rgba(241, 245, 249, 0.32)";
    ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
    for (let v = 0; v < veinTargets.length; v++) {
      const vt = veinTargets[v];
      ctx.beginPath();
      ctx.moveTo(vx0, vy0);
      ctx.quadraticCurveTo(
        side * minSide * vt.cx * breathScale,
        minSide * vt.cy * breathScale,
        side * minSide * vt.x1 * breathScale,
        minSide * vt.y1 * breathScale
      );
      ctx.stroke();
    }

    // Animated Luminous Purification Trim-Path along veins (Scene 1 -> 2)
    if (veinTrim > 0.01) {
      ctx.strokeStyle = "#ECFDF5";
      ctx.lineWidth = Math.max(1.8, minSide * 0.0044);
      for (let v = 0; v < veinTargets.length; v++) {
        const vt = veinTargets[v];
        const stagger = clamp01((veinTrim - v * 0.08) / 0.76);
        drawTrimQuad(
          vx0,
          vy0,
          side * minSide * vt.cx * breathScale,
          minSide * vt.cy * breathScale,
          side * minSide * vt.x1 * breathScale,
          minSide * vt.y1 * breathScale,
          stagger
        );
      }
    }

    ctx.restore();

    // Crisp outer lobe stroke
    traceLungLobe(side, breathScale);
    ctx.lineWidth = minSide * 0.0062;
    ctx.strokeStyle = lobeRimColor;
    ctx.stroke();
  }

  ctx.restore();

  ctx.restore();
}

function draw(ctx, time, width, height) {
  const t = time;
  const duration = 20;
  const sceneCount = 3;
  const loopT = t % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;

  const minSide = Math.min(width, height);
  const cycleNorm = loopT / duration;

  function clamp01(v) {
    return v < 0 ? 0 : v > 1 ? 1 : v;
  }

  function easeInOutSine(x) {
    return -(Math.cos(Math.PI * x) - 1) * 0.5;
  }

  function smoothRange(p, start, end) {
    if (end <= start) return p >= end ? 1 : 0;
    return easeInOutSine(clamp01((p - start) / (end - start)));
  }

  function lerp(a, b, k) {
    return a + (b - a) * k;
  }

  function lerpColor(c1, c2, k) {
    const tK = clamp01(k);
    const r = Math.round(c1[0] + (c2[0] - c1[0]) * tK);
    const g = Math.round(c1[1] + (c2[1] - c1[1]) * tK);
    const b = Math.round(c1[2] + (c2[2] - c1[2]) * tK);
    return "rgb(" + r + "," + g + "," + b + ")";
  }

  function roundedRectPath(x, y, w, h, r) {
    const rad = Math.min(r, w * 0.5, h * 0.5);
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + rad);
    ctx.lineTo(x + w, y + h - rad);
    ctx.quadraticCurveTo(x + w, y + h, x + w - rad, y + h);
    ctx.lineTo(x + rad, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - rad);
    ctx.lineTo(x, y + rad);
    ctx.quadraticCurveTo(x, y, x + rad, y);
    ctx.closePath();
  }

  ctx.save();
  ctx.lineCap = "round";
  ctx.lineJoin = "round";

  // 1. Clean Modern Dark Aesthetic Gradient Background (NO glow, NO edge stroke, NO corner brackets)
  const bgGrad = ctx.createLinearGradient(0, 0, width, height);
  bgGrad.addColorStop(0, "#120B0A");
  bgGrad.addColorStop(0.52, "#1D100E");
  bgGrad.addColorStop(1, "#2B1814");
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Seamless 3-Scene Choreography & Analytic Loop-Locked Turbine Rotation
  // Base 2 + boost 8 * 0.5 = 6 EXACT full revolutions over 20s!
  const revIntegral = 2 * cycleNorm + 8 * (0.5 * cycleNorm - Math.sin(Math.PI * 2 * cycleNorm) / (4 * Math.PI));
  const rotorAngle = revIntegral * Math.PI * 2;

  let magmaHeat = 0.25;
  let steamUp = 0.22;
  let powerOut = 0.22;
  let condenseDown = 0;

  if (currentScene === 0) {
    // Scene 0: Magma surges thermal energy into aquifer; steam pressure rises up left conduit
    magmaHeat = 0.25 + 0.75 * smoothRange(sceneProgress, 0.08, 0.78);
    steamUp = 0.22 + 0.78 * smoothRange(sceneProgress, 0.20, 0.96);
    powerOut = 0.22 + 0.36 * smoothRange(sceneProgress, 0.35, 0.98);
    condenseDown = 0;
  } else if (currentScene === 1) {
    // Scene 1: Turbine reaches peak rotational output; flanking energy bars fill cleanly
    magmaHeat = 1.0 - 0.15 * smoothRange(sceneProgress, 0.75, 1.0);
    steamUp = 1.0 - 0.20 * smoothRange(sceneProgress, 0.72, 1.0);
    powerOut = 0.58 + 0.42 * smoothRange(sceneProgress, 0.0, 0.68);
    condenseDown = smoothRange(sceneProgress, 0.65, 1.0);
  } else {
    // Scene 2: Cooled condensate water returns down right pipe into aquifer; smooth reset
    magmaHeat = 0.85 - 0.60 * smoothRange(sceneProgress, 0.28, 0.94);
    steamUp = 0.80 - 0.58 * smoothRange(sceneProgress, 0.22, 0.92);
    powerOut = 1.0 - 0.78 * smoothRange(sceneProgress, 0.32, 0.95);
    condenseDown = 1.0 - smoothRange(sceneProgress, 0.52, 0.90);
  }

  const wavePhase = cycleNorm * Math.PI * 2 * 6;

  // 3. Layout Coordinates (Vertically unified geothermal plant + earth cross-section)
  const cx = width * 0.5;
  const cy = height * 0.50;

  const geoCy = cy + minSide * 0.120;
  const geoR = minSide * 0.192; // spans y: cy - 0.072 to cy + 0.312

  const turbY = cy - minSide * 0.185;
  const turbR = minSide * 0.068;

  const manTop = cy - minSide * 0.105;
  const manBot = cy - minSide * 0.052;
  const manW = minSide * 0.220;
  const manR = minSide * 0.016;

  const pipeOffX = minSide * 0.068;
  const pipeTopY = manBot - minSide * 0.004;
  const pipeBotY = geoCy - minSide * 0.025; // Terminates cleanly inside aquifer zone

  // 4. Symmetrical Power Output Indicator Bars Flanking Top Turbine (Clean gap >= 0.068 * minSide from rotor)
  const barCount = 3;
  const barW = minSide * 0.013;
  const barGap = minSide * 0.009;
  const maxBarH = minSide * 0.066;

  for (let side = -1; side <= 1; side += 2) {
    for (let b = 0; b < barCount; b++) {
      const distX = turbR + minSide * 0.062 + b * (barW + barGap);
      const bx = side === 1 ? cx + distX : cx - distX - barW;
      const bh = maxBarH * (0.48 + 0.52 * ((b + 1) / barCount));
      const by = turbY + maxBarH * 0.5 - bh;

      roundedRectPath(bx, by, barW, bh, barW * 0.4);
      ctx.fillStyle = "#2A1B18";
      ctx.fill();

      const fillFrac = clamp01((powerOut - b / barCount) * barCount);
      if (fillFrac > 0.02) {
        const fh = bh * fillFrac;
        roundedRectPath(bx, by + (bh - fh), barW, fh, barW * 0.4);
        ctx.fillStyle = b === 2 ? "#FDE047" : "#FF9F0A";
        ctx.fill();
      }
    }
  }

  // 5. Lower Geological Cross-Section Circle (Strictly Clipped: Basalt Crust -> Aquifer -> Molten Magma)
  ctx.beginPath();
  ctx.arc(cx, geoCy, geoR, 0, Math.PI * 2);
  ctx.fillStyle = "#1E1210";
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, geoCy, geoR - minSide * 0.006, 0, Math.PI * 2);
  ctx.clip();

  // Top Basalt Rock Crust Band
  ctx.fillStyle = "#475569";
  ctx.fillRect(cx - geoR, geoCy - geoR, geoR * 2, geoR * 2);

  // Subtle flat-vector rock stratum band
  ctx.fillStyle = "#334155";
  ctx.fillRect(cx - geoR, geoCy - geoR * 0.72, geoR * 2, geoR * 0.34);

  // Middle Heated Aquifer Water Reservoir (y > geoCy - 0.072 * minSide)
  const aquiferTopY = geoCy - minSide * 0.068;
  const aqSteps = 32;
  ctx.beginPath();
  ctx.moveTo(cx - geoR, geoCy + geoR);
  for (let s = 0; s <= aqSteps; s++) {
    const u = s / aqSteps;
    const wx = cx - geoR + u * geoR * 2;
    const wy = aquiferTopY + Math.sin(u * Math.PI * 2 + wavePhase) * minSide * 0.0035;
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(cx + geoR, geoCy + geoR);
  ctx.closePath();

  const aqGrad = ctx.createLinearGradient(cx, aquiferTopY, cx, geoCy + minSide * 0.06);
  aqGrad.addColorStop(0, lerpColor([14, 116, 144], [34, 211, 238], magmaHeat));
  aqGrad.addColorStop(1, lerpColor([12, 74, 110], [6, 182, 212], magmaHeat));
  ctx.fillStyle = aqGrad;
  ctx.fill();

  // Lower Molten Magma Chamber (rises gently during thermal surge)
  const magmaBaseY = geoCy + minSide * (0.068 - 0.018 * magmaHeat);
  ctx.beginPath();
  ctx.moveTo(cx - geoR, geoCy + geoR);
  for (let s = 0; s <= aqSteps; s++) {
    const u = s / aqSteps;
    const wx = cx - geoR + u * geoR * 2;
    const wy = magmaBaseY + Math.sin(u * Math.PI * 2.2 - wavePhase) * minSide * 0.0055;
    ctx.lineTo(wx, wy);
  }
  ctx.lineTo(cx + geoR, geoCy + geoR);
  ctx.closePath();

  const magGrad = ctx.createLinearGradient(cx, magmaBaseY, cx, geoCy + geoR);
  magGrad.addColorStop(0, "#FF9F0A");
  magGrad.addColorStop(0.42, "#FF453A");
  magGrad.addColorStop(1, "#991B1B");
  ctx.fillStyle = magGrad;
  ctx.fill();

  // Crisp thermal lava crest highlight
  ctx.beginPath();
  for (let s = 0; s <= aqSteps; s++) {
    const u = s / aqSteps;
    const wx = cx - geoR + u * geoR * 2;
    const wy = magmaBaseY + Math.sin(u * Math.PI * 2.2 - wavePhase) * minSide * 0.0055;
    if (s === 0) ctx.moveTo(wx, wy);
    else ctx.lineTo(wx, wy);
  }
  ctx.lineWidth = Math.max(1.5, minSide * 0.003);
  ctx.strokeStyle = "#FDE047";
  ctx.stroke();

  // Magma convection bubbles inside pocket
  const magBubs = [
    { xOff: -0.055, speed: 3, phase: 0.1, r: 0.006 },
    { xOff: 0.010, speed: 4, phase: 0.55, r: 0.0075 },
    { xOff: 0.060, speed: 3, phase: 0.80, r: 0.005 },
  ];
  const mBubBot = geoCy + geoR - minSide * 0.025;
  const mBubTop = magmaBaseY + minSide * 0.018;
  if (mBubBot > mBubTop + minSide * 0.015) {
    for (let i = 0; i < magBubs.length; i++) {
      const b = magBubs[i];
      const prog = (cycleNorm * b.speed + b.phase) % 1;
      const by = lerp(mBubBot, mBubTop, prog);
      const bx = cx + b.xOff * minSide;
      const alpha = Math.sin(Math.PI * prog) * 0.85;
      if (alpha > 0.04) {
        ctx.beginPath();
        ctx.arc(bx, by, minSide * b.r, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(253, 224, 71, " + alpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // Subtle right-side flat-vector circular shading inside earth globe
  ctx.beginPath();
  ctx.arc(cx, geoCy, geoR, -Math.PI * 0.4, Math.PI * 0.55);
  ctx.lineWidth = geoR * 0.18;
  ctx.strokeStyle = "rgba(18, 11, 10, 0.24)";
  ctx.stroke();

  // --- LEFT STEAM RISER PIPE & RIGHT CONDENSATE RETURN PIPE (Drawn neatly inside cross-section & through crust!) ---
  const pipeOuterW = minSide * 0.024;
  const pipeInnerW = minSide * 0.012;

  for (let side = -1; side <= 1; side += 2) {
    const px = cx + side * pipeOffX;
    roundedRectPath(px - pipeOuterW * 0.5, pipeTopY - minSide * 0.02, pipeOuterW, pipeBotY - pipeTopY + minSide * 0.02, pipeOuterW * 0.4);
    ctx.fillStyle = "#64748B";
    ctx.fill();

    roundedRectPath(px - pipeInnerW * 0.5, pipeTopY - minSide * 0.02, pipeInnerW, pipeBotY - pipeTopY + minSide * 0.014, pipeInnerW * 0.4);
    ctx.fillStyle = "#0F172A";
    ctx.fill();
  }

  // Rising Steam Pills inside Left Pipe (x = cx - pipeOffX)
  if (steamUp > 0.02) {
    for (let k = 0; k < 3; k++) {
      const prog = (cycleNorm * 5 + k / 3) % 1;
      const py = lerp(pipeBotY - minSide * 0.010, pipeTopY + minSide * 0.010, prog);
      const alpha = Math.sin(Math.PI * prog) * steamUp * 0.92;
      if (alpha > 0.04) {
        ctx.beginPath();
        ctx.arc(cx - pipeOffX, py, minSide * 0.0046, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(103, 232, 249, " + alpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  // Descending Condensate Droplets inside Right Pipe (x = cx + pipeOffX)
  if (condenseDown > 0.02) {
    for (let k = 0; k < 2; k++) {
      const prog = (cycleNorm * 4 + k * 0.5) % 1;
      const py = lerp(pipeTopY + minSide * 0.010, pipeBotY - minSide * 0.010, prog);
      const alpha = Math.sin(Math.PI * prog) * condenseDown * 0.92;
      if (alpha > 0.04) {
        ctx.beginPath();
        ctx.arc(cx + pipeOffX, py, minSide * 0.0046, 0, Math.PI * 2);
        ctx.fillStyle = "rgba(56, 189, 248, " + alpha.toFixed(3) + ")";
        ctx.fill();
      }
    }
  }

  ctx.restore();

  // Outer Earth Cross-Section Rim
  ctx.beginPath();
  ctx.arc(cx, geoCy, geoR, 0, Math.PI * 2);
  ctx.lineWidth = minSide * 0.0075;
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  // 6. Upper Pipe Shaft Bridges (Between Manifold and Earth Rim)
  const bridgeTop = manBot - minSide * 0.004;
  const bridgeBot = geoCy - Math.sqrt(Math.max(0, geoR * geoR - pipeOffX * pipeOffX)) + minSide * 0.004;
  const pipeOuterW2 = minSide * 0.024;
  const pipeInnerW2 = minSide * 0.012;

  for (let side = -1; side <= 1; side += 2) {
    const px = cx + side * pipeOffX;
    ctx.fillStyle = "#64748B";
    ctx.fillRect(px - pipeOuterW2 * 0.5, bridgeTop, pipeOuterW2, bridgeBot - bridgeTop);
    ctx.fillStyle = "#0F172A";
    ctx.fillRect(px - pipeInnerW2 * 0.5, bridgeTop, pipeInnerW2, bridgeBot - bridgeTop);

    // Bridge steam / condensate dot continuity
    if (side === -1 && steamUp > 0.02) {
      for (let k = 0; k < 3; k++) {
        const prog = (cycleNorm * 5 + k / 3) % 1;
        const py = lerp(pipeBotY - minSide * 0.010, pipeTopY + minSide * 0.010, prog);
        if (py >= bridgeTop && py <= bridgeBot) {
          const alpha = Math.sin(Math.PI * prog) * steamUp * 0.92;
          ctx.beginPath();
          ctx.arc(px, py, minSide * 0.0046, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(103, 232, 249, " + alpha.toFixed(3) + ")";
          ctx.fill();
        }
      }
    }
    if (side === 1 && condenseDown > 0.02) {
      for (let k = 0; k < 2; k++) {
        const prog = (cycleNorm * 4 + k * 0.5) % 1;
        const py = lerp(pipeTopY + minSide * 0.010, pipeBotY - minSide * 0.010, prog);
        if (py >= bridgeTop && py <= bridgeBot) {
          const alpha = Math.sin(Math.PI * prog) * condenseDown * 0.92;
          ctx.beginPath();
          ctx.arc(px, py, minSide * 0.0046, 0, Math.PI * 2);
          ctx.fillStyle = "rgba(56, 189, 248, " + alpha.toFixed(3) + ")";
          ctx.fill();
        }
      }
    }
  }

  // 7. Surface Manifold Pedestal & Top Generator Turbine Housing
  // Vertical pylon connecting manifold to turbine hub
  const pylonW = minSide * 0.026;
  ctx.fillStyle = "#64748B";
  ctx.fillRect(cx - pylonW * 0.5, turbY, pylonW, manTop - turbY + minSide * 0.004);

  // Manifold Base Box
  roundedRectPath(cx - manW * 0.5, manTop, manW, manBot - manTop, manR);
  ctx.fillStyle = "#334155";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0052;
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  // Horizontal thermal energy indicator bar inside manifold
  const manInW = manW * 0.44;
  const manInH = minSide * 0.014;
  roundedRectPath(cx - manInW * 0.5, (manTop + manBot) * 0.5 - manInH * 0.5, manInW, manInH, manInH * 0.5);
  ctx.fillStyle = "#1E293B";
  ctx.fill();
  roundedRectPath(
    cx - manInW * 0.5,
    (manTop + manBot) * 0.5 - manInH * 0.5,
    manInW * powerOut,
    manInH,
    manInH * 0.5
  );
  ctx.fillStyle = lerpColor([103, 232, 249], [253, 224, 71], powerOut);
  ctx.fill();

  // 8. Top 6-Blade Steam Generator Turbine Wheel
  // Outer turbine ring casing
  ctx.beginPath();
  ctx.arc(cx, turbY, turbR, 0, Math.PI * 2);
  ctx.fillStyle = "#1E1615";
  ctx.fill();
  ctx.lineWidth = minSide * 0.0058;
  ctx.strokeStyle = "#CBD5E1";
  ctx.stroke();

  ctx.save();
  ctx.translate(cx, turbY);
  ctx.rotate(rotorAngle);
  for (let b = 0; b < 6; b++) {
    ctx.rotate(Math.PI / 3);
    roundedRectPath(-minSide * 0.007, -turbR * 0.80, minSide * 0.014, turbR * 0.62, minSide * 0.006);
    ctx.fillStyle = b % 2 === 0 ? "#F8FAFC" : "#94A3B8";
    ctx.fill();
  }
  ctx.restore();

  // Turbine center hub cap
  ctx.beginPath();
  ctx.arc(cx, turbY, minSide * 0.018, 0, Math.PI * 2);
  ctx.fillStyle = "#334155";
  ctx.fill();
  ctx.lineWidth = Math.max(1.5, minSide * 0.0038);
  ctx.strokeStyle = "#F8FAFC";
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(cx, turbY, minSide * 0.0085, 0, Math.PI * 2);
  ctx.fillStyle = lerpColor([103, 232, 249], [253, 224, 71], powerOut);
  ctx.fill();

  ctx.restore();
}
